                  <>
                    {bankAccounts.filter(a => a.is_primary).map(account => (
                      <div key={account.id} className="bg-muted/30 rounded-lg p-4">
                        <div className="flex items-start justify-between">
                          <div>
                            <div className="flex items-center gap-2 mb-1">
