  const loadRealMessages = async (chatId: string, silent = false, limit = 50): Promise<Message[]> => {
    try {
      if (silent) {
        console.log(`💬 [Polling] Carregando mensagens silenciosamente para: ${chatId} (limit: ${limit})`);
