import { Search, MessageSquare } from "lucide-react";
import { Input } from "@/components/ui/input";
import { ScrollArea } from "@/components/ui/scroll-area";
import { ConversationItem } from "./ConversationItem";
import { useState, useCallback } from "react";

interface Conversation {
  id: string;
  numero: string;
  nome: string;
  ultimaMensagem: string;
  timestamp: string;
  naoLidas: number;
  formStatus?: string;
  qualificationStatus?: string;
  pontuacao?: number;
  tags?: string[];
}

interface ConversationListProps {
  conversations: Conversation[];
  activeConversationId: string | null;
  onSelectConversation: (id: string) => void;
}

export function ConversationList({
  conversations,
  activeConversationId,
  onSelectConversation,
}: ConversationListProps) {
  const [searchTerm, setSearchTerm] = useState("");

  // 🎯 OTIMIZAÇÃO: useCallback para evitar re-renders desnecessários dos itens
  const handleConversationClick = useCallback((id: string) => {
    onSelectConversation(id);
  }, [onSelectConversation]);

  const filteredConversations = conversations.filter((conv) =>
    conv.nome.toLowerCase().includes(searchTerm.toLowerCase()) ||
    conv.numero.includes(searchTerm)
  );

  const totalUnread = conversations.reduce((acc, conv) => acc + conv.naoLidas, 0);

  return (
    <div className="flex h-full flex-col bg-card border-r border-border overflow-hidden">
      <header className="p-4 border-b border-border bg-card shrink-0">
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-2">
            <MessageSquare className="h-6 w-6 text-primary" />
            <h1 className="text-xl font-bold">Conversas</h1>
          </div>
          {totalUnread > 0 && (
            <div className="flex items-center justify-center min-w-[24px] h-6 px-2 rounded-full bg-unread text-white text-xs font-bold">
              {totalUnread}
            </div>
          )}
        </div>
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input
            placeholder="Buscar conversa..."
            className="pl-9"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </header>

      <div className="flex-1 overflow-hidden">
        <ScrollArea className="h-full">
          {filteredConversations.length === 0 ? (
            <div className="p-8 text-center animate-in fade-in-50 duration-500">
              <MessageSquare className="h-12 w-12 mx-auto text-muted-foreground/50 mb-3" />
              <p className="text-muted-foreground mb-2">
                {searchTerm ? "Nenhuma conversa encontrada" : "Nenhuma conversa carregada"}
              </p>
              {!searchTerm && (
                <p className="text-sm text-muted-foreground/70">
                  Clique no botão <span className="font-semibold text-primary">Atualizar</span> no topo da página para carregar suas conversas reais do WhatsApp
                </p>
              )}
            </div>
          ) : (
            filteredConversations.map((conversation) => (
              <ConversationItem
                key={conversation.id}
                conversation={conversation}
                isActive={activeConversationId === conversation.id}
                onClick={() => handleConversationClick(conversation.id)}
              />
            ))
          )}
        </ScrollArea>
      </div>
    </div>
  );
}

src/components/notion/blocks/QuoteBlock..content:
import { useRef, useState, useEffect } from 'react';
import { useNotionStore } from '@/stores/notionStore';
import { cn } from '@/lib/utils';
import type { BaseBlock } from '@/types/notion';
import { Button } from '@/components/ui/button';
import { Trash2, Quote } from 'lucide-react';

interface QuoteBlockProps {
  block: BaseBlock;
}

export const QuoteBlock = ({ block }: QuoteBlockProps) => {
  const { updateBlock, deleteBlock } = useNotionStore();
  const { isLocked } = useNotionStore(state => ({ isLocked: state.getCurrentPage()?.locked }));
  const contentRef = useRef<HTMLDivElement>(null);
  const [showActions, setShowActions] = useState(false);

  useEffect(() => {
    if (contentRef.current && document.activeElement !== contentRef.current) {
      const content = Array.isArray(block.content) ? block.content.join('') : (block.content ?? '');
      contentRef.current.textContent = content;
    }
  }, [block.id, block.content]);

  const handleContentChange = () => {
    if (isLocked) return;
    if (contentRef.current) {
      const newContent = contentRef.current.textContent || '';
      updateBlock(block.id, { content: newContent });
    }
  };

  return (
    <div
      className="relative group notion-hover rounded px-1"
      onMouseEnter={() => setShowActions(true)}
      onMouseLeave={() => setShowActions(false)}
    >
      <div className={cn(
        'absolute left-0 top-1 -translate-x-full flex items-center gap-1 pr-2 opacity-0 group-hover:opacity-100 transition-opacity',
        showActions && 'opacity-100'
      )}>
        <Button
          variant="ghost"
          size="sm"
          className="h-6 w-6 p-0"
          onClick={() => deleteBlock(block.id)}
          data-testid={`button-delete-quote-${block.id}`}
          disabled={isLocked}
        >
          <Trash2 className="h-3 w-3" />
        </Button>
      </div>

      <div className="flex gap-3 border-l-4 border-primary pl-4 py-1">
        <div
          ref={contentRef}
          contentEditable={!isLocked}
          suppressContentEditableWarning
          onInput={handleContentChange}
          className="flex-1 outline-none min-h-[28px] text-muted-foreground italic"
          data-placeholder="Citação vazia"
          data-testid={`text-quote-content-${block.id}`}
        />
      </div>
    </div>
  );
};

