    console.log('📝 Nome:', result[0].name);
    console.log('🎯 Total de campos:', completeFormTemplate.questions.length);

    process.exit(0);
  } catch (error) {
    console.error('❌ Erro ao criar template:', error);
    process.exit(1);
  }
}

addTemplate();

