import { Crown, TrendingUp, Users } from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";
import { GamificationLeague } from "@/features/revendedora/types/gamification";

interface LeagueBadgeProps {
  league: Pick<GamificationLeague, 'name' | 'icon' | 'color' | 'tier'>;
  position?: number | null;
  points?: number;
  className?: string;
}

const tierNames: Record<number, string> = {
  1: "Bronze",
  2: "Prata",
  3: "Ouro",
  4: "Diamante",
  5: "Mestre",
};

const tierColors: Record<number, string> = {
  1: "from-amber-700 to-amber-900",
  2: "from-gray-300 to-gray-500",
  3: "from-yellow-400 to-yellow-600",
  4: "from-cyan-300 to-blue-500",
  5: "from-purple-400 to-pink-500",
};

const tierBorderColors: Record<number, string> = {
  1: "border-amber-700",
  2: "border-gray-400",
  3: "border-yellow-500",
  4: "border-cyan-400",
  5: "border-purple-500",
};

export function LeagueBadge({ league, position, points, className }: LeagueBadgeProps) {
  const tierColor = tierColors[league.tier] || tierColors[1];
  const borderColor = tierBorderColors[league.tier] || tierBorderColors[1];

  const LeagueIcon = () => {
    const iconClass = "w-8 h-8";
    switch (league.icon) {
      case 'crown':
        return <Crown className={iconClass} />;
      case 'trending-up':
        return <TrendingUp className={iconClass} />;
      default:
        return <Users className={iconClass} />;
    }
  };

  return (
    <Card className={cn(
      "overflow-hidden border-2 transition-all hover:shadow-lg",
      borderColor,
      className
    )}>
      <CardContent className="p-4">
        <div className="flex items-center gap-4">
          <div className={cn(
            "w-14 h-14 rounded-full flex items-center justify-center bg-gradient-to-br text-white shadow-lg",
            tierColor
          )}>
            <LeagueIcon />
          </div>

          <div className="flex-1">
            <div className="flex items-center gap-2">
              <h3 className="font-bold text-lg">{league.name}</h3>
              <Badge 
                variant="secondary" 
                className={cn(
                  "text-xs",
                  league.tier >= 4 && "bg-gradient-to-r from-purple-500 to-pink-500 text-white border-0"
                )}
              >
                {tierNames[league.tier] || `Tier ${league.tier}`}
              </Badge>
            </div>

            <div className="flex items-center gap-4 mt-1 text-sm text-muted-foreground">
              {position !== null && position !== undefined && (
                <div className="flex items-center gap-1">
                  <TrendingUp className="w-4 h-4" />
                  <span>#{position}</span>
                </div>
              )}
              {points !== undefined && (
                <div className="flex items-center gap-1">
                  <span className="font-medium text-foreground">{points.toLocaleString()}</span>
                  <span>pontos</span>
                </div>
              )}
            </div>
          </div>

          {position !== null && position !== undefined && position <= 3 && (
            <div className={cn(
              "w-10 h-10 rounded-full flex items-center justify-center font-bold text-lg shadow-md",
              position === 1 && "bg-gradient-to-br from-yellow-300 to-yellow-500 text-yellow-900",
              position === 2 && "bg-gradient-to-br from-gray-200 to-gray-400 text-gray-700",
              position === 3 && "bg-gradient-to-br from-amber-500 to-amber-700 text-amber-100"
            )}>
              {position}
            </div>
          )}
        </div>
      </CardContent>
    </Card>
  );
}

src/components/CustomPluggyConnect.tsx.content:
import { useEffect, useState } from "react";
import { Loader2, CheckCircle2, XCircle, RefreshCw } from "lucide-react";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { PluggyConnect } from "react-pluggy-connect";
import type { Bank } from "@shared/schema";
import { fetchWithPluggyAuth } from "@/lib/pluggyClient";

interface CustomPluggyConnectProps {
  bank: Bank;
  cpf: string;
  onSuccess: () => void;
  onError: (error: string) => void;
  onBack: () => void;
}

export function CustomPluggyConnect({ bank, cpf, onSuccess, onError, onBack }: CustomPluggyConnectProps) {
  const [connectToken, setConnectToken] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [connectionSuccess, setConnectionSuccess] = useState(false);

  useEffect(() => {
    const fetchConnectToken = async () => {
      try {
        setIsLoading(true);
        setError(null);

        const response = await fetchWithPluggyAuth('/api/pluggy/connect-token');

        if (!response.ok) {
          const errorData = await response.json();
          throw new Error(errorData.error || 'Falha ao gerar token de conexão');
        }

        const data = await response.json();
        setConnectToken(data.accessToken);
      } catch (err) {
        const errorMessage = err instanceof Error ? err.message : 'Erro desconhecido';
        setError(errorMessage);
        onError(errorMessage);
      } finally {
        setIsLoading(false);
      }
    };

    fetchConnectToken();
  }, [onError]);

  // ⚠️ ⚠️ ⚠️ CRÍTICO - NÃO REMOVER ESTE CÓDIGO ⚠️ ⚠️ ⚠️
  // Este handler DEVE salvar o item no banco de dados após conexão bem-sucedida.
  // Sem este código, os bancos conectados NÃO aparecerão no dashboard!
  // Ver documentação completa em: PROBLEMA_PLUGGY_RESOLVIDO.md
  const handlePluggySuccess = async (itemData: any) => {
    console.log('Conexão estabelecida com sucesso:', itemData);

    // ⚠️ CRÍTICO: Salvar item no banco de dados PostgreSQL
    // Pluggy removeu o endpoint GET /items, então precisamos guardar localmente
    const item = itemData.item;
    if (item?.id) {
      try {
        await fetch('/api/items', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            id: item.id,
            connectorId: item.connector?.id || 0,
            connectorName: item.connector?.name || bank.name,
            status: item.status || 'UPDATED',
            executionStatus: item.executionStatus || 'SUCCESS',
          }),
        });
        console.log(`✅ Item ${item.id.substring(0, 8)}... salvo no banco de dados`);
      } catch (error) {
        console.error('Erro ao salvar item no banco:', error);
      }
    }

    setConnectionSuccess(true);
    onSuccess();
  };
  // ⚠️ FIM DO CÓDIGO CRÍTICO - NÃO MODIFICAR SEM LER PROBLEMA_PLUGGY_RESOLVIDO.md

  const handlePluggyError = (error: any) => {
    console.error('Erro no widget Pluggy:', error);
    const errorMessage = error?.message || 'Erro ao conectar com o banco';
    setError(errorMessage);
    onError(errorMessage);
  };

  const retry = () => {
    setError(null);
    setIsLoading(true);
    setConnectToken(null);
    setConnectionSuccess(false);

    const fetchConnectToken = async () => {
      try {
        const response = await fetchWithPluggyAuth('/api/pluggy/connect-token');

        if (!response.ok) {
          const errorData = await response.json();
          throw new Error(errorData.error || 'Falha ao gerar token de conexão');
        }

        const data = await response.json();
        setConnectToken(data.accessToken);
      } catch (err) {
        const errorMessage = err instanceof Error ? err.message : 'Erro desconhecido';
        setError(errorMessage);
        onError(errorMessage);
      } finally {
        setIsLoading(false);
      }
    };

    fetchConnectToken();
  };

  if (isLoading) {
    return (
      <div className="space-y-6">
        <div className="text-center">
          <h2 className="text-2xl font-semibold mb-2" data-testid="text-title">
            Preparando Conexão
          </h2>
          <p className="text-sm text-muted-foreground">
            Conectando com {bank.name}
          </p>
        </div>

        <Card className="p-8">
          <div className="flex flex-col items-center justify-center gap-4">
            <Loader2 className="h-12 w-12 animate-spin text-primary" />
            <p className="text-sm text-muted-foreground">Aguarde...</p>
          </div>
        </Card>
      </div>
    );
  }

  if (error) {
    return (
      <div className="space-y-6">
        <div className="text-center">
          <h2 className="text-2xl font-semibold mb-2 text-destructive" data-testid="text-title">
            Erro na Conexão
          </h2>
        </div>

        <Alert variant="destructive">
          <XCircle className="h-4 w-4" />
          <AlertDescription data-testid="text-error-message">
            {error}
          </AlertDescription>
        </Alert>

        <div className="flex gap-3">
          <Button
            variant="outline"
            onClick={onBack}
            className="flex-1 h-12"
            data-testid="button-back"
          >
            Voltar
          </Button>
          <Button
            onClick={retry}
            className="flex-1 h-12 gap-2"
            data-testid="button-retry"
          >
            <RefreshCw className="h-4 w-4" />
            Tentar Novamente
          </Button>
        </div>
      </div>
    );
  }

  if (connectionSuccess) {
    return (
      <div className="space-y-6">
        <div className="text-center">
          <h2 className="text-2xl font-semibold mb-2 text-chart-2" data-testid="text-title">
            Conexão Estabelecida!
          </h2>
          <p className="text-sm text-muted-foreground">
            Sua conta foi conectada com sucesso
          </p>
        </div>

        <Card className="p-8 border-chart-2">
          <div className="flex flex-col items-center justify-center gap-4">
            <div className="h-16 w-16 rounded-full bg-chart-2/10 flex items-center justify-center">
              <CheckCircle2 className="h-8 w-8 text-chart-2" />
            </div>
            <p className="text-center font-medium" data-testid="text-success-message">
              Credenciais do Pluggy.ai funcionando corretamente!
            </p>
          </div>
        </Card>

        <Button
          onClick={onBack}
          variant="outline"
          className="w-full h-12"
          data-testid="button-connect-another"
        >
          Conectar Outro Banco
        </Button>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="text-center">
        <h2 className="text-2xl font-semibold mb-2" data-testid="text-title">
          Conectar ao {bank.name}
        </h2>
        <p className="text-sm text-muted-foreground">
          Siga as instruções no widget abaixo
        </p>
      </div>

      <Card className="p-4">
        {connectToken && (
          <PluggyConnect
            connectToken={connectToken}
            includeSandbox={true}
            connectorIds={[bank.id]}
            theme="dark"
            onSuccess={handlePluggySuccess}
            onError={handlePluggyError}
          />
        )}
      </Card>

      <Button
        variant="outline"
        onClick={onBack}
        className="w-full h-12"
        data-testid="button-back"
      >
        Voltar
      </Button>
    </div>
  );
}

