import { useRef, useState, useEffect } from 'react';
import { useNotionStore } from '@/stores/notionStore';
import type { BaseBlock } from '@/types/notion';
import { Button } from '@/components/ui/button';
import { Link as LinkIcon, Trash2 } from 'lucide-react';

interface LinkToPageBlockProps {
  block: BaseBlock;
}

export const LinkToPageBlock = ({ block }: LinkToPageBlockProps) => {
  const { updateBlock, deleteBlock } = useNotionStore();
  const contentRef = useRef<HTMLDivElement>(null);
  const [showActions, setShowActions] = useState(false);

  useEffect(() => {
    if (contentRef.current && document.activeElement !== contentRef.current) {
      const content = Array.isArray(block.content) ? block.content.join('') : (block.content || '');
      contentRef.current.textContent = content;
    }
  }, [block.id, block.content]);

  const handleContentChange = () => {
    if (contentRef.current) {
      const newContent = contentRef.current.textContent || '';
      updateBlock(block.id, { content: newContent });
    }
  };

  return (
    <div
      className="relative group notion-hover rounded px-1"
      onMouseEnter={() => setShowActions(true)}
      onMouseLeave={() => setShowActions(false)}
    >
      <div className="inline-flex items-center gap-2 py-1 px-2 border border-border rounded hover:bg-accent transition-colors">
        <LinkIcon className="h-4 w-4 text-blue-500 flex-shrink-0" />
        <div
          ref={contentRef}
          contentEditable
          suppressContentEditableWarning
          onInput={handleContentChange}
          className="outline-none min-w-[100px] text-blue-600 dark:text-blue-400"
          data-placeholder="Link para página"
          data-testid={`link-page-${block.id}`}
        />
        {showActions && (
          <Button
            variant="ghost"
            size="sm"
            className="h-5 w-5 p-0 opacity-0 group-hover:opacity-100"
            onClick={() => deleteBlock(block.id)}
          >
            <Trash2 className="h-3 w-3" />
          </Button>
        )}
      </div>
    </div>
  );
};

src/features/formularios-platform/lib/qu.content:
import { QueryClient } from "@tanstack/react-query";

async function handleResponse(response: Response) {
  if (response.status === 204) {
    return null;
  }

  const data = await response.json();

  if (!response.ok) {
    throw new Error(data.error || `Request failed: ${response.statusText}`);
  }

  return data;
}

const defaultFetcher = async ({ queryKey }: { queryKey: string[] }) => {
  const headers: Record<string, string> = {};

  const config = getSupabaseConfig();
  if (config) {
    headers['x-supabase-url'] = config.url;
    headers['x-supabase-key'] = config.anonKey;
  }

  const response = await fetch(queryKey[0], {
    credentials: 'include',
    headers,
  });
  return handleResponse(response);
};

function getSupabaseConfig() {
  const url = localStorage.getItem('supabase_url');
  const anonKey = localStorage.getItem('supabase_anon_key');

  if (!url || !anonKey) return null;

  return { url, anonKey };
}

export const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      queryFn: defaultFetcher,
      staleTime: 1000 * 60,
      retry: false,
    },
  },
});

type RequestMethod = "GET" | "POST" | "PATCH" | "PUT" | "DELETE";

export async function apiRequest(
  url: string,
  method: RequestMethod = "GET",
  data?: any
) {
  const headers: Record<string, string> = {
    "Content-Type": "application/json",
  };

  // Add Supabase headers if configured
  const config = getSupabaseConfig();
  if (config) {
    headers['x-supabase-url'] = config.url;
    headers['x-supabase-key'] = config.anonKey;
    console.log('🔑 [apiRequest] Enviando credenciais Supabase nos headers');
  }

  const options: RequestInit = {
    method,
    headers,
  };

  if (data) {
    options.body = JSON.stringify(data);
  }

  const response = await fetch(url, options);
  return handleResponse(response);
}

src/features/revendedora/services/Stripe.content:
import { loadStripe, Stripe, StripeElements } from '@stripe/stripe-js';

let stripePromise: Promise<Stripe | null> | null = null;
let cachedPublishableKey: string | null = null;

export interface CreatePaymentIntentRequest {
  productId: string;
  resellerId: string;
  companyId: string;
  paymentMethod: 'pix' | 'cartao';
  customerData: {
    name?: string;
    email?: string;
    phone?: string;
  };
}

export interface CreatePaymentIntentResponse {
  success: boolean;
  saleId: string;
  paymentIntentId: string;
  clientSecret: string;
  amount: number;
  pix?: {
    qrcodeUrl: string;
    qrcodeText: string;
    expiresAt: string;
  };
  split: {
    total: number;
    resellerAmount: number;
    companyAmount: number;
    resellerPercentage: number;
  };
}

async function getStripePublishableKey(): Promise<string | null> {
  if (cachedPublishableKey) {
    return cachedPublishableKey;
  }

  const maxRetries = 3;
  let lastError: any = null;

  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      const response = await fetch('/api/stripe/publishable-key');
      if (response.ok) {
        const data = await response.json();
        if (data.publishableKey) {
          cachedPublishableKey = data.publishableKey;
          console.log('[Stripe] Using publishable key from API');
          return cachedPublishableKey;
        }
      }
    } catch (error) {
      lastError = error;
      console.warn(`[Stripe] Attempt ${attempt + 1}/${maxRetries} failed:`, error);
      if (attempt < maxRetries - 1) {
        await new Promise(resolve => setTimeout(resolve, 1000 * (attempt + 1)));
      }
    }
  }

  if (lastError) {
    console.warn('[Stripe] All API attempts failed:', lastError);
  }

  const envKey = import.meta.env.VITE_STRIPE_PUBLISHABLE_KEY;
  if (envKey) {
    console.log('[Stripe] Using VITE_STRIPE_PUBLISHABLE_KEY environment variable');
    cachedPublishableKey = envKey;
    return cachedPublishableKey;
  }

  console.error('[Stripe] No publishable key available. Please configure STRIPE_PUBLISHABLE_KEY secret.');
  return null;
}

export class StripeService {
  static async getStripe(): Promise<Stripe | null> {
    if (!stripePromise) {
      const publishableKey = await getStripePublishableKey();

      if (!publishableKey) {
        console.error('[Stripe] No publishable key available');
        return null;
      }

      stripePromise = loadStripe(publishableKey);
    }

    return stripePromise;
  }

  /**
   * Cria um Payment Intent via API local
   */
  static async createPaymentIntent(
    request: CreatePaymentIntentRequest
  ): Promise<CreatePaymentIntentResponse> {
    try {
      const response = await fetch('/api/payments/create-intent', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(request),
      });

      const data = await response.json();

      if (!response.ok || !data.success) {
        console.error('Erro ao criar payment intent:', data);
        throw new Error(data.error || 'Erro ao criar payment intent');
      }

      return data;
    } catch (error: any) {
      console.error('Erro ao criar payment intent:', error);
      throw new Error(error.message || 'Erro ao criar payment intent');
    }
  }

  /**
   * Confirma pagamento com cartão
   */
  static async confirmCardPayment(
    clientSecret: string,
    elements: StripeElements,
    cardElement: any
  ): Promise<{ success: boolean; error?: string }> {
    const stripe = await this.getStripe();

    if (!stripe) {
      return { success: false, error: 'Stripe não inicializado' };
    }

    const { error, paymentIntent } = await stripe.confirmCardPayment(clientSecret, {
      payment_method: {
        card: cardElement,
      },
    });

    if (error) {
      console.error('Erro ao confirmar pagamento:', error);
      return { success: false, error: error.message };
    }

    if (paymentIntent?.status === 'succeeded') {
      return { success: true };
    }

    return { success: false, error: 'Pagamento não concluído' };
  }

  /**
   * Confirma pagamento PIX (apenas retorna client_secret, confirmação via webhook)
   */
  static async confirmPixPayment(
    clientSecret: string
  ): Promise<{ success: boolean; error?: string }> {
    // Para PIX, o pagamento é confirmado via webhook quando o cliente paga
    // Aqui apenas retornamos sucesso para que o QR code possa ser exibido
    return { success: true };
  }

  /**
   * Verifica status de um Payment Intent
   */
  static async retrievePaymentIntent(paymentIntentId: string): Promise<any> {
    const stripe = await this.getStripe();

    if (!stripe) {
      throw new Error('Stripe não inicializado');
    }

    return await stripe.retrievePaymentIntent(paymentIntentId);
  }
}

