  const createHeadingElement = (): FormElement => ({
    type: 'heading',
    id: `h-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
    text: 'Título da Seção',
    level: 2,
    style: {
      alignment: 'left',
      fontSize: '2xl',
      fontWeight: 'bold'
