import { useState, useMemo, useRef } from "react";
import { Button } from "@/features/produto/components/ui/button";
import { Input } from "@/features/produto/components/ui/input";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/features/produto/components/ui/table";
import { Sheet, SheetContent, SheetDescription, SheetHeader, SheetTitle, SheetTrigger } from "@/features/produto/components/ui/sheet";
import { Label } from "@/features/produto/components/ui/label";
import { Plus, MoreHorizontal, Upload, Download, Filter, Edit, Eye, Printer, Package } from "lucide-react";
import { toast } from "sonner";
import type { Category } from "@/pages/Index";
import { exportToExcel, importFromExcel } from "@/features/produto/lib/exportUtils";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/features/produto/components/ui/dropdown-menu";

interface CategoryListProps {
  categories: Category[];
  onAddCategory: () => void;
  onImportCategories: (categories: Category[]) => void;
  onEdit: (category: Category) => void;
}

export const CategoryList = ({ categories, onAddCategory, onImportCategories, onEdit }: CategoryListProps) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [filterSheetOpen, setFilterSheetOpen] = useState(false);
  const [filters, setFilters] = useState({
    nome: "",
    etiqueta: "",
    etiquetaCustomizada: "",
  });

  const clearFilters = () => {
    setFilters({
      nome: "",
      etiqueta: "",
      etiquetaCustomizada: "",
    });
  };

  const hasActiveFilters = filters.nome || filters.etiqueta || filters.etiquetaCustomizada;

  const handleExportExcel = () => {
    if (filteredCategories.length === 0) {
      toast.error("Nenhuma categoria para exportar");
      return;
    }

    const dataToExport = filteredCategories.map(c => ({
      'Categoria': c.nome,
      'Etiqueta': c.etiqueta,
      'Etiqueta Customizada': c.etiquetaCustomizada,
      'Produtos Vinculados': c.produtosVinculados
    }));

    exportToExcel(dataToExport, 'categorias', 'Categorias');
    toast.success(`${filteredCategories.length} categorias exportadas`);
  };

  const handleImportExcel = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    try {
      const data = await importFromExcel<any>(file);

      if (data.length === 0) {
        toast.error("Arquivo vazio");
        return;
      }

      const importedCategories: Category[] = data.map((row: any, index: number) => ({
        id: String(Date.now() + index),
        nome: row['Categoria'] || row.nome || '',
        etiqueta: row['Etiqueta'] || row.etiqueta || '',
        etiquetaCustomizada: row['Etiqueta Customizada'] || row.etiquetaCustomizada || '',
        produtosVinculados: Number(row['Produtos Vinculados'] || row.produtosVinculados || 0)
      }));

      onImportCategories(importedCategories);
      toast.success(`${importedCategories.length} categorias importadas`);

      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }
    } catch (error) {
      console.error('Erro ao importar:', error);
      toast.error("Erro ao importar arquivo");
    }
  };

  const filteredCategories = useMemo(() => {
    return categories.filter((category) => {
      const matchNome = category.nome.toLowerCase().includes(filters.nome.toLowerCase());
      const matchEtiqueta = category.etiqueta.toLowerCase().includes(filters.etiqueta.toLowerCase());
      const matchEtiquetaCustom = category.etiquetaCustomizada.toLowerCase().includes(filters.etiquetaCustomizada.toLowerCase());

      return matchNome && matchEtiqueta && matchEtiquetaCustom;
    });
  }, [categories, filters]);

  return (
    <div className="flex-1 flex flex-col bg-background">
      <div className="p-6">
        <div className="flex items-center justify-between mb-6">
          <h2 className="text-xl font-semibold text-foreground">Lista de Categorias</h2>

          <div className="flex items-center gap-2">
            <input
              ref={fileInputRef}
              type="file"
              accept=".xlsx,.xls,.csv"
              onChange={handleImportExcel}
              className="hidden"
            />
            <Button 
              variant="outline" 
              className="gap-2"
              onClick={() => fileInputRef.current?.click()}
            >
              <Upload className="w-4 h-4" />
              Importar
            </Button>
            <Button 
              variant="outline" 
              className="gap-2"
              onClick={handleExportExcel}
            >
              <Download className="w-4 h-4" />
              Exportar
            </Button>
            <Button 
              className="bg-primary hover:bg-primary/90"
              onClick={onAddCategory}
            >
              <Plus className="w-4 h-4 mr-2" />
              Adicionar
            </Button>
            <Sheet open={filterSheetOpen} onOpenChange={setFilterSheetOpen}>
              <SheetTrigger asChild>
                <Button variant="outline" className="gap-2">
                  <Filter className="w-4 h-4" />
                  Filtro
                  {hasActiveFilters && (
                    <span className="ml-1 h-2 w-2 rounded-full bg-primary" />
                  )}
                </Button>
              </SheetTrigger>
              <SheetContent>
                <SheetHeader>
                  <SheetTitle>Filtros</SheetTitle>
                  <SheetDescription>
                    Filtre as categorias pelos campos abaixo
                  </SheetDescription>
                </SheetHeader>
                <div className="mt-6 space-y-4">
                  <div className="space-y-2">
                    <Label htmlFor="filter-nome">Categoria</Label>
                    <Input
                      id="filter-nome"
                      placeholder="Buscar por nome da categoria..."
                      value={filters.nome}
                      onChange={(e) => setFilters(prev => ({ ...prev, nome: e.target.value }))}
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="filter-etiqueta">Etiqueta</Label>
                    <Input
                      id="filter-etiqueta"
                      placeholder="Buscar por etiqueta..."
                      value={filters.etiqueta}
                      onChange={(e) => setFilters(prev => ({ ...prev, etiqueta: e.target.value }))}
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="filter-etiquetaCustomizada">Etiqueta Customizada</Label>
                    <Input
                      id="filter-etiquetaCustomizada"
                      placeholder="Buscar por etiqueta customizada..."
                      value={filters.etiquetaCustomizada}
                      onChange={(e) => setFilters(prev => ({ ...prev, etiquetaCustomizada: e.target.value }))}
                    />
                  </div>
                  {hasActiveFilters && (
                    <Button 
                      variant="outline" 
                      className="w-full"
                      onClick={clearFilters}
                    >
                      Limpar Filtros
                    </Button>
                  )}
                </div>
              </SheetContent>
            </Sheet>
          </div>
        </div>

        <div className="border rounded-lg overflow-hidden bg-card">
          <Table>
            <TableHeader>
              <TableRow className="bg-muted/50">
                <TableHead>Categoria</TableHead>
                <TableHead>Etiqueta</TableHead>
                <TableHead>Etiqueta Customizada</TableHead>
                <TableHead>Produtos Vinculados</TableHead>
                <TableHead className="w-24">Ações</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {filteredCategories.map((category) => (
                <TableRow key={category.id} className="hover:bg-muted/50">
                  <TableCell className="font-medium">{category.nome}</TableCell>
                  <TableCell>{category.etiqueta}</TableCell>
                  <TableCell>{category.etiquetaCustomizada}</TableCell>
                  <TableCell>{category.produtosVinculados}</TableCell>
                  <TableCell>
                    <Button 
                      variant="ghost" 
                      size="icon" 
                      className="h-8 w-8"
                      onClick={() => onEdit(category)}
                      title="Editar Categoria"
                    >
                      <Edit className="w-4 h-4" />
                    </Button>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </div>

        <div className="flex items-center justify-end gap-2 mt-4 text-sm text-muted-foreground">
          <span>Linhas por página:</span>
          <select className="border rounded px-2 py-1">
            <option>15</option>
            <option>30</option>
            <option>50</option>
          </select>
          <span>1-8 de 8</span>
          <div className="flex gap-1">
            <Button variant="outline" size="sm" disabled>«</Button>
            <Button variant="outline" size="sm" disabled>‹</Button>
            <Button variant="outline" size="sm">1</Button>
            <Button variant="outline" size="sm" disabled>›</Button>
            <Button variant="outline" size="sm" disabled>»</Button>
          </div>
        </div>
      </div>
    </div>
  );
};

server/formularios/services/leadTracking.content:
import { db } from '../db.js';
import { leads, formularioSessoes, leadHistorico, formSubmissions, forms } from "../../../shared/db-schema";
import { eq, and, desc } from 'drizzle-orm';
import crypto from 'crypto';
import { normalizePhone } from '../utils/phoneNormalizer.js';

export class LeadTrackingService {

  async criarSessaoFormulario(
    telefone: string, 
    formularioId: string, 
    diasExpiracao: number = 7
  ) {
    try {
      const telefoneNormalizado = normalizePhone(telefone);

      let lead = await db.select()
        .from(leads)
        .where(eq(leads.telefoneNormalizado, telefoneNormalizado))
        .limit(1)
        .then(rows => rows[0] || null);

      const agora = new Date();
      const expiresAt = new Date();
      expiresAt.setDate(expiresAt.getDate() + diasExpiracao);

      const token = crypto.randomBytes(32).toString('hex');
      const sessaoId = `sessao_${Date.now()}_${crypto.randomBytes(4).toString('hex')}`;
      const formularioUrl = `/formulario/f/${token}`;

      if (!lead) {
        const [novoLead] = await db.insert(leads).values({
          telefone: telefone,
          telefoneNormalizado: telefoneNormalizado,
          origem: 'whatsapp',
          formularioId: formularioId,
          formularioEnviado: true,
          formularioEnviadoEm: agora,
          formularioUrl: formularioUrl,
        }).returning();
        lead = novoLead;
      } else {
        const [leadAtualizado] = await db.update(leads)
          .set({
            formularioId: formularioId,
            formularioEnviado: true,
            formularioEnviadoEm: agora,
            formularioUrl: formularioUrl,
            updatedAt: agora,
          })
          .where(eq(leads.id, lead.id))
          .returning();
        lead = leadAtualizado;
      }

      const [sessao] = await db.insert(formularioSessoes).values({
        leadId: lead.id,
        token: token,
        sessaoId: sessaoId,
        expiresAt: expiresAt,
        aberto: false,
        totalAcessos: 0,
        progressoPercentual: 0,
        paginaAtual: 1,
        camposPreenchidos: {},
        ipAddresses: [],
        userAgents: [],
      }).returning();

      await db.insert(leadHistorico).values({
        leadId: lead.id,
        tipoEvento: 'formulario_enviado',
        descricao: 'Formulário enviado via WhatsApp',
        dados: { formularioId, sessaoId, token, formularioUrl },
      });

      console.log(`✅ Sessão criada para ${telefoneNormalizado}: token=${token}`);

      return {
        lead,
        sessao,
        url: formularioUrl,
        token,
        expiresAt,
      };
    } catch (error) {
      console.error('❌ Erro ao criar sessão de formulário:', error);
      throw error;
    }
  }

  async validarTokenERegistrarAbertura(
    token: string, 
    ip: string, 
    userAgent: string
  ) {
    try {
      const sessao = await db.select()
        .from(formularioSessoes)
        .where(eq(formularioSessoes.token, token))
        .limit(1)
        .then(rows => rows[0] || null);

      if (!sessao) {
        return { valido: false, erro: 'Token inválido' };
      }

      if (sessao.expiresAt && new Date(sessao.expiresAt) < new Date()) {
        return { valido: false, erro: 'Token expirado' };
      }

      if (sessao.concluido) {
        return { valido: false, erro: 'Formulário já concluído' };
      }

      const agora = new Date();
      const primeiraAbertura = !sessao.aberto;

      const lead = await db.select()
        .from(leads)
        .where(eq(leads.id, sessao.leadId))
        .limit(1)
        .then(rows => rows[0]);

      const ipAddresses = Array.isArray(sessao.ipAddresses) ? sessao.ipAddresses : [];
      const userAgents = Array.isArray(sessao.userAgents) ? sessao.userAgents : [];

      if (!ipAddresses.includes(ip)) {
        ipAddresses.push(ip);
      }
      if (!userAgents.includes(userAgent)) {
        userAgents.push(userAgent);
      }

      if (primeiraAbertura) {
        await db.update(leads)
          .set({
            formularioAberto: true,
            formularioAbertoEm: agora,
            formularioVisualizacoes: 1,
            updatedAt: agora,
          })
          .where(eq(leads.id, sessao.leadId));

        await db.update(formularioSessoes)
          .set({
            aberto: true,
            primeiraAberturaEm: agora,
            ultimaAtividadeEm: agora,
            totalAcessos: (sessao.totalAcessos || 0) + 1,
            ipAddresses: ipAddresses,
            userAgents: userAgents,
            updatedAt: agora,
          })
          .where(eq(formularioSessoes.id, sessao.id));

        await db.insert(leadHistorico).values({
          leadId: sessao.leadId,
          tipoEvento: 'formulario_aberto',
          descricao: 'Lead abriu o formulário pela primeira vez',
          dados: { ip, userAgent },
          ipAddress: ip,
        });

        console.log(`👀 Lead abriu formulário pela primeira vez: ${sessao.sessaoId}`);
      } else {
        const novasVisualizacoes = (lead.formularioVisualizacoes || 1) + 1;

        await db.update(leads)
          .set({
            formularioVisualizacoes: novasVisualizacoes,
            updatedAt: agora,
          })
          .where(eq(leads.id, sessao.leadId));

        await db.update(formularioSessoes)
          .set({
            ultimaAtividadeEm: agora,
            totalAcessos: (sessao.totalAcessos || 0) + 1,
            ipAddresses: ipAddresses,
            userAgents: userAgents,
            updatedAt: agora,
          })
          .where(eq(formularioSessoes.id, sessao.id));

        console.log(`🔄 Lead acessou formulário novamente: ${sessao.sessaoId} (${novasVisualizacoes}x)`);
      }

      const leadAtualizado = await db.select()
        .from(leads)
        .where(eq(leads.id, sessao.leadId))
        .limit(1)
        .then(rows => rows[0]);

      const sessaoAtualizada = await db.select()
        .from(formularioSessoes)
        .where(eq(formularioSessoes.id, sessao.id))
        .limit(1)
        .then(rows => rows[0]);

      return {
        valido: true,
        lead: leadAtualizado,
        sessao: sessaoAtualizada,
        primeiraAbertura,
        dadosPreenchidos: {
          telefone: leadAtualizado.telefoneNormalizado || leadAtualizado.telefone || '',
          nome: leadAtualizado.nome || '',
          email: leadAtualizado.email || '',
        },
      };
    } catch (error) {
      console.error('❌ Erro ao validar token e registrar abertura:', error);
      throw error;
    }
  }

  async registrarInicioPreenchimento(
    token: string, 
    campoInicial: string, 
    valor: any
  ) {
    try {
      const sessao = await db.select()
        .from(formularioSessoes)
        .where(eq(formularioSessoes.token, token))
        .limit(1)
        .then(rows => rows[0] || null);

      if (!sessao) {
        throw new Error('Sessão não encontrada');
      }

      const lead = await db.select()
        .from(leads)
        .where(eq(leads.id, sessao.leadId))
        .limit(1)
        .then(rows => rows[0]);

      const agora = new Date();
      const primeiraVez = !lead.formularioIniciado;

      const camposPreenchidos = sessao.camposPreenchidos || {};
      camposPreenchidos[campoInicial] = valor;

      await db.update(formularioSessoes)
        .set({
          camposPreenchidos: camposPreenchidos,
          ultimaAtividadeEm: agora,
          updatedAt: agora,
        })
        .where(eq(formularioSessoes.id, sessao.id));

      if (primeiraVez) {
        await db.update(leads)
          .set({
            formularioIniciado: true,
            formularioIniciadoEm: agora,
            updatedAt: agora,
          })
          .where(eq(leads.id, sessao.leadId));

        await db.insert(leadHistorico).values({
          leadId: sessao.leadId,
          tipoEvento: 'formulario_iniciado',
          descricao: 'Lead iniciou o preenchimento do formulário',
          dados: { campoInicial, valor },
        });

        console.log(`✏️ Lead iniciou preenchimento: ${sessao.sessaoId}`);
      }

      return { sucesso: true };
    } catch (error) {
      console.error('❌ Erro ao registrar início de preenchimento:', error);
      throw error;
    }
  }

  async atualizarProgresso(
    token: string, 
    camposPreenchidos: object, 
    totalCampos: number
  ) {
    try {
      const sessao = await db.select()
        .from(formularioSessoes)
        .where(eq(formularioSessoes.token, token))
        .limit(1)
        .then(rows => rows[0] || null);

      if (!sessao) {
        throw new Error('Sessão não encontrada');
      }

      const camposCount = Object.keys(camposPreenchidos).length;
      const progressoPercentual = Math.round((camposCount / totalCampos) * 100);

      await db.update(formularioSessoes)
        .set({
          camposPreenchidos: camposPreenchidos,
          progressoPercentual: progressoPercentual,
          ultimaAtividadeEm: new Date(),
          updatedAt: new Date(),
        })
        .where(eq(formularioSessoes.id, sessao.id));

      console.log(`📊 Progresso atualizado: ${progressoPercentual}% (${camposCount}/${totalCampos})`);

      return {
        progresso: progressoPercentual,
        camposPreenchidos: camposCount,
        totalCampos,
      };
    } catch (error) {
      console.error('❌ Erro ao atualizar progresso:', error);
      throw error;
    }
  }

  async finalizarFormulario(
    token: string, 
    respostas: object, 
    metadados: { ip: string; userAgent: string; formularioId: string }
  ) {
    try {
      const sessao = await db.select()
        .from(formularioSessoes)
        .where(eq(formularioSessoes.token, token))
        .limit(1)
        .then(rows => rows[0] || null);

      if (!sessao) {
        throw new Error('Sessão não encontrada');
      }

      const lead = await db.select()
        .from(leads)
        .where(eq(leads.id, sessao.leadId))
        .limit(1)
        .then(rows => rows[0]);

      const formulario = await db.select()
        .from(forms)
        .where(eq(forms.id, metadados.formularioId))
        .limit(1)
        .then(rows => rows[0]);

      if (!formulario) {
        throw new Error('Formulário não encontrado');
      }

      let pontuacao = 0;
      const questions = Array.isArray(formulario.questions) ? formulario.questions : [];

      for (const question of questions) {
        const resposta = respostas[question.id];
        if (resposta && question.options) {
          const opcaoSelecionada = question.options.find((opt: any) => opt.text === resposta);
          if (opcaoSelecionada && opcaoSelecionada.score) {
            pontuacao += opcaoSelecionada.score;
          }
        }
      }

      const passou = pontuacao >= (formulario.passingScore || 0);
      const statusQualificacao = passou ? 'aprovado' : 'reprovado';

      let tempoPreenchimento = null;
      if (lead.formularioIniciadoEm) {
        const inicio = new Date(lead.formularioIniciadoEm);
        const fim = new Date();
        tempoPreenchimento = Math.round((fim.getTime() - inicio.getTime()) / 1000);
      }

      const [submission] = await db.insert(formSubmissions).values({
        formId: metadados.formularioId,
        answers: respostas,
        totalScore: pontuacao,
        passed: passou,
        contactPhone: lead.telefone,
        contactName: lead.nome,
        contactEmail: lead.email,
      }).returning();

      const agora = new Date();
      await db.update(leads)
        .set({
          formularioConcluido: true,
          formularioConcluidoEm: agora,
          pontuacao: pontuacao,
          statusQualificacao: statusQualificacao,
          submissionId: submission.id,
          updatedAt: agora,
        })
        .where(eq(leads.id, sessao.leadId));

      await db.update(formularioSessoes)
        .set({
          concluido: true,
          progressoPercentual: 100,
          ultimaAtividadeEm: agora,
          updatedAt: agora,
        })
        .where(eq(formularioSessoes.id, sessao.id));

      await db.insert(leadHistorico).values({
        leadId: sessao.leadId,
        tipoEvento: 'formulario_concluido',
        descricao: `Lead concluiu o formulário - ${statusQualificacao.toUpperCase()}`,
        dados: { 
          pontuacao, 
          passou, 
          submissionId: submission.id,
          tempoPreenchimento,
        },
        ipAddress: metadados.ip,
      });

      if (passou) {
        await db.insert(leadHistorico).values({
          leadId: sessao.leadId,
          tipoEvento: 'lead_aprovado',
          descricao: `Lead aprovado com ${pontuacao} pontos`,
          dados: { pontuacao },
        });
      } else {
        await db.insert(leadHistorico).values({
          leadId: sessao.leadId,
          tipoEvento: 'lead_reprovado',
          descricao: `Lead reprovado com ${pontuacao} pontos`,
          dados: { pontuacao },
        });
      }

      console.log(`🎯 Formulário finalizado: ${statusQualificacao.toUpperCase()} (${pontuacao} pts)`);

      const leadAtualizado = await db.select()
        .from(leads)
        .where(eq(leads.id, sessao.leadId))
        .limit(1)
        .then(rows => rows[0]);

      return {
        lead: leadAtualizado,
        qualificacao: statusQualificacao,
        tempoPreenchimento,
      };
    } catch (error) {
      console.error('❌ Erro ao finalizar formulário:', error);
      throw error;
    }
  }

  async buscarStatusReal(telefone: string) {
    try {
      const telefoneNormalizado = normalizePhone(telefone);

      const lead = await db.select()
        .from(leads)
        .where(eq(leads.telefoneNormalizado, telefoneNormalizado))
        .limit(1)
        .then(rows => rows[0] || null);

      if (!lead) {
        return {
          existe: false,
          telefoneNormalizado,
        };
      }

      const sessoes = await db.select()
        .from(formularioSessoes)
        .where(eq(formularioSessoes.leadId, lead.id))
        .orderBy(desc(formularioSessoes.createdAt));

      const sessaoAtiva = sessoes.find(s => !s.concluido) || null;

      const historico = await db.select()
        .from(leadHistorico)
        .where(eq(leadHistorico.leadId, lead.id))
        .orderBy(desc(leadHistorico.createdAt));

      return {
        existe: true,
        lead,
        sessaoAtiva,
        sessoes,
        historico,
        status: {
          formularioEnviado: lead.formularioEnviado,
          formularioAberto: lead.formularioAberto,
          formularioIniciado: lead.formularioIniciado,
          formularioConcluido: lead.formularioConcluido,
          visualizacoes: lead.formularioVisualizacoes || 0,
          progressoPercentual: sessaoAtiva?.progressoPercentual || 0,
          pontuacao: lead.pontuacao,
          statusQualificacao: lead.statusQualificacao,
        },
      };
    } catch (error) {
      console.error('❌ Erro ao buscar status real do lead:', error);
      throw error;
    }
  }
}

export const leadTrackingService = new LeadTrackingService();

