import { useState, useEffect, useCallback } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { toast } from 'sonner';

export interface Notification {
  id: string;
  type: 'low_stock' | 'out_of_stock' | 'sale' | 'general';
  title: string;
  message: string;
  data?: any;
  read_at: string | null;
  created_at: string;
}

interface LowStockProduct {
  id: string;
  description: string | null;
  stock: number | null;
  low_stock_threshold: number | null;
}

export function useNotifications() {
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [lowStockProducts, setLowStockProducts] = useState<LowStockProduct[]>([]);
  const [notifiedProducts, setNotifiedProducts] = useState<Set<string>>(new Set());

  const generateLowStockNotifications = useCallback((products: LowStockProduct[]) => {
    const newNotifications: Notification[] = [];
    const now = new Date().toISOString();

    products.forEach(product => {
      if (notifiedProducts.has(product.id)) return;

      const stock = product.stock ?? 0;
      const threshold = product.low_stock_threshold ?? 5;

      if (stock === 0) {
        newNotifications.push({
          id: `stock-${product.id}-${Date.now()}`,
          type: 'out_of_stock',
          title: 'Produto Esgotado!',
          message: `"${product.description || 'Produto'}" está sem estoque.`,
          data: { productId: product.id },
          read_at: null,
          created_at: now
        });
      } else if (stock <= threshold) {
        newNotifications.push({
          id: `stock-${product.id}-${Date.now()}`,
          type: 'low_stock',
          title: 'Estoque Baixo',
          message: `"${product.description || 'Produto'}" tem apenas ${stock} unidade${stock !== 1 ? 's' : ''}.`,
          data: { productId: product.id, stock, threshold },
          read_at: null,
          created_at: now
        });
      }
    });

    if (newNotifications.length > 0) {
      setNotifications(prev => [...newNotifications, ...prev].slice(0, 50));
      setNotifiedProducts(prev => {
        const next = new Set(prev);
        products.forEach(p => next.add(p.id));
        return next;
      });

      if (newNotifications.some(n => n.type === 'out_of_stock')) {
        toast.error('Produtos esgotados!', {
          description: 'Há produtos sem estoque que precisam de reposição.'
        });
      } else {
        toast.warning('Estoque baixo!', {
          description: 'Alguns produtos estão com estoque abaixo do limite.'
        });
      }
    }
  }, [notifiedProducts]);

  const checkLowStock = useCallback(async () => {
    if (!supabase) return;

    try {
      let data: any[] = [];
      let error: any = null;

      try {
        const result = await supabase
          .from('products')
          .select('id, description, stock, low_stock_threshold, notify_low_stock')
          .or('notify_low_stock.is.null,notify_low_stock.eq.true');

        data = result.data || [];
        error = result.error;
      } catch (e) {
        error = e;
      }

      if (error && error.code === '42703') {
        const fallbackResult = await supabase
          .from('products')
          .select('id, description, stock');

        data = (fallbackResult.data || []).map((p: any) => ({
          ...p,
          low_stock_threshold: 5,
          notify_low_stock: true
        }));
      } else if (error) {
        throw error;
      }

      const lowStock = (data || []).filter(product => {
        const stock = (product as any).stock ?? 0;
        const threshold = (product as any).low_stock_threshold ?? 5;
        return stock <= threshold;
      }) as LowStockProduct[];

      setLowStockProducts(lowStock);
      generateLowStockNotifications(lowStock);
    } catch (error) {
      console.error('[useNotifications] Error checking low stock:', error);
    }
  }, [generateLowStockNotifications]);

  useEffect(() => {
    checkLowStock();

    const interval = setInterval(checkLowStock, 60000);

    if (supabase) {
      const channel = supabase
        .channel('product_stock_changes')
        .on(
          'postgres_changes',
          { event: 'UPDATE', schema: 'public', table: 'products' },
          (payload) => {
            const newStock = (payload.new as any).stock ?? 0;
            const oldStock = (payload.old as any).stock ?? 0;

            if (newStock < oldStock) {
              setNotifiedProducts(prev => {
                const next = new Set(prev);
                next.delete((payload.new as any).id);
                return next;
              });
              checkLowStock();
            }
          }
        )
        .subscribe();

      return () => {
        clearInterval(interval);
        supabase.removeChannel(channel);
      };
    }

    return () => clearInterval(interval);
  }, [checkLowStock]);

  useEffect(() => {
    setUnreadCount(notifications.filter(n => !n.read_at).length);
  }, [notifications]);

  const markAsRead = useCallback((notificationId?: string) => {
    const now = new Date().toISOString();
    setNotifications(prev => 
      prev.map(n => 
        notificationId 
          ? (n.id === notificationId ? { ...n, read_at: now } : n)
          : { ...n, read_at: now }
      )
    );
  }, []);

  const markAllAsRead = useCallback(() => {
    const now = new Date().toISOString();
    setNotifications(prev => prev.map(n => ({ ...n, read_at: now })));
  }, []);

  const clearNotifications = useCallback(() => {
    setNotifications([]);
    setNotifiedProducts(new Set());
  }, []);

  return {
    notifications,
    unreadCount,
    lowStockProducts,
    markAsRead,
    markAllAsRead,
    clearNotifications,
    refetch: checkLowStock
  };
}

src/App.tsx.content:
import { Toaster } from "@/components/ui/toaster";
import { Toaster as Sonner } from "@/components/ui/sonner";
import { TooltipProvider } from "@/components/ui/tooltip";
import { QueryClientProvider } from "@tanstack/react-query";
import { BrowserRouter } from "react-router-dom";
import { ThemeProvider } from "next-themes";
import { AuthProvider } from "./contexts/AuthContext";
import { NotificationProvider } from "./contexts/NotificationContext";
import { queryClient } from "./lib/queryClient";
import PlatformRouter from "./platforms/PlatformRouter";
import { InstallPWAButton } from "./components/InstallPWAButton";

/**
 * App Principal - Versão Profissional com Separação Desktop/Mobile
 * 
 * Detecta automaticamente a plataforma (desktop vs mobile) e renderiza
 * o app apropriado com design e navegação otimizados para cada plataforma.
 * 
 * Arquitetura:
 * - Desktop: Header horizontal + navegação superior
 * - Mobile: Header compacto + navegação inferior (bottom nav)
 * - Roteamento completamente separado e independente
 */
const App = () => (
  <QueryClientProvider client={queryClient}>
    <ThemeProvider 
      attribute="class" 
      defaultTheme="dark" 
      enableSystem={false} 
      storageKey="nexus-theme" 
      disableTransitionOnChange
    >
      <TooltipProvider>
        <Toaster />
        <Sonner />
        <BrowserRouter
          future={{
            v7_startTransition: true,
            v7_relativeSplatPath: true,
          }}
        >
          <AuthProvider>
            <NotificationProvider>
              {/* Platform Router - Detecta e renderiza Desktop ou Mobile App */}
              <PlatformRouter />

              {/* PWA Install Button - Aparece em todas as páginas no canto inferior direito (desktop only) */}
              <InstallPWAButton />
            </NotificationProvider>
          </AuthProvider>
        </BrowserRouter>
      </TooltipProvider>
    </ThemeProvider>
  </QueryClientProvider>
);

export default App;

