                </p>
                <div className="flex gap-4 justify-center">
                  <Button 
                    onClick={handleCreateNew}
                    variant="premium"
                    size="lg"
                  >
                    <Plus className="h-5 w-5 mr-2" />
                    Criar Nova Página
                  </Button>
                  {pages.length > 0 && (
                    <Button 
                      onClick={() => setShowPagesList(true)}
                      variant="outline"
                      size="lg"
                      className="glass"
                    >
                      <List className="h-5 w-5 mr-2" />
