import React, { useState, useEffect } from 'react';
import * as fabricModule from 'fabric';
import { Input } from '@/components/ui/input';

const fabric = (fabricModule as any).fabric || fabricModule;
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';

interface PropertiesPanelProps {
  selectedObject: fabric.Object | null;
  onUpdate: () => void;
}

const MM_TO_PX = 10;

export const PropertiesPanel: React.FC<PropertiesPanelProps> = ({
  selectedObject,
  onUpdate,
}) => {
  const [properties, setProperties] = useState<any>({});

  useEffect(() => {
    if (!selectedObject) {
      setProperties({});
      return;
    }

    const updateProperties = () => {
      const props: any = {
        left: ((selectedObject.left || 0) / MM_TO_PX).toFixed(2),
        top: ((selectedObject.top || 0) / MM_TO_PX).toFixed(2),
        width: (((selectedObject.width || 0) * (selectedObject.scaleX || 1)) / MM_TO_PX).toFixed(2),
        height: (((selectedObject.height || 0) * (selectedObject.scaleY || 1)) / MM_TO_PX).toFixed(2),
      };

      if (selectedObject.type === 'textbox' || selectedObject.type === 'text') {
        const textbox = selectedObject as fabric.Textbox;
        props.text = textbox.text || '';
        props.fontSize = textbox.fontSize || 12;
        props.fontFamily = textbox.fontFamily || 'Arial';
        props.fill = textbox.fill as string || '#000000';
        props.fontWeight = textbox.fontWeight || 'normal';
      }

      setProperties(props);
    };

    updateProperties();
  }, [selectedObject]);

  const handlePropertyChange = (key: string, value: any) => {
    if (!selectedObject) return;

    if (key === 'left' || key === 'top') {
      selectedObject.set(key, parseFloat(value) * MM_TO_PX);
    } else if (key === 'width') {
      const newScale = (parseFloat(value) * MM_TO_PX) / (selectedObject.width || 1);
      selectedObject.set('scaleX', newScale);
    } else if (key === 'height') {
      const newScale = (parseFloat(value) * MM_TO_PX) / (selectedObject.height || 1);
      selectedObject.set('scaleY', newScale);
    } else if (key === 'text' && (selectedObject.type === 'textbox' || selectedObject.type === 'text')) {
      (selectedObject as fabric.Textbox).set('text', value);
    } else if (key === 'fontSize' && (selectedObject.type === 'textbox' || selectedObject.type === 'text')) {
      (selectedObject as fabric.Textbox).set('fontSize', parseInt(value));
    } else if (key === 'fontFamily' && (selectedObject.type === 'textbox' || selectedObject.type === 'text')) {
      (selectedObject as fabric.Textbox).set('fontFamily', value);
    } else if (key === 'fill' && (selectedObject.type === 'textbox' || selectedObject.type === 'text')) {
      (selectedObject as fabric.Textbox).set('fill', value);
    } else if (key === 'fontWeight' && (selectedObject.type === 'textbox' || selectedObject.type === 'text')) {
      (selectedObject as fabric.Textbox).set('fontWeight', value);
    }

    selectedObject.setCoords();
    selectedObject.canvas?.renderAll();
    onUpdate();

    setProperties((prev: any) => ({ ...prev, [key]: value }));
  };

  if (!selectedObject) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="text-sm">Propriedades</CardTitle>
        </CardHeader>
        <CardContent>
          <p className="text-sm text-gray-500">Selecione um elemento para editar suas propriedades</p>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="text-sm">Propriedades do Elemento</CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="grid grid-cols-2 gap-4">
          <div>
            <Label htmlFor="left" className="text-xs">Esquerda (mm)</Label>
            <Input
              id="left"
              type="number"
              step="0.1"
              value={properties.left || 0}
              onChange={(e) => handlePropertyChange('left', e.target.value)}
              className="mt-1"
            />
          </div>
          <div>
            <Label htmlFor="top" className="text-xs">Topo (mm)</Label>
            <Input
              id="top"
              type="number"
              step="0.1"
              value={properties.top || 0}
              onChange={(e) => handlePropertyChange('top', e.target.value)}
              className="mt-1"
            />
          </div>
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div>
            <Label htmlFor="width" className="text-xs">Largura (mm)</Label>
            <Input
              id="width"
              type="number"
              step="0.1"
              value={properties.width || 0}
              onChange={(e) => handlePropertyChange('width', e.target.value)}
              className="mt-1"
            />
          </div>
          <div>
            <Label htmlFor="height" className="text-xs">Altura (mm)</Label>
            <Input
              id="height"
              type="number"
              step="0.1"
              value={properties.height || 0}
              onChange={(e) => handlePropertyChange('height', e.target.value)}
              className="mt-1"
            />
          </div>
        </div>

        {(selectedObject.type === 'textbox' || selectedObject.type === 'text') && (
          <>
            <div>
              <Label htmlFor="text" className="text-xs">Texto</Label>
              <Input
                id="text"
                type="text"
                value={properties.text || ''}
                onChange={(e) => handlePropertyChange('text', e.target.value)}
                className="mt-1"
              />
            </div>

            <div>
              <Label htmlFor="fontSize" className="text-xs">Tamanho da Fonte</Label>
              <Input
                id="fontSize"
                type="number"
                min="6"
                max="72"
                value={properties.fontSize || 12}
                onChange={(e) => handlePropertyChange('fontSize', e.target.value)}
                className="mt-1"
              />
            </div>

            <div>
              <Label htmlFor="fontFamily" className="text-xs">Fonte</Label>
              <Select
                value={properties.fontFamily || 'Arial'}
                onValueChange={(value) => handlePropertyChange('fontFamily', value)}
              >
                <SelectTrigger className="mt-1">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="Arial">Arial</SelectItem>
                  <SelectItem value="Helvetica">Helvetica</SelectItem>
                  <SelectItem value="Times New Roman">Times New Roman</SelectItem>
                  <SelectItem value="Courier New">Courier New</SelectItem>
                  <SelectItem value="Georgia">Georgia</SelectItem>
                  <SelectItem value="Verdana">Verdana</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div>
              <Label htmlFor="fill" className="text-xs">Cor</Label>
              <div className="flex gap-2 mt-1">
                <Input
                  id="fill"
                  type="color"
                  value={properties.fill || '#000000'}
                  onChange={(e) => handlePropertyChange('fill', e.target.value)}
                  className="w-16 h-10 p-1"
                />
                <Input
                  type="text"
                  value={properties.fill || '#000000'}
                  onChange={(e) => handlePropertyChange('fill', e.target.value)}
                  className="flex-1"
                />
              </div>
            </div>

            <div>
              <Label htmlFor="fontWeight" className="text-xs">Peso da Fonte</Label>
              <Select
                value={properties.fontWeight || 'normal'}
                onValueChange={(value) => handlePropertyChange('fontWeight', value)}
              >
                <SelectTrigger className="mt-1">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="normal">Normal</SelectItem>
                  <SelectItem value="bold">Negrito</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </>
        )}
      </CardContent>
    </Card>
  );
};

src/components/label-designer/smartLabel.content:
import type { Product } from "@/features/produto/pages/ProdutoPage";

export interface LabelLayoutConfig {
  widthMm: number;
  heightMm: number;
}

export interface LayoutElement {
  type: 'text' | 'image' | 'barcode' | 'qrcode';
  id: string;
  x: number;
  y: number;
  width: number;
  height: number;
  fontSize?: number;
  fontWeight?: string;
  content?: string;
  placeholder?: boolean;
}

export interface SmartLayout {
  elements: LayoutElement[];
  zones: {
    logo: { x: number; y: number; width: number; height: number };
    productName: { x: number; y: number; width: number; height: number };
    price: { x: number; y: number; width: number; height: number };
    reference: { x: number; y: number; width: number; height: number };
    barcode: { x: number; y: number; width: number; height: number };
    notes: { x: number; y: number; width: number; height: number };
  };
}

type LabelSizeCategory = 'tiny' | 'small' | 'medium' | 'large' | 'xlarge';

function categorizeLabelSize(widthMm: number, heightMm: number): LabelSizeCategory {
  const area = widthMm * heightMm;

  if (area < 400) return 'tiny';
  if (area < 900) return 'small';
  if (area < 2000) return 'medium';
  if (area < 4000) return 'large';
  return 'xlarge';
}

export function generateSmartLayout(
  config: LabelLayoutConfig,
  product: Product,
  companyLogo?: string
): SmartLayout {
  const { widthMm, heightMm } = config;
  const category = categorizeLabelSize(widthMm, heightMm);
  const isHorizontal = widthMm > heightMm;

  const margin = Math.max(1, Math.min(widthMm, heightMm) * 0.05);
  const usableWidth = widthMm - margin * 2;
  const usableHeight = heightMm - margin * 2;

  const elements: LayoutElement[] = [];
  let zones: SmartLayout['zones'];

  switch (category) {
    case 'tiny':
      zones = generateTinyLayout(margin, usableWidth, usableHeight, widthMm, heightMm);
      break;
    case 'small':
      zones = generateSmallLayout(margin, usableWidth, usableHeight, widthMm, heightMm, isHorizontal);
      break;
    case 'medium':
      zones = generateMediumLayout(margin, usableWidth, usableHeight, widthMm, heightMm, isHorizontal);
      break;
    case 'large':
    case 'xlarge':
    default:
      zones = generateLargeLayout(margin, usableWidth, usableHeight, widthMm, heightMm, isHorizontal);
      break;
  }

  if (product.description) {
    const nameFontSize = calculateFontSize(category, 'name');
    elements.push({
      type: 'text',
      id: 'product-name',
      x: zones.productName.x,
      y: zones.productName.y,
      width: zones.productName.width,
      height: zones.productName.height,
      fontSize: nameFontSize,
      fontWeight: 'bold',
      content: product.description,
    });
  }

  if (product.price) {
    const priceFontSize = calculateFontSize(category, 'price');
    const priceStr = product.price.startsWith('R$') ? product.price : `R$ ${product.price}`;
    elements.push({
      type: 'text',
      id: 'product-price',
      x: zones.price.x,
      y: zones.price.y,
      width: zones.price.width,
      height: zones.price.height,
      fontSize: priceFontSize,
      fontWeight: 'bold',
      content: priceStr,
    });
  }

  if (product.reference && category !== 'tiny') {
    const refFontSize = calculateFontSize(category, 'reference');
    elements.push({
      type: 'text',
      id: 'product-reference',
      x: zones.reference.x,
      y: zones.reference.y,
      width: zones.reference.width,
      height: zones.reference.height,
      fontSize: refFontSize,
      fontWeight: 'normal',
      content: `Ref: ${product.reference}`,
    });
  }

  if (product.barcode && category !== 'tiny') {
    elements.push({
      type: 'barcode',
      id: 'product-barcode',
      x: zones.barcode.x,
      y: zones.barcode.y,
      width: zones.barcode.width,
      height: zones.barcode.height,
      content: product.barcode,
    });
  }

  if (zones.logo.width > 0 && zones.logo.height > 0) {
    elements.push({
      type: 'image',
      id: 'company-logo',
      x: zones.logo.x,
      y: zones.logo.y,
      width: zones.logo.width,
      height: zones.logo.height,
      placeholder: !companyLogo,
      content: companyLogo,
    });
  }

  if (zones.notes.width > 0 && zones.notes.height > 0 && category !== 'tiny' && category !== 'small') {
    const notesFontSize = calculateFontSize(category, 'notes');
    elements.push({
      type: 'text',
      id: 'notes',
      x: zones.notes.x,
      y: zones.notes.y,
      width: zones.notes.width,
      height: zones.notes.height,
      fontSize: notesFontSize,
      fontWeight: 'normal',
      content: '',
      placeholder: true,
    });
  }

  return { elements, zones };
}

function calculateFontSize(category: LabelSizeCategory, elementType: 'name' | 'price' | 'reference' | 'notes'): number {
  const sizeMap: Record<LabelSizeCategory, Record<string, number>> = {
    tiny: { name: 6, price: 7, reference: 5, notes: 5 },
    small: { name: 8, price: 10, reference: 6, notes: 6 },
    medium: { name: 10, price: 12, reference: 8, notes: 7 },
    large: { name: 12, price: 14, reference: 9, notes: 8 },
    xlarge: { name: 14, price: 16, reference: 10, notes: 9 },
  };

  return sizeMap[category][elementType];
}

function generateTinyLayout(
  margin: number,
  usableWidth: number,
  usableHeight: number,
  widthMm: number,
  heightMm: number
): SmartLayout['zones'] {
  const nameHeight = usableHeight * 0.5;
  const priceHeight = usableHeight * 0.5;

  return {
    logo: { x: 0, y: 0, width: 0, height: 0 },
    productName: {
      x: margin,
      y: margin,
      width: usableWidth,
      height: nameHeight,
    },
    price: {
      x: margin,
      y: margin + nameHeight,
      width: usableWidth,
      height: priceHeight,
    },
    reference: { x: 0, y: 0, width: 0, height: 0 },
    barcode: { x: 0, y: 0, width: 0, height: 0 },
    notes: { x: 0, y: 0, width: 0, height: 0 },
  };
}

function generateSmallLayout(
  margin: number,
  usableWidth: number,
  usableHeight: number,
  widthMm: number,
  heightMm: number,
  isHorizontal: boolean
): SmartLayout['zones'] {
  if (isHorizontal) {
    const leftWidth = usableWidth * 0.65;
    const rightWidth = usableWidth * 0.35;
    const nameHeight = usableHeight * 0.35;
    const priceHeight = usableHeight * 0.35;
    const refHeight = usableHeight * 0.3;

    return {
      logo: { x: 0, y: 0, width: 0, height: 0 },
      productName: {
        x: margin,
        y: margin,
        width: leftWidth,
        height: nameHeight,
      },
      price: {
        x: margin,
        y: margin + nameHeight,
        width: leftWidth,
        height: priceHeight,
      },
      reference: {
        x: margin,
        y: margin + nameHeight + priceHeight,
        width: leftWidth,
        height: refHeight,
      },
      barcode: {
        x: margin + leftWidth + 1,
        y: margin,
        width: rightWidth - 1,
        height: usableHeight,
      },
      notes: { x: 0, y: 0, width: 0, height: 0 },
    };
  } else {
    const nameHeight = usableHeight * 0.3;
    const priceHeight = usableHeight * 0.25;
    const barcodeHeight = usableHeight * 0.35;
    const refHeight = usableHeight * 0.1;

    return {
      logo: { x: 0, y: 0, width: 0, height: 0 },
      productName: {
        x: margin,
        y: margin,
        width: usableWidth,
        height: nameHeight,
      },
      price: {
        x: margin,
        y: margin + nameHeight,
        width: usableWidth,
        height: priceHeight,
      },
      reference: {
        x: margin,
        y: margin + nameHeight + priceHeight,
        width: usableWidth,
        height: refHeight,
      },
      barcode: {
        x: margin,
        y: margin + nameHeight + priceHeight + refHeight,
        width: usableWidth,
        height: barcodeHeight,
      },
      notes: { x: 0, y: 0, width: 0, height: 0 },
    };
  }
}

function generateMediumLayout(
  margin: number,
  usableWidth: number,
  usableHeight: number,
  widthMm: number,
  heightMm: number,
  isHorizontal: boolean
): SmartLayout['zones'] {
  if (isHorizontal) {
    const logoWidth = Math.min(usableWidth * 0.2, 15);
    const logoHeight = Math.min(usableHeight * 0.4, 12);
    const contentWidth = usableWidth - logoWidth - 2;
    const barcodeWidth = usableWidth * 0.35;

    const nameHeight = usableHeight * 0.3;
    const priceHeight = usableHeight * 0.25;
    const refHeight = usableHeight * 0.2;
    const barcodeHeight = usableHeight * 0.25;

    return {
      logo: {
        x: margin,
        y: margin,
        width: logoWidth,
        height: logoHeight,
      },
      productName: {
        x: margin + logoWidth + 2,
        y: margin,
        width: contentWidth - barcodeWidth,
        height: nameHeight,
      },
      price: {
        x: margin + logoWidth + 2,
        y: margin + nameHeight,
        width: contentWidth - barcodeWidth,
        height: priceHeight,
      },
      reference: {
        x: margin,
        y: margin + logoHeight + 1,
        width: usableWidth - barcodeWidth - 2,
        height: refHeight,
      },
      barcode: {
        x: widthMm - margin - barcodeWidth,
        y: margin,
        width: barcodeWidth,
        height: usableHeight * 0.6,
      },
      notes: {
        x: margin,
        y: heightMm - margin - barcodeHeight,
        width: usableWidth - barcodeWidth - 2,
        height: barcodeHeight,
      },
    };
  } else {
    const logoSize = Math.min(usableWidth * 0.25, 10);
    const nameHeight = usableHeight * 0.2;
    const priceHeight = usableHeight * 0.18;
    const refHeight = usableHeight * 0.12;
    const barcodeHeight = usableHeight * 0.25;
    const notesHeight = usableHeight * 0.15;

    return {
      logo: {
        x: margin,
        y: margin,
        width: logoSize,
        height: logoSize,
      },
      productName: {
        x: margin + logoSize + 2,
        y: margin,
        width: usableWidth - logoSize - 2,
        height: nameHeight,
      },
      price: {
        x: margin,
        y: margin + nameHeight + 1,
        width: usableWidth,
        height: priceHeight,
      },
      reference: {
        x: margin,
        y: margin + nameHeight + priceHeight + 2,
        width: usableWidth,
        height: refHeight,
      },
      barcode: {
        x: margin,
        y: margin + nameHeight + priceHeight + refHeight + 3,
        width: usableWidth,
        height: barcodeHeight,
      },
      notes: {
        x: margin,
        y: heightMm - margin - notesHeight,
        width: usableWidth,
        height: notesHeight,
      },
    };
  }
}

function generateLargeLayout(
  margin: number,
  usableWidth: number,
  usableHeight: number,
  widthMm: number,
  heightMm: number,
  isHorizontal: boolean
): SmartLayout['zones'] {
  if (isHorizontal) {
    const logoWidth = Math.min(usableWidth * 0.18, 20);
    const logoHeight = Math.min(usableHeight * 0.35, 15);
    const barcodeWidth = usableWidth * 0.3;
    const barcodeHeight = usableHeight * 0.5;

    const nameHeight = usableHeight * 0.25;
    const priceHeight = usableHeight * 0.22;
    const refHeight = usableHeight * 0.15;
    const notesHeight = usableHeight * 0.3;

    const contentStartX = margin + logoWidth + 3;
    const contentWidth = usableWidth - logoWidth - barcodeWidth - 6;

    return {
      logo: {
        x: margin,
        y: margin,
        width: logoWidth,
        height: logoHeight,
      },
      productName: {
        x: contentStartX,
        y: margin,
        width: contentWidth,
        height: nameHeight,
      },
      price: {
        x: contentStartX,
        y: margin + nameHeight + 1,
        width: contentWidth,
        height: priceHeight,
      },
      reference: {
        x: margin,
        y: margin + logoHeight + 2,
        width: logoWidth + contentWidth + 3,
        height: refHeight,
      },
      barcode: {
        x: widthMm - margin - barcodeWidth,
        y: margin,
        width: barcodeWidth,
        height: barcodeHeight,
      },
      notes: {
        x: margin,
        y: heightMm - margin - notesHeight,
        width: usableWidth - barcodeWidth - 3,
        height: notesHeight,
      },
    };
  } else {
    const logoSize = Math.min(usableWidth * 0.22, 18);
    const nameHeight = usableHeight * 0.15;
    const priceHeight = usableHeight * 0.12;
    const refHeight = usableHeight * 0.1;
    const barcodeHeight = usableHeight * 0.2;
    const notesHeight = usableHeight * 0.15;

    return {
      logo: {
        x: margin,
        y: margin,
        width: logoSize,
        height: logoSize,
      },
      productName: {
        x: margin + logoSize + 3,
        y: margin,
        width: usableWidth - logoSize - 3,
        height: nameHeight,
      },
      price: {
        x: margin,
        y: margin + Math.max(logoSize, nameHeight) + 2,
        width: usableWidth,
        height: priceHeight,
      },
      reference: {
        x: margin,
        y: margin + Math.max(logoSize, nameHeight) + priceHeight + 4,
        width: usableWidth,
        height: refHeight,
      },
      barcode: {
        x: margin + (usableWidth - usableWidth * 0.7) / 2,
        y: margin + Math.max(logoSize, nameHeight) + priceHeight + refHeight + 6,
        width: usableWidth * 0.7,
        height: barcodeHeight,
      },
      notes: {
        x: margin,
        y: heightMm - margin - notesHeight,
        width: usableWidth,
        height: notesHeight,
      },
    };
  }
}

export function getLayoutPreviewDescription(category: LabelSizeCategory): string {
  const descriptions: Record<LabelSizeCategory, string> = {
    tiny: 'Layout compacto: Nome + Preço',
    small: 'Layout básico: Nome, Preço, Ref, Código de barras',
    medium: 'Layout padrão: Logo, Nome, Preço, Ref, Código de barras, Notas',
    large: 'Layout completo: Todos os elementos com espaçamento confortável',
    xlarge: 'Layout premium: Todos os elementos com visual elegante',
  };

  return descriptions[category];
}

