import { GripVertical } from "lucide-react";
import * as ResizablePrimitive from "react-resizable-panels";

import { cn } from "@/lib/utils";

const ResizablePanelGroup = ({ className, ...props }: React.ComponentProps<typeof ResizablePrimitive.PanelGroup>) => (
  <ResizablePrimitive.PanelGroup
    className={cn("flex h-full w-full data-[panel-group-direction=vertical]:flex-col", className)}
    {...props}
  />
);

const ResizablePanel = ResizablePrimitive.Panel;

const ResizableHandle = ({
  withHandle,
  className,
  ...props
}: React.ComponentProps<typeof ResizablePrimitive.PanelResizeHandle> & {
  withHandle?: boolean;
}) => (
  <ResizablePrimitive.PanelResizeHandle
    className={cn(
      "relative flex w-px items-center justify-center bg-border after:absolute after:inset-y-0 after:left-1/2 after:w-1 after:-translate-x-1/2 data-[panel-group-direction=vertical]:h-px data-[panel-group-direction=vertical]:w-full data-[panel-group-direction=vertical]:after:left-0 data-[panel-group-direction=vertical]:after:h-1 data-[panel-group-direction=vertical]:after:w-full data-[panel-group-direction=vertical]:after:-translate-y-1/2 data-[panel-group-direction=vertical]:after:translate-x-0 focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring focus-visible:ring-offset-1 [&[data-panel-group-direction=vertical]>div]:rotate-90",
      className,
    )}
    {...props}
  >
    {withHandle && (
      <div className="z-10 flex h-4 w-3 items-center justify-center rounded-sm border bg-border">
        <GripVertical className="h-2.5 w-2.5" />
      </div>
    )}
  </ResizablePrimitive.PanelResizeHandle>
);

export { ResizablePanelGroup, ResizablePanel, ResizableHandle };

src/components/notion/PropertyTypeMenu.t.content:
import { useState, useEffect, useMemo } from 'react';
import { 
  AlignLeft, Hash, Circle, List as ListIcon, CircleDot, Calendar,
  User, Paperclip, CheckSquare, Link as LinkIcon, Phone, AtSign, Palette
} from 'lucide-react';
import { cn } from '@/lib/utils';
import type { DatabaseFieldType } from '@/types/notion';

interface PropertyTypeMenuProps {
  position: { x: number; y: number };
  onSelectType: (type: DatabaseFieldType, textColor?: string, bgColor?: string) => void;
  onClose: () => void;
}

interface PropertyTypeOption {
  type: DatabaseFieldType;
  label: string;
  icon: React.ReactNode;
}

interface ColorOption {
  value: string;
  label: string;
  textClass: string;
  bgClass: string;
}

export const PropertyTypeMenu = ({ 
  position, 
  onSelectType, 
  onClose 
}: PropertyTypeMenuProps) => {
  const [activeTab, setActiveTab] = useState<'type' | 'text-color' | 'bg-color'>('type');
  const [selectedType, setSelectedType] = useState<DatabaseFieldType | null>(null);
  const [selectedTextColor, setSelectedTextColor] = useState<string>('default');
  const [selectedBgColor, setSelectedBgColor] = useState<string>('default');

  const allPropertyTypes: PropertyTypeOption[] = useMemo(() => [
    { type: 'text', label: 'Texto', icon: <AlignLeft className="h-4 w-4" /> },
    { type: 'number', label: 'Número', icon: <Hash className="h-4 w-4" /> },
    { type: 'select', label: 'Selecionar', icon: <Circle className="h-4 w-4" /> },
    { type: 'multi-select', label: 'Seleção múltipla', icon: <ListIcon className="h-4 w-4" /> },
    { type: 'select', label: 'Status', icon: <CircleDot className="h-4 w-4" /> },
    { type: 'date', label: 'Data', icon: <Calendar className="h-4 w-4" /> },
    { type: 'text', label: 'Pessoa', icon: <User className="h-4 w-4" /> },
    { type: 'text', label: 'Arquivos e mídia', icon: <Paperclip className="h-4 w-4" /> },
    { type: 'checkbox', label: 'Caixa de seleção', icon: <CheckSquare className="h-4 w-4" /> },
    { type: 'url', label: 'URL', icon: <LinkIcon className="h-4 w-4" /> },
    { type: 'phone', label: 'Telefone', icon: <Phone className="h-4 w-4" /> },
    { type: 'email', label: 'E-mail', icon: <AtSign className="h-4 w-4" /> },
  ], []);

  const textColors: ColorOption[] = useMemo(() => [
    { value: 'default', label: 'Padrão', textClass: 'text-foreground', bgClass: '' },
    { value: 'gray', label: 'Cinza', textClass: 'text-gray-500', bgClass: '' },
    { value: 'brown', label: 'Marrom', textClass: 'text-amber-700', bgClass: '' },
    { value: 'orange', label: 'Laranja', textClass: 'text-orange-500', bgClass: '' },
    { value: 'yellow', label: 'Amarelo', textClass: 'text-yellow-500', bgClass: '' },
    { value: 'green', label: 'Verde', textClass: 'text-green-500', bgClass: '' },
    { value: 'blue', label: 'Azul', textClass: 'text-blue-500', bgClass: '' },
    { value: 'purple', label: 'Roxo', textClass: 'text-purple-500', bgClass: '' },
    { value: 'pink', label: 'Rosa', textClass: 'text-pink-500', bgClass: '' },
    { value: 'red', label: 'Vermelho', textClass: 'text-red-500', bgClass: '' },
  ], []);

  const backgroundColors: ColorOption[] = useMemo(() => [
    { value: 'default', label: 'Padrão', textClass: '', bgClass: 'bg-transparent' },
    { value: 'gray', label: 'Cinza', textClass: '', bgClass: 'bg-gray-100 dark:bg-gray-800' },
    { value: 'brown', label: 'Marrom', textClass: '', bgClass: 'bg-amber-100 dark:bg-amber-900' },
    { value: 'orange', label: 'Laranja', textClass: '', bgClass: 'bg-orange-100 dark:bg-orange-900' },
    { value: 'yellow', label: 'Amarelo', textClass: '', bgClass: 'bg-yellow-100 dark:bg-yellow-900' },
    { value: 'green', label: 'Verde', textClass: '', bgClass: 'bg-green-100 dark:bg-green-900' },
    { value: 'blue', label: 'Azul', textClass: '', bgClass: 'bg-blue-100 dark:bg-blue-900' },
    { value: 'purple', label: 'Roxo', textClass: '', bgClass: 'bg-purple-100 dark:bg-purple-900' },
    { value: 'pink', label: 'Rosa', textClass: '', bgClass: 'bg-pink-100 dark:bg-pink-900' },
    { value: 'red', label: 'Vermelho', textClass: '', bgClass: 'bg-red-100 dark:bg-red-900' },
  ], []);

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (!(e.target as HTMLElement).closest('.property-type-menu')) {
        if (selectedType) {
          onSelectType(selectedType, selectedTextColor, selectedBgColor);
        }
        onClose();
      }
    };

    const handleEscape = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        if (selectedType) {
          onSelectType(selectedType, selectedTextColor, selectedBgColor);
        }
        onClose();
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    document.addEventListener('keydown', handleEscape);

    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
      document.removeEventListener('keydown', handleEscape);
    };
  }, [onClose, selectedType, selectedTextColor, selectedBgColor, onSelectType]);

  return (
    <div
      className="property-type-menu fixed bg-popover border border-border rounded-lg shadow-lg overflow-hidden z-50"
      style={{
        left: `${position.x}px`,
        top: `${position.y}px`,
        width: '320px'
      }}
    >
      {/* Tabs */}
      <div className="flex border-b border-border bg-muted/30">
        <button
          onClick={() => setActiveTab('type')}
          className={cn(
            'flex-1 px-3 py-2 text-xs font-medium transition-colors',
            activeTab === 'type' 
              ? 'bg-background text-foreground border-b-2 border-primary' 
              : 'text-muted-foreground hover:text-foreground'
          )}
        >
          Tipo
        </button>
        <button
          onClick={() => setActiveTab('text-color')}
          className={cn(
            'flex-1 px-3 py-2 text-xs font-medium transition-colors flex items-center justify-center gap-1',
            activeTab === 'text-color' 
              ? 'bg-background text-foreground border-b-2 border-primary' 
              : 'text-muted-foreground hover:text-foreground'
          )}
        >
          <Palette className="h-3 w-3" />
          Texto
        </button>
        <button
          onClick={() => setActiveTab('bg-color')}
          className={cn(
            'flex-1 px-3 py-2 text-xs font-medium transition-colors flex items-center justify-center gap-1',
            activeTab === 'bg-color' 
              ? 'bg-background text-foreground border-b-2 border-primary' 
              : 'text-muted-foreground hover:text-foreground'
          )}
        >
          <Palette className="h-3 w-3" />
          Fundo
        </button>
      </div>

      {/* Content */}
      <div className="max-h-[400px] overflow-y-auto">
        {activeTab === 'type' && (
          <div className="py-2">
            {allPropertyTypes.map((option, index) => (
              <button
                key={`${option.type}-${option.label}-${index}`}
                onClick={() => setSelectedType(option.type)}
                className={cn(
                  'w-full text-left px-3 py-2.5 hover:bg-accent hover:text-accent-foreground transition-colors flex items-center gap-3',
                  selectedType === option.type && 'bg-accent text-accent-foreground'
                )}
              >
                <span className="text-muted-foreground">
                  {option.icon}
                </span>
                <span className="text-sm">{option.label}</span>
                {selectedType === option.type && (
                  <span className="ml-auto text-primary text-xs">✓</span>
                )}
              </button>
            ))}
          </div>
        )}

        {activeTab === 'text-color' && (
          <div className="py-2">
            {textColors.map((color) => (
              <button
                key={color.value}
                onClick={() => setSelectedTextColor(color.value)}
                className={cn(
                  'w-full text-left px-3 py-2.5 hover:bg-accent hover:text-accent-foreground transition-colors flex items-center gap-3',
                  selectedTextColor === color.value && 'bg-accent text-accent-foreground'
                )}
              >
                <div className={cn('w-4 h-4 rounded-full border border-border', color.textClass, 'bg-current')} />
                <span className={cn('text-sm', color.textClass)}>{color.label}</span>
                {selectedTextColor === color.value && (
                  <span className="ml-auto text-primary text-xs">✓</span>
                )}
              </button>
            ))}
          </div>
        )}

        {activeTab === 'bg-color' && (
          <div className="py-2">
            {backgroundColors.map((color) => (
              <button
                key={color.value}
                onClick={() => setSelectedBgColor(color.value)}
                className={cn(
                  'w-full text-left px-3 py-2.5 hover:bg-accent hover:text-accent-foreground transition-colors flex items-center gap-3',
                  selectedBgColor === color.value && 'bg-accent text-accent-foreground'
                )}
              >
                <div className={cn('w-4 h-4 rounded border border-border', color.bgClass)} />
                <span className="text-sm">{color.label}</span>
                {selectedBgColor === color.value && (
                  <span className="ml-auto text-primary text-xs">✓</span>
                )}
              </button>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

src/features/formularios-platform/compon.content:
import { useState, useEffect, useMemo, useRef } from "react";
import { 
  FormConfig, 
  FormAnswer, 
  FormSubmission, 
  ScoreTier,
  FormElement,
  isQuestionElement,
  isHeadingElement,
  isTextElement,
  isPageBreakElement,
  migrateQuestionsToElements,
  groupElementsIntoPages
} from "../types/form";
import { Button } from "./ui/button";
import { Card, CardContent, CardFooter, CardHeader, CardTitle, CardDescription } from "./ui/card";
import { Textarea } from "./ui/textarea";
import { Input } from "./ui/input";
import { RadioGroup, RadioGroupItem } from "./ui/radio-group";
import { Label } from "./ui/label";
import { Progress } from "./ui/progress";
import { ArrowRight, Send, CheckCircle2, XCircle, Award, Sparkles } from "lucide-react";

interface FormPreviewProps {
  config: FormConfig;
  onBack: () => void;
  isLivePreview?: boolean;
  activePageId?: string | null;
  activeQuestionId?: string | null;
  wizardMode?: boolean;
}

export const FormPreview = ({ config, onBack, isLivePreview = false, activePageId, activeQuestionId, wizardMode = false }: FormPreviewProps) => {
  const [answers, setAnswers] = useState<Record<string, FormAnswer>>({});
  const [result, setResult] = useState<FormSubmission | null>(null);
  const [currentPageIndex, setCurrentPageIndex] = useState(0);
  const [wizardStep, setWizardStep] = useState(0);
  const questionRefs = useRef<Record<string, HTMLDivElement | null>>({});

  const shouldUseWizard = wizardMode || isLivePreview;

  const defaultDesign = {
    colors: {
      primary: "hsl(221, 83%, 53%)",
      secondary: "hsl(210, 40%, 96%)",
      background: "hsl(0, 0%, 100%)",
      text: "hsl(222, 47%, 11%)",
      button: "hsl(221, 83%, 53%)",
      buttonText: "hsl(0, 0%, 100%)"
    },
    typography: {
      fontFamily: "Inter",
      titleSize: "2xl",
      textSize: "base"
    },
    spacing: "comfortable"
  };

  const baseDesign = config.designConfig ?? {};
  const design = {
    ...defaultDesign,
    ...baseDesign,
    colors: {
      ...defaultDesign.colors,
      ...(baseDesign.colors || {})
    },
    typography: {
      ...defaultDesign.typography,
      ...(baseDesign.typography || {})
    },
    spacing: baseDesign.spacing || defaultDesign.spacing
  };

  const welcomeConfig = config.welcomeConfig ?? {
    title: config.title || "Bem-vindo!",
    description: config.description || "Por favor, preencha o formulário a seguir.",
    imageUrl: null
  };

  const colors = design.colors;

  const spacingClasses = {
    compact: "space-y-4",
    comfortable: "space-y-6",
    spacious: "space-y-8"
  };

  const titleSizeClasses = {
    xs: "text-xs",
    sm: "text-sm",
    base: "text-base",
    lg: "text-lg",
    xl: "text-xl",
    "2xl": "text-2xl",
    "3xl": "text-3xl",
    "4xl": "text-4xl"
  };

  const textSizeClasses = {
    xs: "text-xs",
    sm: "text-sm",
    base: "text-base",
    lg: "text-lg",
    xl: "text-xl",
    "2xl": "text-2xl",
    "3xl": "text-3xl",
    "4xl": "text-4xl"
  };

  const elements = useMemo<FormElement[]>(() => {
    let allElements: FormElement[] = [];

    if (config.elements && config.elements.length > 0) {
      allElements = config.elements;
    } else if (config.questions && config.questions.length > 0) {
      allElements = migrateQuestionsToElements(config.questions);
    }

    if (activeQuestionId && isLivePreview && !shouldUseWizard) {
      const questionElement = allElements.find(el => isQuestionElement(el) && el.id === activeQuestionId);
      if (questionElement) {
        return [questionElement];
      }
    }

    if (activePageId) {
      const pages = groupElementsIntoPages(allElements);
      const activePage = pages.find(page => page.id === activePageId);
      return activePage ? activePage.elements : allElements;
    }

    return allElements;
  }, [config.elements, config.questions, activePageId, activeQuestionId, isLivePreview, shouldUseWizard]);

  const questionElements = useMemo(() => 
    elements.filter(isQuestionElement),
    [elements]
  );

  const totalQuestions = questionElements.length;

  const getTotalWizardSteps = () => {
    return 1 + 1 + 1 + totalQuestions + 1;
  };

  const totalWizardSteps = getTotalWizardSteps();
  const wizardProgress = wizardStep === 0 ? 0 : Math.round(((wizardStep) / (totalWizardSteps - 1)) * 100);

  const pages = useMemo(() => {
    const pagesArray: FormElement[][] = [];
    let currentPage: FormElement[] = [];

    elements.forEach((element) => {
      if (isPageBreakElement(element)) {
        if (currentPage.length > 0) {
          pagesArray.push(currentPage);
          currentPage = [];
        }
      } else {
        currentPage.push(element);
      }
    });

    if (currentPage.length > 0) {
      pagesArray.push(currentPage);
    }

    return pagesArray.length > 0 ? pagesArray : [elements];
  }, [elements]);

  const getCurrentQuestionNumber = (elementIndex: number): number => {
    let questionCount = 0;
    for (let i = 0; i <= elementIndex && i < elements.length; i++) {
      if (isQuestionElement(elements[i])) {
        questionCount++;
      }
    }
    return questionCount;
  };

  useEffect(() => {
    if (design.typography.fontFamily && design.typography.fontFamily !== "Inter") {
      const link = document.createElement('link');
      link.href = `https://fonts.googleapis.com/css2?family=${design.typography.fontFamily.replace(' ', '+')}:wght@400;500;600;700&display=swap`;
      link.rel = 'stylesheet';
      document.head.appendChild(link);
      return () => {
        document.head.removeChild(link);
      };
    }
  }, [design.typography.fontFamily]);

  useEffect(() => {
    if (activeQuestionId && questionRefs.current[activeQuestionId]) {
      const element = questionRefs.current[activeQuestionId];
      element?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
  }, [activeQuestionId]);

  const handleAnswer = (questionId: string, answer: string, points: number) => {
    const newAnswers = {
      ...answers,
      [questionId]: { questionId, answer, points }
    };
    setAnswers(newAnswers);
  };

  const handleNextPage = () => {
    if (currentPageIndex < pages.length - 1) {
      setCurrentPageIndex(prev => prev + 1);
    }
  };

  const handlePrevPage = () => {
    if (currentPageIndex > 0) {
      setCurrentPageIndex(prev => prev - 1);
    }
  };

  const handleWizardNext = () => {
    if (wizardStep < totalWizardSteps - 1) {
      setWizardStep(prev => prev + 1);
    }
  };

  const handleWizardBack = () => {
    if (wizardStep > 0) {
      setWizardStep(prev => prev - 1);
    }
  };

  const handleStartWizard = () => {
    setWizardStep(1);
  };

  const handleSubmit = () => {
    const answerArray = Object.values(answers);
    const totalScore = answerArray.reduce((sum, ans) => sum + ans.points, 0);

    let passed = totalScore >= config.passingScore;

    if (config.scoreTiers && config.scoreTiers.length > 0) {
      const tier = config.scoreTiers.find(
        t => totalScore >= t.minScore && totalScore <= t.maxScore
      );
      passed = tier?.qualifies || false;
    }

    setResult({
      answers: answerArray,
      totalScore,
      passed
    });

    if (shouldUseWizard) {
      setWizardStep(totalWizardSteps - 1);
    }
  };

  const getCurrentTier = (score: number): ScoreTier | undefined => {
    return config.scoreTiers?.find(
      tier => score >= tier.minScore && score <= tier.maxScore
    );
  };

  const renderHeading = (element: FormElement) => {
    if (!isHeadingElement(element)) return null;

    const HeadingTag = `h${element.level}` as keyof JSX.IntrinsicElements;

    const fontSizeClasses = {
      'xs': 'text-xs',
      'sm': 'text-sm',
      'base': 'text-base',
      'lg': 'text-lg',
      'xl': 'text-xl',
      '2xl': 'text-2xl',
      '3xl': 'text-3xl',
      '4xl': 'text-4xl'
    };

    const fontWeightClasses = {
      'normal': 'font-normal',
      'medium': 'font-medium',
      'semibold': 'font-semibold',
      'bold': 'font-bold'
    };

    const alignmentClasses = {
      'left': 'text-left',
      'center': 'text-center',
      'right': 'text-right'
    };

    const fontSize = element.style?.fontSize || '2xl';
    const fontWeight = element.style?.fontWeight || 'bold';
    const alignment = element.style?.alignment || 'left';
    const italic = element.style?.italic || false;
    const underline = element.style?.underline || false;
    const strikethrough = element.style?.strikethrough || false;

    const textDecorationParts = [];
    if (underline) textDecorationParts.push('underline');
    if (strikethrough) textDecorationParts.push('line-through');
    const textDecoration = textDecorationParts.length > 0 ? textDecorationParts.join(' ') : 'none';

    return (
      <div key={element.id} className="space-y-2">
        <HeadingTag 
          className={`${fontSizeClasses[fontSize]} ${fontWeightClasses[fontWeight]} ${alignmentClasses[alignment]}`}
          style={{ 
            color: design.colors.text,
            fontStyle: italic ? 'italic' : 'normal',
            textDecoration
          }}
        >
          {element.text}
        </HeadingTag>
      </div>
    );
  };

  const renderText = (element: FormElement) => {
    if (!isTextElement(element)) return null;

    const fontSizeClasses = {
      'xs': 'text-xs',
      'sm': 'text-sm',
      'base': 'text-base',
      'lg': 'text-lg',
      'xl': 'text-xl',
      '2xl': 'text-2xl',
      '3xl': 'text-3xl',
      '4xl': 'text-4xl'
    };

    const fontWeightClasses = {
      'normal': 'font-normal',
      'medium': 'font-medium',
      'semibold': 'font-semibold',
      'bold': 'font-bold'
    };

    const alignmentClasses = {
      'left': 'text-left',
      'center': 'text-center',
      'right': 'text-right'
    };

    const fontSize = element.style?.fontSize || 'base';
    const fontWeight = element.style?.fontWeight || 'normal';
    const alignment = element.style?.alignment || 'left';
    const italic = element.style?.italic || false;
    const underline = element.style?.underline || false;
    const strikethrough = element.style?.strikethrough || false;

    const textDecorationParts = [];
    if (underline) textDecorationParts.push('underline');
    if (strikethrough) textDecorationParts.push('line-through');
    const textDecoration = textDecorationParts.length > 0 ? textDecorationParts.join(' ') : 'none';

    return (
      <div key={element.id} className="space-y-2">
        <p 
          className={`leading-relaxed ${fontSizeClasses[fontSize]} ${fontWeightClasses[fontWeight]} ${alignmentClasses[alignment]}`}
          style={{ 
            color: design.colors.text, 
            opacity: 0.9,
            fontStyle: italic ? 'italic' : 'normal',
            textDecoration
          }}
        >
          {element.content}
        </p>
      </div>
    );
  };

  const renderPageBreak = (element: FormElement) => {
    if (!isPageBreakElement(element)) return null;

    return (
      <div key={element.id} className="my-8">
        {element.showLine && (
          <hr 
            className="border-t-2" 
            style={{ borderColor: design.colors.primary + '30' }}
          />
        )}
        {element.label && (
          <p 
            className="text-center text-sm mt-2"
            style={{ color: design.colors.text, opacity: 0.6 }}
          >
            {element.label}
          </p>
        )}
      </div>
    );
  };

  const renderQuestion = (element: FormElement, questionNumber: number) => {
    if (!isQuestionElement(element)) return null;

    const isActiveQuestion = activeQuestionId === element.id;

    return (
      <div 
        key={element.id} 
        ref={(el) => { questionRefs.current[element.id] = el; }}
        className="space-y-4 transition-all duration-300 rounded-lg p-4"
        style={isActiveQuestion ? { 
          boxShadow: `0 0 0 2px ${design.colors.primary}`,
          backgroundColor: `${design.colors.primary}0d`
        } : undefined}
      >
        <div className="flex items-start gap-3">
          <span 
            className="font-semibold px-3 py-1 rounded-full text-sm shrink-0"
            style={{ 
              backgroundColor: `${design.colors.primary}20`,
              color: design.colors.primary
            }}
          >
            {questionNumber}
          </span>
          <div className="flex-1">
            <h3 
              className={`font-medium ${textSizeClasses[design.typography.textSize as keyof typeof textSizeClasses]} mb-4`}
              style={{ color: design.colors.text }}
            >
              {element.text}
            </h3>

            {element.questionType === 'multiple-choice' && element.options && (
              <RadioGroup
                value={answers[element.id]?.answer || ""}
                onValueChange={(value) => {
                  const option = element.options?.find(o => o.id === value);
                  if (option) {
                    handleAnswer(element.id, option.text, option.points);
                  }
                }}
                className="space-y-3"
              >
                {element.options.map((option) => (
                  <div
                    key={option.id}
                    className="flex items-center space-x-3 p-4 rounded-lg border transition-all duration-200 cursor-pointer hover:shadow-md"
                    style={{
                      backgroundColor: design.colors.secondary,
                      borderColor: design.colors.primary + '30',
                      color: design.colors.text
                    }}
                  >
                    <RadioGroupItem value={option.id} id={`${element.id}-${option.id}`} />
                    <Label 
                      htmlFor={`${element.id}-${option.id}`}
                      className="flex-1 cursor-pointer font-normal"
                      style={{ color: design.colors.text }}
                    >
                      {option.text}
                    </Label>
                  </div>
                ))}
              </RadioGroup>
            )}

