import fs from 'fs';
import path from 'path';
import { log } from '../vite';

const DATA_DIR = path.join(process.cwd(), 'data');

const STATE_FILES = [
  'form_submission_poller_state.json',
  'cpf_processed_ids.json',
  'cpf_compliance_poller_state.json',
  'automation_state.json',
];

export function resetFormPollerState(): void {
  const filePath = path.join(DATA_DIR, 'form_submission_poller_state.json');
  const initialState = {
    lastSyncedAt: null,
    lastSyncedId: null,
    lastRunAt: null,
    totalSubmissionsProcessed: 0,
    totalErrors: 0,
    lastError: null
  };

  try {
    if (!fs.existsSync(DATA_DIR)) {
      fs.mkdirSync(DATA_DIR, { recursive: true });
    }
    fs.writeFileSync(filePath, JSON.stringify(initialState, null, 2), 'utf8');
    log('🔄 [StateReset] FormPoller state resetado');
  } catch (error) {
    console.error('❌ [StateReset] Erro ao resetar FormPoller state:', error);
  }
}

export function resetCPFProcessedIds(): void {
  const filePath = path.join(DATA_DIR, 'cpf_processed_ids.json');

  try {
    if (!fs.existsSync(DATA_DIR)) {
      fs.mkdirSync(DATA_DIR, { recursive: true });
    }
    fs.writeFileSync(filePath, '[]', 'utf8');
    log('🔄 [StateReset] CPF processed IDs resetado');
  } catch (error) {
    console.error('❌ [StateReset] Erro ao resetar CPF processed IDs:', error);
  }
}

export function resetCPFPollerState(): void {
  const filePath = path.join(DATA_DIR, 'cpf_compliance_poller_state.json');
  const initialState = {
    lastPolledAt: null,
    totalProcessed: 0,
    totalErrors: 0,
    lastError: null
  };

  try {
    if (!fs.existsSync(DATA_DIR)) {
      fs.mkdirSync(DATA_DIR, { recursive: true });
    }
    fs.writeFileSync(filePath, JSON.stringify(initialState, null, 2), 'utf8');
    log('🔄 [StateReset] CPFPoller state resetado');
  } catch (error) {
    console.error('❌ [StateReset] Erro ao resetar CPFPoller state:', error);
  }
}

export function resetAutomationState(): void {
  const filePath = path.join(DATA_DIR, 'automation_state.json');

  try {
    if (fs.existsSync(filePath)) {
      fs.unlinkSync(filePath);
      log('🔄 [StateReset] Automation state removido');
    }
  } catch (error) {
    console.error('❌ [StateReset] Erro ao resetar automation state:', error);
  }
}

export function resetAllPollerStates(): void {
  log('🔄 [StateReset] Resetando todos os estados de polling...');

  resetFormPollerState();
  resetCPFProcessedIds();
  resetCPFPollerState();
  resetAutomationState();

  log('✅ [StateReset] Todos os estados de polling resetados com sucesso!');
  log('📊 [StateReset] O sistema irá sincronizar todos os dados do Supabase na próxima execução.');
}

export function checkAndResetStaleStates(): void {
  log('🔍 [StateReset] Verificando estados obsoletos...');

  const formPollerPath = path.join(DATA_DIR, 'form_submission_poller_state.json');

  if (fs.existsSync(formPollerPath)) {
    try {
      const data = JSON.parse(fs.readFileSync(formPollerPath, 'utf8'));

      if (data.lastSyncedAt) {
        const lastSync = new Date(data.lastSyncedAt);
        const now = new Date();
        const daysSinceSync = (now.getTime() - lastSync.getTime()) / (1000 * 60 * 60 * 24);

        if (daysSinceSync > 7) {
          log(`⚠️ [StateReset] FormPoller não sincroniza há ${Math.floor(daysSinceSync)} dias - resetando...`);
          resetFormPollerState();
        }
      }
    } catch (error) {
      log('⚠️ [StateReset] Estado do FormPoller corrompido - resetando...');
      resetFormPollerState();
    }
  }
}

export function isFirstRun(): boolean {
  const formPollerPath = path.join(DATA_DIR, 'form_submission_poller_state.json');
  const cpfPollerPath = path.join(DATA_DIR, 'cpf_compliance_poller_state.json');

  return !fs.existsSync(formPollerPath) && !fs.existsSync(cpfPollerPath);
}

export function initializePollerStates(): void {
  if (!fs.existsSync(DATA_DIR)) {
    fs.mkdirSync(DATA_DIR, { recursive: true });
  }

  const formPollerPath = path.join(DATA_DIR, 'form_submission_poller_state.json');
  const cpfPollerPath = path.join(DATA_DIR, 'cpf_compliance_poller_state.json');
  const cpfProcessedPath = path.join(DATA_DIR, 'cpf_processed_ids.json');

  if (!fs.existsSync(formPollerPath)) {
    resetFormPollerState();
  }

  if (!fs.existsSync(cpfPollerPath)) {
    resetCPFPollerState();
  }

  if (!fs.existsSync(cpfProcessedPath)) {
    resetCPFProcessedIds();
  }

  log('✅ [StateReset] Estados de polling inicializados');
}

src/features/revendedora/hooks/useResell.content:
import { useState, useEffect, useCallback } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { toast } from 'sonner';

export interface ResellerProfile {
  id?: string;
  reseller_id: string;
  profile_photo_url: string | null;
  phone: string | null;
  instagram_handle: string | null;
  bio: string | null;
  show_career_level: boolean;
  created_at?: string;
  updated_at?: string;
}

export function useResellerProfile(resellerId?: string) {
  const [profile, setProfile] = useState<ResellerProfile | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [uploading, setUploading] = useState(false);

  const getResellerId = useCallback((): string => {
    if (resellerId) return resellerId;
    const storedReseller = localStorage.getItem('current_reseller_id');
    if (storedReseller) return storedReseller;
    return '00000000-0000-0000-0000-000000000001';
  }, [resellerId]);

  const loadProfile = useCallback(async () => {
    if (!supabase) {
      console.log('[ResellerProfile] Supabase not configured');
      setLoading(false);
      return;
    }

    try {
      const id = getResellerId();
      console.log('[ResellerProfile] Loading profile for reseller:', id);

      const { data, error } = await supabase
        .from('reseller_profiles')
        .select('*')
        .eq('reseller_id', id)
        .single();

      if (error && error.code !== 'PGRST116') {
        if (error.code === 'PGRST205' || error.message?.includes('does not exist')) {
          console.log('[ResellerProfile] Table not found, profile system not set up yet');
        } else {
          console.error('[ResellerProfile] Error loading profile:', error);
        }
      } else if (data) {
        console.log('[ResellerProfile] Profile loaded:', data);
        setProfile(data as ResellerProfile);
      } else {
        console.log('[ResellerProfile] No profile found for reseller');
        setProfile({
          reseller_id: id,
          profile_photo_url: null,
          phone: null,
          instagram_handle: null,
          bio: null,
          show_career_level: false,
        });
      }
    } catch (error) {
      console.error('[ResellerProfile] Error:', error);
    } finally {
      setLoading(false);
    }
  }, [getResellerId]);

  useEffect(() => {
    loadProfile();
  }, [loadProfile]);

  const uploadProfilePhoto = async (file: File): Promise<string | null> => {
    if (!supabase) {
      toast.error('Configuração do Supabase não encontrada');
      return null;
    }

    setUploading(true);
    try {
      const id = getResellerId();
      const fileExt = file.name.split('.').pop();
      const fileName = `${id}/profile-${Date.now()}.${fileExt}`;
      const filePath = `reseller-profile-photos/${fileName}`;

      console.log('[ResellerProfile] Uploading photo:', filePath);

      const { data: uploadData, error: uploadError } = await supabase.storage
        .from('reseller-profile-photos')
        .upload(fileName, file, {
          cacheControl: '3600',
          upsert: true,
        });

      if (uploadError) {
        if (uploadError.message?.includes('bucket') || uploadError.message?.includes('not found')) {
          console.log('[ResellerProfile] Storage bucket not found, trying alternative');
          const { data: publicUpload, error: publicError } = await supabase.storage
            .from('public')
            .upload(`reseller-profiles/${fileName}`, file, {
              cacheControl: '3600',
              upsert: true,
            });

          if (publicError) {
            throw publicError;
          }

          const { data: publicUrl } = supabase.storage
            .from('public')
            .getPublicUrl(`reseller-profiles/${fileName}`);

          console.log('[ResellerProfile] Photo uploaded to public bucket:', publicUrl.publicUrl);
          return publicUrl.publicUrl;
        }
        throw uploadError;
      }

      const { data: urlData } = supabase.storage
        .from('reseller-profile-photos')
        .getPublicUrl(fileName);

      console.log('[ResellerProfile] Photo uploaded:', urlData.publicUrl);
      return urlData.publicUrl;
    } catch (error: any) {
      console.error('[ResellerProfile] Upload error:', error);
      toast.error('Erro ao fazer upload da foto: ' + (error.message || 'Erro desconhecido'));
      return null;
    } finally {
      setUploading(false);
    }
  };

  const saveProfile = async (profileData: Partial<ResellerProfile>): Promise<boolean> => {
    if (!supabase) {
      toast.error('Configuração do Supabase não encontrada');
      return false;
    }

    setSaving(true);
    try {
      const id = getResellerId();
      const dataToSave = {
        reseller_id: id,
        profile_photo_url: profileData.profile_photo_url || null,
        phone: profileData.phone || null,
        instagram_handle: profileData.instagram_handle || null,
        bio: profileData.bio || null,
        show_career_level: profileData.show_career_level ?? false,
      };

      console.log('[ResellerProfile] Saving profile:', dataToSave);

      const { data: existing } = await supabase
        .from('reseller_profiles')
        .select('id')
        .eq('reseller_id', id)
        .single();

      if (existing) {
        const { error } = await supabase
          .from('reseller_profiles')
          .update(dataToSave as any)
          .eq('reseller_id', id);

        if (error) throw error;
      } else {
        const { error } = await supabase
          .from('reseller_profiles')
          .insert(dataToSave as any);

        if (error) throw error;
      }

      console.log('[ResellerProfile] Profile saved successfully');
      setProfile({ ...profile, ...dataToSave } as ResellerProfile);
      toast.success('Perfil salvo com sucesso!');
      return true;
    } catch (error: any) {
      console.error('[ResellerProfile] Save error:', error);
      if (error.code === 'PGRST205' || error.message?.includes('does not exist')) {
        toast.error('Tabela de perfis não encontrada. Execute a migração SQL primeiro.');
      } else {
        toast.error('Erro ao salvar perfil: ' + (error.message || 'Erro desconhecido'));
      }
      return false;
    } finally {
      setSaving(false);
    }
  };

  return {
    profile,
    loading,
    saving,
    uploading,
    loadProfile,
    saveProfile,
    uploadProfilePhoto,
    getResellerId,
  };
}

export function usePublicResellerProfile(resellerId: string) {
  const [profile, setProfile] = useState<ResellerProfile | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const loadProfile = async () => {
      if (!supabase || !resellerId) {
        setLoading(false);
        return;
      }

      try {
        console.log('[PublicResellerProfile] Loading profile for:', resellerId);

        const { data, error } = await supabase
          .from('reseller_profiles')
          .select('*')
          .eq('reseller_id', resellerId)
          .single();

        if (error && error.code !== 'PGRST116') {
          console.error('[PublicResellerProfile] Error:', error);
        } else if (data) {
          console.log('[PublicResellerProfile] Profile loaded:', data);
          setProfile(data as ResellerProfile);
        }
      } catch (error) {
        console.error('[PublicResellerProfile] Error:', error);
      } finally {
        setLoading(false);
      }
    };

    loadProfile();
  }, [resellerId]);

  return { profile, loading };
}

