/**
 * Response Compression Middleware
 * Reduces bandwidth usage for Supabase and Cloudflare
 * Optimized for FREE tier limits
 */

import { Request, Response, NextFunction } from 'express';
import zlib from 'zlib';
import { promisify } from 'util';

const gzipAsync = promisify(zlib.gzip);
const brotliAsync = promisify(zlib.brotliCompress);

/**
 * Compression settings
 */
const COMPRESSION_CONFIG = {
  threshold: 1024, // Only compress if response > 1KB
  level: 6, // Balance between speed and compression (1-9)

  // MIME types to compress
  compressibleTypes: [
    'text/html',
    'text/css',
    'text/javascript',
    'application/javascript',
    'application/json',
    'application/xml',
    'text/xml',
    'text/plain',
    'image/svg+xml',
  ],

  // Paths to always compress
  compressPaths: [
    '/api/dashboard',
    '/api/forms',
    '/api/workspace',
    '/api/products',
    '/api/calendar',
  ],
};

/**
 * Check if response should be compressed
 */
function shouldCompress(req: Request, res: Response): boolean {
  // Skip if client doesn't support compression
  const acceptEncoding = req.headers['accept-encoding'] || '';
  if (!acceptEncoding.includes('gzip') && !acceptEncoding.includes('br')) {
    return false;
  }

  // Check content type
  const contentType = res.getHeader('content-type')?.toString() || '';
  const isCompressibleType = COMPRESSION_CONFIG.compressibleTypes.some(
    type => contentType.includes(type)
  );

  // Check path
  const isCompressiblePath = COMPRESSION_CONFIG.compressPaths.some(
    path => req.path.startsWith(path)
  );

  return isCompressibleType || isCompressiblePath;
}

/**
 * Smart compression middleware
 * Uses Brotli for browsers that support it, fallback to Gzip
 */
export function smartCompression(req: Request, res: Response, next: NextFunction): void {
  const originalSend = res.send.bind(res);

  res.send = function(body: any): Response {
    // Skip if shouldn't compress
    if (!shouldCompress(req, res)) {
      return originalSend(body);
    }

    // Skip if body is too small
    const bodySize = Buffer.byteLength(body || '', 'utf8');
    if (bodySize < COMPRESSION_CONFIG.threshold) {
      return originalSend(body);
    }

    // Get best compression method
    const acceptEncoding = req.headers['accept-encoding'] || '';
    const useBrotli = acceptEncoding.includes('br');
    const useGzip = acceptEncoding.includes('gzip');

    if (!useBrotli && !useGzip) {
      return originalSend(body);
    }

    // Compress asynchronously
    (async () => {
      try {
        let compressed: Buffer;
        let encoding: string;

        if (useBrotli) {
          compressed = await brotliAsync(body, {
            params: {
              [zlib.constants.BROTLI_PARAM_QUALITY]: COMPRESSION_CONFIG.level,
            },
          });
          encoding = 'br';
        } else {
          compressed = await gzipAsync(body, {
            level: COMPRESSION_CONFIG.level,
          });
          encoding = 'gzip';
        }

        const compressedSize = compressed.length;
        const ratio = ((1 - compressedSize / bodySize) * 100).toFixed(1);

        console.log(
          `🗜️ Compressed ${req.path}: ${bodySize}B → ${compressedSize}B (${ratio}% savings, ${encoding})`
        );

        res.setHeader('Content-Encoding', encoding);
        res.setHeader('Content-Length', compressedSize.toString());
        res.setHeader('Vary', 'Accept-Encoding');

        originalSend.call(res, compressed);
      } catch (error) {
        console.error('Compression error:', error);
        // Fallback to uncompressed
        originalSend.call(res, body);
      }
    })();

    // Return response object for chaining
    return res;
  };

  next();
}

/**
 * Compression stats tracker
 */
class CompressionStats {
  private totalSaved = 0;
  private requestsCompressed = 0;

  track(originalSize: number, compressedSize: number): void {
    this.totalSaved += (originalSize - compressedSize);
    this.requestsCompressed++;
  }

  getStats() {
    return {
      totalSavedBytes: this.totalSaved,
      totalSavedMB: (this.totalSaved / (1024 * 1024)).toFixed(2),
      requestsCompressed: this.requestsCompressed,
      averageSavings: this.requestsCompressed > 0
        ? ((this.totalSaved / this.requestsCompressed) / 1024).toFixed(2) + ' KB'
        : '0 KB',
    };
  }

  reset(): void {
    this.totalSaved = 0;
    this.requestsCompressed = 0;
  }
}

export const compressionStats = new CompressionStats();

/**
 * JSON minification for API responses
 * Removes whitespace from JSON responses
 */
export function jsonMinify(req: Request, res: Response, next: NextFunction): void {
  if (!req.path.startsWith('/api/')) {
    return next();
  }

  const originalJson = res.json.bind(res);

  res.json = function(body: any): Response {
    // Minify JSON (no whitespace)
    const minified = JSON.stringify(body);
    const original = JSON.stringify(body, null, 2);

    const saved = Buffer.byteLength(original) - Buffer.byteLength(minified);
    if (saved > 0) {
      console.log(`🔨 JSON minified: saved ${saved}B`);
    }

    // Set content type and send minified
    res.setHeader('Content-Type', 'application/json');
    return originalJson.call(res, body);
  };

  next();
}

src/features/formularios-platform/compon.content:
import { useState } from "react";
import { FormElement, DesignConfig, FormTemplate, ScoreTier, CompletionPageConfig, extractQuestions } from "../types/form";
import { Button } from "./ui/button";
import { Input } from "./ui/input";
import { Card } from "./ui/card";
import { Plus, Palette, Layout, Eye, Target, Trash2, Save } from "lucide-react";
import { Textarea } from "./ui/textarea";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "./ui/tabs";
import { DesignCustomizer } from "./design/DesignCustomizer";
import { TemplateSelector } from "./design/TemplateSelector";
import { DragDropEditor } from "./design/DragDropEditor";
import { ElementToolbar } from "./ElementToolbar";
import { api } from "../lib/api";
import { useToast } from "../hooks/use-toast";
import { Switch } from "./ui/switch";
import { Label } from "./ui/label";

interface FormBuilderWithDesignProps {
  title: string;
  description: string;
  elements: FormElement[];
  passingScore: number;
  scoreTiers?: ScoreTier[];
  designConfig: DesignConfig;
  completionPageConfig?: CompletionPageConfig;
  onTitleChange: (title: string) => void;
  onDescriptionChange: (description: string) => void;
  onElementsChange: (elements: FormElement[]) => void;
  onPassingScoreChange: (score: number) => void;
  onScoreTiersChange?: (tiers: ScoreTier[]) => void;
  onDesignChange: (design: DesignConfig) => void;
  onCompletionPageChange?: (config: CompletionPageConfig) => void;
  onSave?: () => void;
  isSaving?: boolean;
  onSaveAsTemplate?: () => void;
  activePageId?: string | null;
  onActivePageChange?: (pageId: string) => void;
}

export const FormBuilderWithDesign = ({ 
  title,
  description,
  elements,
  passingScore,
  scoreTiers = [],
  designConfig,
  completionPageConfig,
  onTitleChange,
  onDescriptionChange,
  onElementsChange,
  onPassingScoreChange,
  onScoreTiersChange,
  onDesignChange,
  onCompletionPageChange,
  onSave,
  isSaving = false,
  onSaveAsTemplate,
  activePageId,
  onActivePageChange
}: FormBuilderWithDesignProps) => {
  const { toast } = useToast();
  const [useTiers, setUseTiers] = useState(scoreTiers.length > 0);

  const addScoreTier = () => {
    const newTier: ScoreTier = {
      id: Date.now().toString(),
      label: '',
      minScore: 0,
      maxScore: 0,
      description: '',
      qualifies: false
    };
    onScoreTiersChange?.([...scoreTiers, newTier]);
  };

  const updateScoreTier = (id: string, updates: Partial<ScoreTier>) => {
    onScoreTiersChange?.(
      scoreTiers.map(tier => tier.id === id ? { ...tier, ...updates } : tier)
    );
  };

  const deleteScoreTier = (id: string) => {
    onScoreTiersChange?.(scoreTiers.filter(tier => tier.id !== id));
  };

  const handleUseTiersChange = (checked: boolean) => {
    setUseTiers(checked);
    if (!checked) {
      onScoreTiersChange?.([]);
    } else if (scoreTiers.length === 0) {
      // Criar tiers padrão
      const defaultTiers: ScoreTier[] = [
        {
          id: '1',
          label: 'Ótimo',
          minScore: 350,
          maxScore: 400,
          description: 'Lead altamente qualificado',
          qualifies: true
        },
        {
          id: '2',
          label: 'Bom',
          minScore: 300,
          maxScore: 349,
          description: 'Lead qualificado',
          qualifies: true
        },
        {
          id: '3',
          label: 'Médio',
          minScore: 250,
          maxScore: 299,
          description: 'Lead com potencial',
          qualifies: true
        },
        {
          id: '4',
          label: 'Não Qualificado',
          minScore: 0,
          maxScore: 249,
          description: 'Não qualifica para reunião',
          qualifies: false
        }
      ];
      onScoreTiersChange?.(defaultTiers);
    }
  };

  const addElement = (newElement: FormElement) => {
    onElementsChange([...elements, newElement]);
  };

  const updateElement = (id: string, updated: FormElement) => {
    onElementsChange(elements.map(el => el.id === id ? updated : el));
  };

  const deleteElement = (id: string) => {
    onElementsChange(elements.filter(el => el.id !== id));
  };

  const handleSelectTemplate = (template: FormTemplate) => {
    onDesignChange(template.designConfig);
    if (template.elements && template.elements.length > 0) {
      onElementsChange(template.elements);
    } else if (template.questions && template.questions.length > 0) {
      // Backward compatibility: convert old questions to elements
      const migratedElements = template.questions.map(q => ({
        type: 'question' as const,
        id: q.id,
        text: q.text,
        questionType: q.type,
        options: q.options,
        points: q.points,
        elementTypeVersion: 1
      }));
      onElementsChange(migratedElements);
    }
    toast({
      title: "Template aplicado!",
      description: `Template "${template.name}" foi aplicado com sucesso`
    });
  };

  const saveAsTemplate = async () => {
    try {
      const templateData: any = {
        name: title,
        description: description,
        designConfig: designConfig,
        elements: elements,
        questions: extractQuestions(elements),
        isDefault: false
      };

      // Adicionar score tiers se estiverem configurados
      if (scoreTiers.length > 0) {
        templateData.scoreTiers = scoreTiers;
      }

      await api.createTemplate(templateData);

      toast({
        title: "Sucesso!",
        description: "Template salvo com sucesso"
      });

      if (onSaveAsTemplate) {
        onSaveAsTemplate();
      }
    } catch (error) {
      console.error('Error saving template:', error);
      toast({
        title: "Erro",
        description: "Não foi possível salvar o template",
        variant: "destructive"
      });
    }
  };

  return (
    <div className="space-y-6">
      <Card className="p-8 bg-gradient-to-br from-card to-card/80 border-border shadow-[var(--shadow-luxury)]">
        <div className="space-y-4">
          <div>
            <label className="text-sm font-medium text-foreground mb-2 block">
              Título do Formulário
            </label>
            <Input
              value={title}
              onChange={(e) => onTitleChange(e.target.value)}
              className="text-lg font-semibold bg-background border-border"
            />
          </div>

          <div>
            <label className="text-sm font-medium text-foreground mb-2 block">
              Descrição
            </label>
            <Textarea
              value={description}
              onChange={(e) => onDescriptionChange(e.target.value)}
              className="bg-background border-border resize-none"
              rows={3}
            />
          </div>

          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label htmlFor="use-tiers" className="text-sm font-medium">
                  Sistema de Qualificação de Leads
                </Label>
                <p className="text-xs text-muted-foreground">
                  Configure múltiplos níveis de pontuação para qualificar leads
                </p>
              </div>
              <Switch
                id="use-tiers"
                checked={useTiers}
                onCheckedChange={handleUseTiersChange}
              />
            </div>

            {!useTiers ? (
              <div>
                <label className="text-sm font-medium text-foreground mb-2 block">
                  Pontuação Mínima para Aprovação
                </label>
                <Input
                  type="number"
                  value={passingScore}
                  onChange={(e) => onPassingScoreChange(parseInt(e.target.value) || 0)}
                  className="w-32 bg-background border-border"
                />
              </div>
            ) : (
              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <h3 className="text-sm font-medium text-foreground">Níveis de Qualificação</h3>
                  <Button onClick={addScoreTier} size="sm" variant="outline" className="gap-2">
                    <Plus className="h-3 w-3" />
                    Adicionar Nível
                  </Button>
                </div>

                <div className="space-y-3">
                  {scoreTiers.map((tier) => (
                    <Card key={tier.id} className="p-4 bg-background border-border">
                      <div className="space-y-3">
                        <div className="flex items-start justify-between gap-2">
                          <Input
                            placeholder="Nome do nível (ex: Ótimo)"
                            value={tier.label}
                            onChange={(e) => updateScoreTier(tier.id, { label: e.target.value })}
                            className="flex-1 bg-background border-border"
                          />
                          <Button
                            onClick={() => deleteScoreTier(tier.id)}
                            size="sm"
                            variant="ghost"
                            className="text-destructive hover:text-destructive"
                          >
                            <Trash2 className="h-4 w-4" />
                          </Button>
                        </div>

                        <div className="grid grid-cols-2 gap-2">
                          <div>
                            <label className="text-xs text-muted-foreground mb-1 block">
                              Pontuação Mínima
                            </label>
                            <Input
                              type="number"
                              value={tier.minScore}
                              onChange={(e) => updateScoreTier(tier.id, { minScore: parseInt(e.target.value) || 0 })}
                              className="bg-background border-border"
                            />
                          </div>
                          <div>
                            <label className="text-xs text-muted-foreground mb-1 block">
                              Pontuação Máxima
                            </label>
                            <Input
                              type="number"
                              value={tier.maxScore}
                              onChange={(e) => updateScoreTier(tier.id, { maxScore: parseInt(e.target.value) || 0 })}
                              className="bg-background border-border"
                            />
                          </div>
                        </div>

                        <Input
                          placeholder="Descrição (ex: Lead altamente qualificado)"
                          value={tier.description}
                          onChange={(e) => updateScoreTier(tier.id, { description: e.target.value })}
                          className="bg-background border-border"
                        />

                        <div className="flex items-center gap-2">
                          <Switch
                            id={`qualifies-${tier.id}`}
                            checked={tier.qualifies}
                            onCheckedChange={(checked) => updateScoreTier(tier.id, { qualifies: checked })}
                          />
                          <Label htmlFor={`qualifies-${tier.id}`} className="text-sm">
                            Qualifica para reunião
                          </Label>
                        </div>
                      </div>
                    </Card>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>
      </Card>

      <Tabs defaultValue="questions" className="w-full">
        <TabsList className="grid w-full grid-cols-3">
          <TabsTrigger value="questions" className="gap-2">
            <Layout className="h-4 w-4" />
            Perguntas
          </TabsTrigger>
          <TabsTrigger value="design" className="gap-2">
            <Palette className="h-4 w-4" />
            Design
          </TabsTrigger>
          <TabsTrigger value="templates" className="gap-2">
            <Eye className="h-4 w-4" />
            Templates
          </TabsTrigger>
        </TabsList>

        <TabsContent value="questions" className="space-y-4 mt-6">
          <DragDropEditor
            elements={elements}
            onReorder={onElementsChange}
            onUpdate={updateElement}
            onDelete={deleteElement}
            activePageId={activePageId}
            onActivePageChange={onActivePageChange}
          />

          <div className="flex justify-center">
            <ElementToolbar onAddElement={addElement} />
          </div>
        </TabsContent>

        <TabsContent value="design" className="mt-6">
          <DesignCustomizer
            design={designConfig}
            onChange={onDesignChange}
          />
        </TabsContent>

        <TabsContent value="templates" className="mt-6">
          <TemplateSelector onSelectTemplate={handleSelectTemplate} />
        </TabsContent>
      </Tabs>

      <div className="flex gap-3">
        {onSave && (
          <Button
            onClick={onSave}
            disabled={isSaving}
            className="gap-2 bg-gradient-to-r from-primary to-primary-glow hover:shadow-glow"
            size="lg"
          >
            <Save className="h-5 w-5" />
            {isSaving ? "Salvando..." : "Salvar Formulário"}
          </Button>
        )}
        <Button
          onClick={saveAsTemplate}
          variant="outline"
          className="gap-2"
        >
          Salvar como Template
        </Button>
      </div>
    </div>
  );
};

src/features/produto/components/ui/alert.content:
import * as React from "react";
import * as AlertDialogPrimitive from "@radix-ui/react-alert-dialog";

import { cn } from "@/features/produto/lib/utils";
import { buttonVariants } from "@/components/ui/button";

const AlertDialog = AlertDialogPrimitive.Root;

const AlertDialogTrigger = AlertDialogPrimitive.Trigger;

const AlertDialogPortal = AlertDialogPrimitive.Portal;

const AlertDialogOverlay = React.forwardRef<
  React.ElementRef<typeof AlertDialogPrimitive.Overlay>,
  React.ComponentPropsWithoutRef<typeof AlertDialogPrimitive.Overlay>
>(({ className, ...props }, ref) => (
  <AlertDialogPrimitive.Overlay
    className={cn(
      "fixed inset-0 z-50 bg-black/80 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0",
      className,
    )}
    {...props}
    ref={ref}
  />
));
AlertDialogOverlay.displayName = AlertDialogPrimitive.Overlay.displayName;

const AlertDialogContent = React.forwardRef<
  React.ElementRef<typeof AlertDialogPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof AlertDialogPrimitive.Content>
>(({ className, ...props }, ref) => (
  <AlertDialogPortal>
    <AlertDialogOverlay />
    <AlertDialogPrimitive.Content
      ref={ref}
      className={cn(
        "fixed left-[50%] top-[50%] z-50 grid w-full max-w-lg translate-x-[-50%] translate-y-[-50%] gap-4 border bg-background p-6 shadow-lg duration-200 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[state=closed]:slide-out-to-left-1/2 data-[state=closed]:slide-out-to-top-[48%] data-[state=open]:slide-in-from-left-1/2 data-[state=open]:slide-in-from-top-[48%] sm:rounded-lg",
        className,
      )}
      {...props}
    />
  </AlertDialogPortal>
));
AlertDialogContent.displayName = AlertDialogPrimitive.Content.displayName;

const AlertDialogHeader = ({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) => (
  <div className={cn("flex flex-col space-y-2 text-center sm:text-left", className)} {...props} />
);
AlertDialogHeader.displayName = "AlertDialogHeader";

const AlertDialogFooter = ({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) => (
  <div className={cn("flex flex-col-reverse sm:flex-row sm:justify-end sm:space-x-2", className)} {...props} />
);
AlertDialogFooter.displayName = "AlertDialogFooter";

const AlertDialogTitle = React.forwardRef<
  React.ElementRef<typeof AlertDialogPrimitive.Title>,
