server/middleware/multiTenantAuth.ts.content:
import { Request, Response, NextFunction } from 'express';

// Extender os tipos do Express Session
declare module 'express-session' {
  interface SessionData {
    userId?: string;
    userEmail?: string;
    userName?: string;
    tenantId?: string;  // Tenant ID para isolamento completo de credenciais
    supabaseUrl?: string;
    supabaseKey?: string;
  }
}

// Middleware para verificar se usuário está autenticado
export function requireAuth(req: Request, res: Response, next: NextFunction) {
  // Em desenvolvimento, permitir acesso mesmo sem sessão (criar tenant temporário)
  if (process.env.NODE_ENV === 'development') {
    if (!req.session || !req.session.userId) {
      const tempTenantId = `dev-tenant-default`;
      console.warn('⚠️ [DEV] Label Designer: Usando tenant temporário para desenvolvimento');

      // Criar sessão temporária se não existir
      if (req.session) {
        req.session.userId = tempTenantId;
        req.session.tenantId = tempTenantId;
        req.session.userEmail = 'dev@example.com';
        req.session.userName = 'Dev User';
      }
    }
    return next();
  }

  // Em produção, exigir autenticação real
  if (!req.session || !req.session.userId) {
    return res.status(401).json({ 
      error: 'Não autenticado',
      redirect: '/login'
    });
  }
  next();
}

// Middleware para adicionar dados do usuário nas requisições
export function attachUserData(req: Request, res: Response, next: NextFunction) {
  if (req.session && req.session.userId) {
    (req as any).user = {
      id: req.session.userId,
      email: req.session.userEmail,
      nome: req.session.userName,
      supabaseUrl: req.session.supabaseUrl,
      supabaseKey: req.session.supabaseKey
    };
  }
  next();
}

// Middleware para verificar se rota é pública (não precisa de autenticação)
export function isPublicRoute(path: string): boolean {
  // Permitir todas as rotas do Vite e assets
  if (path.startsWith('/@') || 
      path.startsWith('/node_modules') ||
      path.startsWith('/src') ||
      path.endsWith('.js') ||
      path.endsWith('.ts') ||
      path.endsWith('.tsx') ||
      path.endsWith('.jsx') ||
      path.endsWith('.css') ||
      path.endsWith('.json') ||
      path.endsWith('.png') ||
      path.endsWith('.jpg') ||
      path.endsWith('.svg') ||
      path.endsWith('.ico')) {
    return true;
  }

  const publicRoutes = [
    '/login',
    '/api/auth/',
    '/api/config/',
    '/health',
    '/assets'
  ];

  return publicRoutes.some(route => path.startsWith(route));
}

// Middleware para redirecionar não autenticados
export function redirectIfNotAuth(req: Request, res: Response, next: NextFunction) {
  // Ignorar rotas públicas, API e assets
  if (isPublicRoute(req.path)) {
    return next();
  }

  // Se não está autenticado e está tentando acessar página protegida
  if (!req.session || !req.session.userId) {
    // Se é API, SEMPRE retornar 401 JSON
    if (req.path.startsWith('/api/')) {
      return res.status(401).json({ 
        error: 'Não autenticado',
        redirect: '/login'
      });
    }

    // Se é página HTML, redirecionar
    if (req.accepts('html')) {
      return res.redirect('/login');
    }

    // Default: 401 JSON
    return res.status(401).json({ 
      error: 'Não autenticado',
      redirect: '/login'
    });
  }

  next();
}

src/features/revendedora/hooks/useCommis.content:
import { useEffect, useState, useCallback } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { SalesTier } from '@/types/database';

export interface CommissionConfig {
  use_dynamic_tiers: boolean;
  sales_tiers: SalesTier[];
}

export interface CommissionResult {
  resellerPercentage: number;
  companyPercentage: number;
  tierName: string;
}

const DEFAULT_TIERS: SalesTier[] = [
  { id: '1', name: 'Iniciante', min_monthly_sales: 0, max_monthly_sales: 2000, reseller_percentage: 70, company_percentage: 30 },
  { id: '2', name: 'Bronze', min_monthly_sales: 2000, max_monthly_sales: 4500, reseller_percentage: 70, company_percentage: 30 },
  { id: '3', name: 'Prata', min_monthly_sales: 4500, max_monthly_sales: 10000, reseller_percentage: 75, company_percentage: 25 },
  { id: '4', name: 'Ouro', min_monthly_sales: 10000, reseller_percentage: 80, company_percentage: 20 },
];

export function useCommissionConfig(resellerId?: string) {
  const [config, setConfig] = useState<CommissionConfig>({
    use_dynamic_tiers: false,
    sales_tiers: DEFAULT_TIERS,
  });
  const [loading, setLoading] = useState(true);
  const [monthlyVolume, setMonthlyVolume] = useState<number>(0);
  const [volumeLoading, setVolumeLoading] = useState(false);

  const fetchConfig = useCallback(async () => {
    try {
      if (!supabase) {
        console.log('[useCommissionConfig] Supabase not configured');
        setLoading(false);
        return;
      }

      const { data, error } = await (supabase as any)
        .from('commission_config')
        .select('*')
        .eq('id', 'default')
        .single();

      if (error) {
        console.log('[useCommissionConfig] No config found, using defaults');
      } else if (data) {
        console.log('[useCommissionConfig] ✅ Config loaded:', data);
        setConfig({
          use_dynamic_tiers: data.use_dynamic_tiers || false,
          sales_tiers: data.sales_tiers?.length > 0 ? data.sales_tiers : DEFAULT_TIERS,
        });
      }
    } catch (error) {
      console.error('[useCommissionConfig] Error:', error);
    } finally {
      setLoading(false);
    }
  }, []);

  const fetchMonthlyVolume = useCallback(async () => {
    if (!resellerId || !supabase) return;

    setVolumeLoading(true);
    try {
      const now = new Date();
      const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);

      const { data, error } = await (supabase as any)
        .from('sales_with_split')
        .select('total_amount')
        .eq('reseller_id', resellerId)
        .eq('paid', true)
        .gte('created_at', startOfMonth.toISOString());

      if (error) {
        console.error('[useCommissionConfig] Error fetching monthly volume:', error);
      } else {
        const volume = (data || []).reduce((sum: number, sale: any) => sum + (sale.total_amount || 0), 0);
        console.log(`[useCommissionConfig] Monthly volume for ${resellerId}: R$ ${volume}`);
        setMonthlyVolume(volume);
      }
    } catch (error) {
      console.error('[useCommissionConfig] Error:', error);
    } finally {
      setVolumeLoading(false);
    }
  }, [resellerId]);

  useEffect(() => {
    fetchConfig();
    fetchMonthlyVolume();

    if (!supabase) return;

    console.log('[useCommissionConfig] 🔴 Setting up REALTIME subscription...');

    const subscription = supabase
      .channel('commission_config_changes')
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'commission_config',
        },
        (payload: any) => {
          console.log('[useCommissionConfig] 📡 Realtime update received:', payload);
          if (payload.new) {
            setConfig({
              use_dynamic_tiers: payload.new.use_dynamic_tiers || false,
              sales_tiers: payload.new.sales_tiers?.length > 0 ? payload.new.sales_tiers : DEFAULT_TIERS,
            });
          }
        }
      )
      .subscribe((status: string) => {
        console.log('[useCommissionConfig] Subscription status:', status);
      });

    return () => {
      console.log('[useCommissionConfig] Cleaning up subscription...');
      subscription.unsubscribe();
    };
  }, [fetchConfig, fetchMonthlyVolume]);

  const calculateCommission = useCallback((volume: number): CommissionResult => {
    if (!config.use_dynamic_tiers) {
      return { resellerPercentage: 70, companyPercentage: 30, tierName: 'Padrão' };
    }

    const sortedTiers = [...config.sales_tiers].sort((a, b) => a.min_monthly_sales - b.min_monthly_sales);

    for (const tier of sortedTiers) {
      const meetsMinimum = volume >= tier.min_monthly_sales;
      const meetsMaximum = tier.max_monthly_sales === undefined || volume < tier.max_monthly_sales;

      if (meetsMinimum && meetsMaximum) {
        return {
          resellerPercentage: tier.reseller_percentage,
          companyPercentage: tier.company_percentage,
          tierName: tier.name,
        };
      }
    }

    if (sortedTiers.length > 0) {
      const lastTier = sortedTiers[sortedTiers.length - 1];
      return {
        resellerPercentage: lastTier.reseller_percentage,
        companyPercentage: lastTier.company_percentage,
        tierName: lastTier.name,
      };
    }

    return { resellerPercentage: 70, companyPercentage: 30, tierName: 'Padrão' };
  }, [config]);

  const getCurrentCommission = useCallback((): CommissionResult => {
    return calculateCommission(monthlyVolume);
  }, [calculateCommission, monthlyVolume]);

  return {
    config,
    loading: loading || volumeLoading,
    monthlyVolume,
    calculateCommission,
    getCurrentCommission,
    refetch: fetchConfig,
  };
}

src/components/label-designer/CanvasEdit.content:
import React, { useEffect, useRef, useImperativeHandle, forwardRef, useState, useCallback } from 'react';
import * as fabricModule from 'fabric';
import JsBarcode from 'jsbarcode';
import QRCode from 'qrcode';
import { CanvasEditorRef, LabelElement } from './types';
import type { LayoutElement, SmartLayout } from './smartLabelLayout';

const fabric = (fabricModule as any).fabric || fabricModule;

interface CanvasEditorProps {
  widthMm: number;
  heightMm: number;
  onSelectionChange?: (object: fabric.Object | null) => void;
  onCanvasChange?: () => void;
  onReady?: () => void;
}

const MM_TO_PX = 10;

export const CanvasEditor = forwardRef<CanvasEditorRef, CanvasEditorProps>(
  ({ widthMm, heightMm, onSelectionChange, onCanvasChange, onReady }, ref) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const fabricCanvasRef = useRef<fabric.Canvas | null>(null);
    const hasCalledOnReady = useRef(false);
    const [canvasVersion, setCanvasVersion] = useState(0);

    useEffect(() => {
      if (!canvasRef.current) return;

      const widthPx = widthMm * MM_TO_PX;
      const heightPx = heightMm * MM_TO_PX;

      const canvas = new fabric.Canvas(canvasRef.current, {
        width: widthPx,
        height: heightPx,
        backgroundColor: '#ffffff',
        selection: true,
      });

      fabricCanvasRef.current = canvas;

      setCanvasVersion(v => v + 1);

      canvas.on('selection:created', (e) => {
        onSelectionChange?.(e.selected?.[0] || null);
      });

      canvas.on('selection:updated', (e) => {
        onSelectionChange?.(e.selected?.[0] || null);
      });

      canvas.on('selection:cleared', () => {
        onSelectionChange?.(null);
      });

      canvas.on('object:modified', () => {
        onCanvasChange?.();
      });

      canvas.on('object:added', () => {
        onCanvasChange?.();
      });

      canvas.on('object:removed', () => {
        onCanvasChange?.();
      });

      if (!hasCalledOnReady.current && onReady) {
        hasCalledOnReady.current = true;
        requestAnimationFrame(() => {
          onReady();
        });
      }

      return () => {
        canvas.dispose();
        fabricCanvasRef.current = null;
      };
    }, [widthMm, heightMm]);

    const addText = () => {
      if (!fabricCanvasRef.current) return;

      const text = new fabric.Textbox('Texto', {
        left: 20,
        top: 20,
        width: 150,
        fontSize: 18,
        fill: '#000000',
        fontFamily: 'Arial',
      });

      fabricCanvasRef.current.add(text);
      fabricCanvasRef.current.setActiveObject(text);
      fabricCanvasRef.current.renderAll();
    };

    const addTextWithContent = (
      content: string, 
      options?: { 
        x?: number; 
        y?: number; 
        width?: number;
        fontSize?: number; 
        fontWeight?: string;
        fontFamily?: string;
        fill?: string;
      }
    ) => {
      if (!fabricCanvasRef.current) return;

      const xPx = (options?.x || 5) * MM_TO_PX;
      const yPx = (options?.y || 5) * MM_TO_PX;
      const widthPx = options?.width ? options.width * MM_TO_PX : (widthMm - 10) * MM_TO_PX;

      const text = new fabric.Textbox(content, {
        left: xPx,
        top: yPx,
        width: widthPx,
        fontSize: options?.fontSize || 12,
        fill: options?.fill || '#000000',
        fontFamily: options?.fontFamily || 'Arial',
        fontWeight: options?.fontWeight || 'normal',
      });

      fabricCanvasRef.current.add(text);
      fabricCanvasRef.current.renderAll();
    };

    const addImage = async (file: File) => {
      if (!fabricCanvasRef.current) return;

      const reader = new FileReader();
      reader.onload = async (e) => {
        const dataUrl = e.target?.result as string;
        try {
          const img = await fabric.Image.fromURL(dataUrl, { crossOrigin: 'anonymous' });
          if (!fabricCanvasRef.current) return;

          img.set({
            left: 20,
            top: 20,
            scaleX: 0.4,
            scaleY: 0.4,
          });

          fabricCanvasRef.current.add(img);
          fabricCanvasRef.current.setActiveObject(img);
          fabricCanvasRef.current.renderAll();
        } catch (error) {
          console.error('[CanvasEditor] Error adding image:', error);
        }
      };
      reader.readAsDataURL(file);
    };

    const addImageAtPosition = async (
      dataUrl: string,
      options: { x: number; y: number; width: number; height: number }
    ) => {
      if (!fabricCanvasRef.current) return;

      try {
        const img = await fabric.Image.fromURL(dataUrl, { crossOrigin: 'anonymous' });
        if (!fabricCanvasRef.current) return;

        const xPx = options.x * MM_TO_PX;
        const yPx = options.y * MM_TO_PX;
        const targetWidth = options.width * MM_TO_PX;
        const targetHeight = options.height * MM_TO_PX;

        const scaleX = targetWidth / (img.width || 100);
        const scaleY = targetHeight / (img.height || 100);
        const scale = Math.min(scaleX, scaleY);

        img.set({
          left: xPx,
          top: yPx,
          scaleX: scale,
          scaleY: scale,
        });

        (img as any).elementType = 'logo';

        fabricCanvasRef.current.add(img);
        fabricCanvasRef.current.renderAll();
      } catch (error) {
        console.error('[CanvasEditor] Error adding positioned image:', error);
      }
    };

    const addLogoPlaceholder = (options: { x: number; y: number; width: number; height: number }) => {
      if (!fabricCanvasRef.current) return;

      const xPx = options.x * MM_TO_PX;
      const yPx = options.y * MM_TO_PX;
      const widthPx = options.width * MM_TO_PX;
      const heightPx = options.height * MM_TO_PX;

      const rect = new fabric.Rect({
        left: 0,
        top: 0,
        width: widthPx,
        height: heightPx,
        fill: '#ffffff',
        stroke: '#000000',
        strokeWidth: 2,
      });

      const text = new fabric.Text('LOGO', {
        left: widthPx / 2,
        top: heightPx / 2,
        fontSize: Math.min(widthPx, heightPx) * 0.35,
        fill: '#000000',
        fontFamily: 'Arial',
        fontWeight: 'bold',
        originX: 'center',
        originY: 'center',
      });

      const group = new fabric.Group([rect, text], {
        left: xPx,
        top: yPx,
      });

      (group as any).elementType = 'logoPlaceholder';
      (group as any).isPlaceholder = true;

      fabricCanvasRef.current.add(group);
      fabricCanvasRef.current.renderAll();
    };

    const addBarcode = async (text: string = 'BJ-0001', options?: { x?: number; y?: number; width?: number; height?: number }) => {
      if (!fabricCanvasRef.current) return;

      try {
        const canvas = document.createElement('canvas');
        const barcodeHeight = options?.height ? options.height * MM_TO_PX * 0.7 : 40;

        JsBarcode(canvas, text, {
          format: 'CODE128',
          displayValue: false,
          height: barcodeHeight,
          width: 2,
        });

        const dataUrl = canvas.toDataURL('image/png');

        const img = await fabric.Image.fromURL(dataUrl, { crossOrigin: 'anonymous' });
        if (!fabricCanvasRef.current) return;

        const xPx = options?.x ? options.x * MM_TO_PX : 20;
        const yPx = options?.y ? options.y * MM_TO_PX : 120;

        if (options?.width && options?.height) {
          const targetWidth = options.width * MM_TO_PX;
          const targetHeight = options.height * MM_TO_PX;
          const scaleX = targetWidth / (img.width || 100);
          const scaleY = targetHeight / (img.height || 50);
          const scale = Math.min(scaleX, scaleY, 1);

          img.set({
            left: xPx,
            top: yPx,
            scaleX: scale,
            scaleY: scale,
          });
        } else {
          img.set({
            left: xPx,
            top: yPx,
            scaleX: 1,
            scaleY: 1,
          });
        }

        (img as any).barcodeValue = text;
        (img as any).elementType = 'barcode';

        fabricCanvasRef.current.add(img);
        fabricCanvasRef.current.renderAll();
      } catch (error) {
        console.error('Error creating barcode:', error);
      }
    };

    const addQRCode = async (text: string = 'https://sua-loja.com', options?: { x?: number; y?: number; size?: number }) => {
      if (!fabricCanvasRef.current) return;

      try {
        const size = options?.size ? options.size * MM_TO_PX : 128;

        const dataUrl = await QRCode.toDataURL(text, {
          width: size,
          margin: 1,
        });

        const img = await fabric.Image.fromURL(dataUrl, { crossOrigin: 'anonymous' });
        if (!fabricCanvasRef.current) return;

        const xPx = options?.x ? options.x * MM_TO_PX : 120;
        const yPx = options?.y ? options.y * MM_TO_PX : 120;

        img.set({
          left: xPx,
          top: yPx,
          scaleX: 0.6,
          scaleY: 0.6,
        });

        (img as any).qrCodeValue = text;
        (img as any).elementType = 'qrcode';

        fabricCanvasRef.current.add(img);
        fabricCanvasRef.current.renderAll();
      } catch (error) {
        console.error('Error creating QR code:', error);
      }
    };

    const loadSmartLayout = async (layout: SmartLayout, companyLogoUrl?: string) => {
      if (!fabricCanvasRef.current) return;

      fabricCanvasRef.current.clear();
      fabricCanvasRef.current.backgroundColor = '#ffffff';

      const textPromises: Promise<void>[] = [];
      const imagePromises: Promise<void>[] = [];

      for (const element of layout.elements) {
        switch (element.type) {
          case 'text':
            if (element.content || element.placeholder) {
              addTextWithContent(
                element.content || '...',
                {
                  x: element.x,
                  y: element.y,
                  width: element.width,
                  fontSize: element.fontSize,
                  fontWeight: element.fontWeight,
                }
              );
            }
            break;

          case 'image':
            if (element.id === 'company-logo') {
              if (companyLogoUrl) {
                imagePromises.push(
                  addImageAtPosition(companyLogoUrl, {
                    x: element.x,
                    y: element.y,
                    width: element.width,
                    height: element.height,
                  })
                );
              } else if (element.placeholder) {
                addLogoPlaceholder({
                  x: element.x,
                  y: element.y,
                  width: element.width,
                  height: element.height,
                });
              }
            }
            break;

          case 'barcode':
            if (element.content) {
              imagePromises.push(
                (async () => {
                  await addBarcode(element.content!, {
                    x: element.x,
                    y: element.y,
                    width: element.width,
                    height: element.height,
                  });
                })()
              );
            }
            break;
        }
      }

      await Promise.all(imagePromises);

      fabricCanvasRef.current.renderAll();
    };

    const deleteSelected = () => {
      if (!fabricCanvasRef.current) return;

      const activeObject = fabricCanvasRef.current.getActiveObject();
      if (activeObject) {
        fabricCanvasRef.current.remove(activeObject);
        fabricCanvasRef.current.renderAll();
      }
    };

    const clearCanvas = () => {
      if (!fabricCanvasRef.current) return;
      fabricCanvasRef.current.clear();
      fabricCanvasRef.current.backgroundColor = '#ffffff';
      fabricCanvasRef.current.renderAll();
    };

    const getElements = (): LabelElement[] => {
      if (!fabricCanvasRef.current) return [];

      const objects = fabricCanvasRef.current.getObjects();
      const elements: LabelElement[] = [];

      objects.forEach((obj) => {
        const left = obj.left || 0;
        const top = obj.top || 0;
        const width = (obj.width || 0) * (obj.scaleX || 1);
        const height = (obj.height || 0) * (obj.scaleY || 1);

        const xMm = left / MM_TO_PX;
        const yMm = top / MM_TO_PX;
        const widthMm = width / MM_TO_PX;
        const heightMm = height / MM_TO_PX;

        if (obj.type === 'textbox' || obj.type === 'text') {
          const textbox = obj as fabric.Textbox;
          elements.push({
            type: 'text',
            text: textbox.text || '',
            x: xMm,
            y: yMm,
            width: widthMm,
            height: heightMm,
            fontSize: textbox.fontSize || 12,
            fontFamily: textbox.fontFamily || 'Arial',
            fill: textbox.fill as string || '#000000',
          });
        } else if ((obj as any).elementType === 'barcode') {
          elements.push({
            type: 'barcode',
            value: (obj as any).barcodeValue || 'BJ-0001',
            data: obj.toDataURL({ format: 'png' }),
            x: xMm,
            y: yMm,
            width: widthMm,
            height: heightMm,
          });
        } else if ((obj as any).elementType === 'qrcode') {
          elements.push({
            type: 'qrcode',
            value: (obj as any).qrCodeValue || 'https://sua-loja.com',
            data: obj.toDataURL({ format: 'png' }),
            x: xMm,
            y: yMm,
            width: widthMm,
            height: heightMm,
          });
        } else if (obj.type === 'image' || (obj as any).elementType === 'logo') {
          elements.push({
            type: 'image',
            data: obj.toDataURL({ format: 'png' }),
            x: xMm,
            y: yMm,
            width: widthMm,
            height: heightMm,
          });
        } else if ((obj as any).elementType === 'logoPlaceholder') {
        }
      });

      return elements;
    };

    const loadDesignData = (data: any) => {
      if (!fabricCanvasRef.current) return;

      fabricCanvasRef.current.loadFromJSON(data, () => {
        fabricCanvasRef.current?.renderAll();
      });
    };

    const getDesignData = () => {
      if (!fabricCanvasRef.current) return null;
      return fabricCanvasRef.current.toJSON(['barcodeValue', 'qrCodeValue', 'elementType', 'isPlaceholder']);
    };

    useImperativeHandle(ref, () => {
      return {
        canvas: fabricCanvasRef.current,
        addText,
        addTextWithContent,
        addImage,
        addImageAtPosition,
        addLogoPlaceholder,
        addBarcode,
        addQRCode,
        loadSmartLayout,
        deleteSelected,
        clearCanvas,
        getElements,
        loadDesignData,
        getDesignData,
      };
    }, [canvasVersion, widthMm, heightMm]);

    return (
      <div className="flex justify-center items-center p-4 bg-gray-100 rounded-lg">
        <div className="bg-white shadow-lg" style={{ padding: '20px' }}>
          <canvas ref={canvasRef} />
        </div>
      </div>
    );
  }
);

