import { useEffect, useState } from 'react';
import { useNotionStore } from '@/stores/notionStore';
import { Sidebar } from './Sidebar';
import { Editor } from './Editor';
import { Topbar } from './Topbar';
import { DatabaseView } from './DatabaseView';
import { FiltersProvider } from '@/contexts/FiltersContext';
import { Board } from '@/components/kanban/Board';
import { useIsMobile } from '@/hooks/use-mobile';
import { Sheet, SheetContent, SheetTrigger } from '@/components/ui/sheet';
import { Button } from '@/components/ui/button';
import { Menu } from 'lucide-react';

export const NotionLayout = () => {
  const { pages, addPage, currentPageId, currentDatabaseId, currentBoardId, getCurrentDatabase, getCurrentBoard, updateBoard } = useNotionStore();
  const currentDatabase = getCurrentDatabase();
  const currentBoard = getCurrentBoard();
  const [filterSidebarOpen, setFilterSidebarOpen] = useState(false);
  const isMobile = useIsMobile();
  const [sidebarOpen, setSidebarOpen] = useState(false);

  useEffect(() => {
    if (pages.length === 0) {
      addPage();
    }
  }, [pages.length, addPage]);

  const hasSelection = currentPageId || currentDatabaseId || currentBoardId;

  // Show loading only if we have pages but no selection yet (edge case)
  if (pages.length > 0 && !hasSelection) {
    return (
      <div className="flex min-h-[calc(100vh-5rem)] items-center justify-center">
        <div className="text-center">
          <p className="text-muted-foreground">Carregando...</p>
        </div>
      </div>
    );
  }

  // If no pages yet, useEffect will add one and trigger re-render
  if (pages.length === 0) {
    return (
      <div className="flex min-h-[calc(100vh-5rem)] items-center justify-center">
        <div className="text-center">
          <p className="text-muted-foreground">Iniciando...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col min-h-[calc(100vh-5rem)] w-full">
      {/* Header - largura total */}
      <div className="border-b border-border bg-background">
        <div className="container mx-auto px-4 sm:px-6 lg:px-8 py-4 sm:py-6">
          <div className="flex items-center gap-4">
            {isMobile && (
              <Sheet open={sidebarOpen} onOpenChange={setSidebarOpen}>
                <SheetTrigger asChild>
                  <Button 
                    variant="outline" 
                    size="icon"
                    className="min-h-[44px] min-w-[44px] touch-manipulation active:scale-95 shrink-0"
                  >
                    <Menu className="h-5 w-5" />
                  </Button>
                </SheetTrigger>
                <SheetContent side="left" className="w-[280px] p-0">
                  <Sidebar />
                </SheetContent>
              </Sheet>
            )}
            <div className="flex-1">
              <h1 className="text-2xl sm:text-4xl font-black text-foreground tracking-tight gradient-text">
                Workspace
              </h1>
              <p className="text-sm sm:text-xl text-muted-foreground/80 mt-1 sm:mt-2">
                Organize suas ideias, projetos e conhecimento em páginas, databases e quadros personalizáveis
              </p>
            </div>
          </div>
        </div>
      </div>

      {/* Sidebar + Content */}
      <div className="flex flex-1 overflow-hidden">
        {!isMobile && (
          <div data-tour="workspace-sidebar">
            <Sidebar />
          </div>
        )}
        <div className="flex flex-1 flex-col">
          <Topbar />
          {currentBoardId && currentBoard ? (
          <FiltersProvider>
            <Board 
              board={currentBoard} 
              onUpdateBoard={(updatedBoard) => updateBoard(currentBoard.id, updatedBoard)}
              filterSidebarOpen={filterSidebarOpen}
              onFilterSidebarChange={setFilterSidebarOpen}
            />
          </FiltersProvider>
        ) : currentDatabaseId && currentDatabase ? (
          <div className="flex-1 overflow-y-auto" data-tour="database-views">
            <div className="max-w-full mx-auto px-8 py-6">
              <DatabaseView database={currentDatabase} />
            </div>
          </div>
        ) : (
          <div data-tour="workspace-editor">
            <Editor />
          </div>
        )}
        </div>
      </div>
    </div>
  );
};

src/components/billing/AttachmentsFilter.content:
import { useState } from 'react';
import { Filter, X, ChevronDown, ChevronUp, Search } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';

export interface FilterOptions {
  searchText: string;
  type: string;
  category: string;
  dateFrom: string;
  dateTo: string;
  amountFrom: string;
  amountTo: string;
  sortBy: string;
  sortOrder: 'asc' | 'desc';
}

interface AttachmentsFiltersProps {
  filters: FilterOptions;
  onFiltersChange: (filters: FilterOptions) => void;
  categories: string[];
}

export default function AttachmentsFilters({ 
  filters, 
  onFiltersChange,
  categories 
}: AttachmentsFiltersProps) {
  const [isExpanded, setIsExpanded] = useState(false);

  const handleFilterChange = (key: keyof FilterOptions, value: string) => {
    onFiltersChange({ ...filters, [key]: value });
  };

  const clearFilters = () => {
    onFiltersChange({
      searchText: '',
      type: 'all',
      category: 'all',
      dateFrom: '',
      dateTo: '',
      amountFrom: '',
      amountTo: '',
      sortBy: 'date',
      sortOrder: 'desc',
    });
  };

  const hasActiveFilters = 
    filters.searchText !== '' ||
    filters.type !== 'all' ||
    filters.category !== 'all' ||
    filters.dateFrom !== '' ||
    filters.dateTo !== '' ||
    filters.amountFrom !== '' ||
    filters.amountTo !== '';

  return (
    <Card className="p-4 space-y-4">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Filter className="h-5 w-5 text-blue-500" />
          <h3 className="font-semibold">Filtros</h3>
          {hasActiveFilters && (
            <span className="px-2 py-0.5 text-xs bg-blue-500 text-white rounded-full">
              Ativos
            </span>
          )}
        </div>

        <div className="flex items-center gap-2">
          {hasActiveFilters && (
            <Button
              variant="ghost"
              size="sm"
              onClick={clearFilters}
              className="text-xs"
            >
              <X className="h-4 w-4 mr-1" />
              Limpar
            </Button>
          )}
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setIsExpanded(!isExpanded)}
          >
            {isExpanded ? (
              <ChevronUp className="h-4 w-4" />
            ) : (
              <ChevronDown className="h-4 w-4" />
            )}
          </Button>
        </div>
      </div>

      {/* Busca por texto (sempre visível) */}
      <div className="relative">
        <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-gray-400" />
        <Input
          type="text"
          placeholder="Buscar por descrição ou estabelecimento..."
          value={filters.searchText}
          onChange={(e) => handleFilterChange('searchText', e.target.value)}
          className="pl-10"
        />
      </div>

      {/* Filtros expandidos */}
      {isExpanded && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 pt-4 border-t">
          {/* Tipo de Arquivo */}
          <div className="space-y-2">
            <Label className="text-sm font-medium">Tipo de Arquivo</Label>
            <Select
              value={filters.type}
              onValueChange={(value) => handleFilterChange('type', value)}
            >
              <SelectTrigger>
                <SelectValue placeholder="Todos" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Todos</SelectItem>
                <SelectItem value="manual">Manual</SelectItem>
                <SelectItem value="receipt">Imagem</SelectItem>
              </SelectContent>
            </Select>
          </div>

          {/* Categoria */}
          <div className="space-y-2">
            <Label className="text-sm font-medium">Categoria</Label>
            <Select
              value={filters.category}
              onValueChange={(value) => handleFilterChange('category', value)}
            >
              <SelectTrigger>
                <SelectValue placeholder="Todas" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Todas</SelectItem>
                {categories.map((cat) => (
                  <SelectItem key={cat} value={cat}>
                    {cat}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* Ordenação */}
          <div className="space-y-2">
            <Label className="text-sm font-medium">Ordenar por</Label>
            <div className="flex gap-2">
              <Select
                value={filters.sortBy}
                onValueChange={(value) => handleFilterChange('sortBy', value)}
              >
                <SelectTrigger className="flex-1">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="date">Data</SelectItem>
                  <SelectItem value="amount">Valor</SelectItem>
                  <SelectItem value="category">Categoria</SelectItem>
                </SelectContent>
              </Select>
              <Button
                variant="outline"
                size="icon"
                onClick={() =>
                  handleFilterChange(
                    'sortOrder',
                    filters.sortOrder === 'asc' ? 'desc' : 'asc'
                  )
                }
              >
                {filters.sortOrder === 'asc' ? '↑' : '↓'}
              </Button>
            </div>
          </div>

          {/* Data Inicial */}
          <div className="space-y-2">
            <Label className="text-sm font-medium">Data Inicial</Label>
            <Input
              type="date"
              value={filters.dateFrom}
              onChange={(e) => handleFilterChange('dateFrom', e.target.value)}
            />
          </div>

          {/* Data Final */}
          <div className="space-y-2">
            <Label className="text-sm font-medium">Data Final</Label>
            <Input
              type="date"
              value={filters.dateTo}
              onChange={(e) => handleFilterChange('dateTo', e.target.value)}
            />
          </div>

          {/* Valor Mínimo */}
          <div className="space-y-2">
            <Label className="text-sm font-medium">Valor Mínimo (R$)</Label>
            <Input
              type="number"
              step="0.01"
              placeholder="0.00"
              value={filters.amountFrom}
              onChange={(e) => handleFilterChange('amountFrom', e.target.value)}
            />
          </div>

          {/* Valor Máximo */}
          <div className="space-y-2">
            <Label className="text-sm font-medium">Valor Máximo (R$)</Label>
            <Input
              type="number"
              step="0.01"
              placeholder="0.00"
              value={filters.amountTo}
              onChange={(e) => handleFilterChange('amountTo', e.target.value)}
            />
          </div>
        </div>
      )}
    </Card>
  );
}

src/features/produto/components/Mobile/M.content:
import { useState, useMemo } from "react";
import { SupplierCard } from "./SupplierCard";
import { FAB } from "./FAB";
import { Input } from "@/features/produto/components/ui/input";
import { Button } from "@/features/produto/components/ui/button";
import { Filter, Download, Upload, Users, Calendar as CalendarIcon } from "lucide-react";
import type { Supplier } from "@/pages/Index";
import { Badge } from "@/features/produto/components/ui/badge";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from "@/features/produto/components/ui/sheet";
import { Label } from "@/features/produto/components/ui/label";
import { Calendar } from "@/features/produto/components/ui/calendar";
import { Popover, PopoverContent, PopoverTrigger } from "@/features/produto/components/ui/popover";
import { format } from "date-fns";
import { cn } from "@/features/produto/lib/utils";
import { ScrollArea } from "@/features/produto/components/ui/scroll-area";

interface MobileSupplierListProps {
  suppliers: Supplier[];
  onAddSupplier: () => void;
  onImportSuppliers: (suppliers: Supplier[]) => void;
  onEdit?: (supplier: Supplier) => void;
}

export const MobileSupplierList = ({
  suppliers,
  onAddSupplier,
  onImportSuppliers,
  onEdit,
}: MobileSupplierListProps) => {
  const [selectedSuppliers, setSelectedSuppliers] = useState<string[]>([]);
  const [filterOpen, setFilterOpen] = useState(false);
  const [filters, setFilters] = useState({
    nome: "",
    cpfCnpj: "",
    cidade: "",
    uf: "",
    email: "",
    telefone: "",
    startDate: undefined as Date | undefined,
    endDate: undefined as Date | undefined,
  });

  const filteredSuppliers = useMemo(() => {
    return suppliers.filter((supplier) => {
      const matchNome = !filters.nome || supplier.nome.toLowerCase().includes(filters.nome.toLowerCase());
      const matchCpfCnpj = !filters.cpfCnpj || supplier.cpfCnpj.includes(filters.cpfCnpj);
      const matchCidade = !filters.cidade || supplier.cidade.toLowerCase().includes(filters.cidade.toLowerCase());
      const matchUf = !filters.uf || supplier.uf.toLowerCase().includes(filters.uf.toLowerCase());
      const matchEmail = !filters.email || supplier.email.toLowerCase().includes(filters.email.toLowerCase());
      const matchTelefone = !filters.telefone || supplier.telefone.includes(filters.telefone);

      return matchNome && matchCpfCnpj && matchCidade && matchUf && matchEmail && matchTelefone;
    });
  }, [suppliers, filters]);

  const activeFiltersCount = 
    Object.entries(filters).filter(([key, value]) => {
      if (key === 'startDate' || key === 'endDate') return value !== undefined;
      return value !== "";
    }).length;

  const handleSelectSupplier = (id: string) => {
    setSelectedSuppliers((prev) =>
      prev.includes(id) ? prev.filter((p) => p !== id) : [...prev, id]
    );
  };

  return (
    <div className="flex flex-col h-full bg-gray-50 dark:bg-gray-950 pb-20">
      {/* Action Bar - Only Import, Export, and Filter */}
      <div className="sticky top-14 bg-white dark:bg-gray-900 border-b border-gray-200 dark:border-gray-800 p-4 z-30">
        <div className="flex gap-2">
          <Button variant="outline" size="sm" className="flex-1" data-testid="button-import">
            <Upload className="w-4 h-4 mr-2" />
            Importar
          </Button>
          <Button variant="outline" size="sm" className="flex-1" data-testid="button-export">
            <Download className="w-4 h-4 mr-2" />
            Exportar
          </Button>

          <Sheet open={filterOpen} onOpenChange={setFilterOpen}>
            <SheetTrigger asChild>
              <Button variant="outline" size="sm" className="relative" data-testid="button-filter">
                <Filter className="w-4 h-4 mr-2" />
                Filtro
                {activeFiltersCount > 0 && (
                  <Badge className="absolute -top-1 -right-1 h-5 w-5 flex items-center justify-center p-0 text-[10px]">
                    {activeFiltersCount}
                  </Badge>
                )}
              </Button>
            </SheetTrigger>
            <SheetContent side="bottom" className="h-[85vh]">
              <SheetHeader>
                <SheetTitle>Filtros</SheetTitle>
              </SheetHeader>
              <ScrollArea className="h-[calc(85vh-120px)] mt-4">
                <div className="space-y-4 pr-4">
                  <div>
                    <Label>Nome</Label>
                    <Input
                      placeholder="Buscar por nome..."
                      value={filters.nome}
                      onChange={(e) => setFilters({ ...filters, nome: e.target.value })}
                      data-testid="input-filter-nome"
                    />
                  </div>

                  <div>
                    <Label>CPF/CNPJ</Label>
                    <Input
                      placeholder="Buscar por CPF ou CNPJ..."
                      value={filters.cpfCnpj}
                      onChange={(e) => setFilters({ ...filters, cpfCnpj: e.target.value })}
                      data-testid="input-filter-cpfCnpj"
                    />
                  </div>

                  <div>
                    <Label>Cidade</Label>
                    <Input
                      placeholder="Ex: São Paulo, Rio de Janeiro..."
                      value={filters.cidade}
                      onChange={(e) => setFilters({ ...filters, cidade: e.target.value })}
                      data-testid="input-filter-cidade"
                    />
                  </div>

                  <div>
                    <Label>Estado (UF)</Label>
                    <Input
                      placeholder="Ex: SP, RJ, MG..."
                      maxLength={2}
                      value={filters.uf}
                      onChange={(e) => setFilters({ ...filters, uf: e.target.value })}
                      data-testid="input-filter-uf"
                    />
                  </div>

                  <div>
                    <Label>Email</Label>
                    <Input
                      type="email"
                      placeholder="Filtrar por email..."
                      value={filters.email}
                      onChange={(e) => setFilters({ ...filters, email: e.target.value })}
                      data-testid="input-filter-email"
                    />
                  </div>

                  <div>
                    <Label>Telefone</Label>
                    <Input
                      placeholder="Filtrar por telefone..."
                      value={filters.telefone}
                      onChange={(e) => setFilters({ ...filters, telefone: e.target.value })}
                      data-testid="input-filter-telefone"
                    />
                  </div>

                  <div>
                    <Label>Data Inicial</Label>
                    <Popover>
                      <PopoverTrigger asChild>
                        <Button
                          variant="outline"
                          className={cn(
                            "w-full justify-start text-left font-normal",
                            !filters.startDate && "text-muted-foreground"
                          )}
                          data-testid="button-filter-startDate"
                        >
                          <CalendarIcon className="mr-2 h-4 w-4" />
                          {filters.startDate ? format(filters.startDate, "dd/MM/yyyy") : "Selecione a data"}
                        </Button>
                      </PopoverTrigger>
                      <PopoverContent className="w-auto p-0" align="start">
                        <Calendar
                          mode="single"
                          selected={filters.startDate}
                          onSelect={(date) => setFilters({ ...filters, startDate: date })}
                          initialFocus
                        />
                      </PopoverContent>
                    </Popover>
                  </div>

                  <div>
                    <Label>Data Final</Label>
                    <Popover>
                      <PopoverTrigger asChild>
                        <Button
                          variant="outline"
                          className={cn(
                            "w-full justify-start text-left font-normal",
                            !filters.endDate && "text-muted-foreground"
                          )}
                          data-testid="button-filter-endDate"
                        >
                          <CalendarIcon className="mr-2 h-4 w-4" />
                          {filters.endDate ? format(filters.endDate, "dd/MM/yyyy") : "Selecione a data"}
                        </Button>
                      </PopoverTrigger>
                      <PopoverContent className="w-auto p-0" align="start">
                        <Calendar
                          mode="single"
                          selected={filters.endDate}
                          onSelect={(date) => setFilters({ ...filters, endDate: date })}
                          initialFocus
                        />
                      </PopoverContent>
                    </Popover>
                  </div>
                </div>
              </ScrollArea>

              <div className="flex gap-2 pt-4 border-t">
                <Button
                  variant="outline"
                  className="flex-1"
                  onClick={() => setFilters({ 
                    nome: "", 
                    cpfCnpj: "", 
                    cidade: "", 
                    uf: "", 
                    email: "", 
                    telefone: "",
                    startDate: undefined,
                    endDate: undefined
                  })}
                  data-testid="button-clear-filters"
                >
                  Limpar
                </Button>
                <Button
                  className="flex-1"
                  onClick={() => setFilterOpen(false)}
                  data-testid="button-apply-filters"
                >
                  Aplicar
                </Button>
              </div>
            </SheetContent>
          </Sheet>
        </div>
      </div>

      {/* Results Count */}
      <div className="px-4 py-2 bg-gray-50 dark:bg-gray-950">
        <p className="text-sm text-gray-600 dark:text-gray-400" data-testid="text-results-count">
          {filteredSuppliers.length} {filteredSuppliers.length === 1 ? "fornecedor" : "fornecedores"}
          {selectedSuppliers.length > 0 && ` · ${selectedSuppliers.length} selecionado(s)`}
        </p>
      </div>

      {/* Supplier List */}
      <div className="flex-1 overflow-auto px-4 space-y-3 py-3">
        {filteredSuppliers.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-64 text-center">
            <Users className="w-16 h-16 text-gray-300 dark:text-gray-700 mb-4" />
            <p className="text-gray-500 dark:text-gray-400" data-testid="text-no-suppliers">
              Nenhum fornecedor encontrado
            </p>
          </div>
        ) : (
          filteredSuppliers.map((supplier) => (
            <SupplierCard
              key={supplier.id}
              supplier={supplier}
              onSelect={handleSelectSupplier}
              isSelected={selectedSuppliers.includes(supplier.id)}
            />
          ))
        )}
      </div>

      {/* FAB */}
      <FAB onClick={onAddSupplier} label="Novo Fornecedor" />
    </div>
  );
};

src/features/revendedora/pages/admin/Pro.content:
import { useState, useEffect } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Search, Package, Plus, Pencil, Trash2, Bell, Settings, AlertTriangle, BarChart3, Boxes } from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { toast } from 'sonner';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { Button } from '@/components/ui/button';
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '@/components/ui/tooltip';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { BestSellingProducts } from '@/components/inventory/BestSellingProducts';
import { LowStockAlert } from '@/components/inventory/LowStockAlert';
import { ProductEditModal } from '@/components/inventory/ProductEditModal';
import { StockForecastPanel } from '@/components/inventory/StockForecastPanel';
import { ProductInventorySettingsModal } from '@/components/inventory/ProductInventorySettingsModal';
import { useProductAnalytics } from '@/hooks/useProductAnalytics';

interface Product {
  id: string;
  description: string | null;
  reference: string | null;
  image: string | null;
  barcode: string | null;
  category: string | null;
  price: number | null;
  stock: number | null;
  low_stock_threshold?: number | null;
  notify_low_stock?: boolean;
}

export default function AdminProducts() {
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [editModalOpen, setEditModalOpen] = useState(false);
  const [inventorySettingsProduct, setInventorySettingsProduct] = useState<any>(null);
  const [inventorySettingsOpen, setInventorySettingsOpen] = useState(false);

  const { bestSellers, lowStockProducts, loading: analyticsLoading, refetch: refetchAnalytics } = useProductAnalytics();

  useEffect(() => {
    loadProducts();
  }, []);

  const loadProducts = async () => {
    try {
      const { data, error } = await supabase
        .from('products')
        .select('*')
        .order('description');

      if (error) throw error;
      setProducts(data || []);
    } catch (error) {
      console.error('Error loading products:', error);
      toast.error('Erro ao carregar produtos');
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = (product: Product) => {
    setEditingProduct(product);
    setEditModalOpen(true);
  };

  const handleSaved = () => {
    loadProducts();
    refetchAnalytics();
  };

  const filteredProducts = products.filter(product =>
    (product.description || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
    (product.barcode || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
    (product.reference || '').toLowerCase().includes(searchTerm.toLowerCase())
  );

  const getStockStatus = (product: Product) => {
    const stock = product.stock ?? 0;
    const threshold = product.low_stock_threshold ?? 5;

    if (stock === 0) return 'out_of_stock';
    if (stock <= threshold) return 'low_stock';
    return 'in_stock';
  };

  const formatCurrency = (value: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value);

  if (loading) {
    return <div className="flex items-center justify-center h-64">Carregando produtos...</div>;
  }

  const handleOpenInventorySettings = (product: any) => {
    setInventorySettingsProduct(product);
    setInventorySettingsOpen(true);
  };

  const handleInventorySettingsSaved = () => {
    loadProducts();
    refetchAnalytics();
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row items-start sm:items-center gap-4 sm:justify-between">
        <div>
          <h1 className="text-2xl sm:text-3xl font-bold">Gerenciar Produtos</h1>
          <p className="text-muted-foreground text-sm sm:text-base">
            Gerencie o catálogo de produtos da plataforma
          </p>
        </div>
        <Button className="w-full sm:w-auto">
          <Plus className="mr-2 h-4 w-4" />
          Novo Produto
        </Button>
      </div>

      {lowStockProducts.length > 0 && (
        <LowStockAlert products={lowStockProducts} loading={analyticsLoading} compact />
      )}

      <Tabs defaultValue="catalog" className="w-full">
        <TabsList className="grid w-full grid-cols-2 max-w-md">
          <TabsTrigger value="catalog" className="flex items-center gap-2">
            <Boxes className="h-4 w-4" />
            Catálogo
          </TabsTrigger>
          <TabsTrigger value="forecasting" className="flex items-center gap-2">
            <BarChart3 className="h-4 w-4" />
            Projeções de Estoque
          </TabsTrigger>
        </TabsList>

        <TabsContent value="catalog" className="space-y-6 mt-6">
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2">
              <BestSellingProducts products={bestSellers} loading={analyticsLoading} />
            </div>
            <div>
              <LowStockAlert products={lowStockProducts} loading={analyticsLoading} />
            </div>
          </div>

      <Card>
        <CardHeader>
          <CardTitle>Catálogo de Produtos</CardTitle>
          <CardDescription>
            {products.length} produto{products.length !== 1 ? 's' : ''} cadastrado{products.length !== 1 ? 's' : ''}
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="mb-4">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input
                placeholder="Buscar por descrição, código de barras ou referência..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-9 min-h-[44px]"
              />
            </div>
          </div>

          <div className="overflow-x-auto -mx-4 px-4">
            <Table className="min-w-[600px]">
            <TableHeader>
              <TableRow>
                <TableHead>Imagem</TableHead>
                <TableHead>Descrição</TableHead>
                <TableHead className="hidden sm:table-cell">Código de Barras</TableHead>
                <TableHead className="hidden sm:table-cell">Categoria</TableHead>
                <TableHead>Preço</TableHead>
                <TableHead>Estoque</TableHead>
                <TableHead className="hidden sm:table-cell">Alerta</TableHead>
                <TableHead className="text-right">Ações</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {filteredProducts.map((product) => {
                const stockStatus = getStockStatus(product);
                const threshold = product.low_stock_threshold ?? 5;
                const hasNotification = product.notify_low_stock !== false;

                return (
                  <TableRow key={product.id} className={stockStatus === 'out_of_stock' ? 'bg-red-50/50' : stockStatus === 'low_stock' ? 'bg-orange-50/50' : ''}>
                    <TableCell>
                      <div className="h-12 w-12 rounded-md bg-muted flex items-center justify-center overflow-hidden">
                        {product.image ? (
                          <img src={product.image} alt={product.description || 'Produto'} className="h-full w-full object-cover" />
                        ) : (
                          <Package className="h-6 w-6 text-muted-foreground" />
                        )}
                      </div>
                    </TableCell>
                    <TableCell>
                      <div>
                        <div className="font-medium">{product.description || 'Sem descrição'}</div>
                        {product.reference && (
                          <div className="text-sm text-muted-foreground">
                            Ref: {product.reference}
                          </div>
                        )}
                      </div>
                    </TableCell>
                    <TableCell className="hidden sm:table-cell font-mono text-sm">{product.barcode || '-'}</TableCell>
                    <TableCell className="hidden sm:table-cell">
                      {product.category && (
                        <Badge variant="secondary">{product.category}</Badge>
                      )}
                    </TableCell>
                    <TableCell className="font-semibold">
                      {product.price ? formatCurrency(product.price) : '-'}
                    </TableCell>
                    <TableCell>
                      {product.stock !== null && product.stock !== undefined ? (
                        stockStatus === 'out_of_stock' ? (
                          <Badge variant="destructive">Esgotado</Badge>
                        ) : stockStatus === 'low_stock' ? (
                          <TooltipProvider>
                            <Tooltip>
                              <TooltipTrigger>
                                <Badge className="bg-orange-500 hover:bg-orange-600 flex items-center gap-1">
                                  <AlertTriangle className="h-3 w-3" />
                                  {product.stock} un.
                                </Badge>
                              </TooltipTrigger>
                              <TooltipContent>
                                <p>Estoque baixo! Limite: {threshold} un.</p>
                              </TooltipContent>
                            </Tooltip>
                          </TooltipProvider>
                        ) : (
                          <Badge variant="default">{product.stock} un.</Badge>
                        )
                      ) : (
                        <Badge variant="outline">-</Badge>
                      )}
                    </TableCell>
                    <TableCell className="hidden sm:table-cell">
                      <TooltipProvider>
                        <Tooltip>
                          <TooltipTrigger>
                            <div className={`flex items-center gap-1 text-sm ${hasNotification ? 'text-primary' : 'text-muted-foreground'}`}>
                              <Bell className={`h-4 w-4 ${hasNotification ? 'fill-current' : ''}`} />
                              <span className="text-xs">{threshold}</span>
                            </div>
                          </TooltipTrigger>
                          <TooltipContent>
                            <p>{hasNotification ? `Notificar quando atingir ${threshold} unidades` : 'Notificações desativadas'}</p>
                          </TooltipContent>
                        </Tooltip>
                      </TooltipProvider>
                    </TableCell>
                    <TableCell className="text-right">
                      <div className="flex items-center justify-end gap-1 sm:gap-2">
                        <TooltipProvider>
                          <Tooltip>
                            <TooltipTrigger asChild>
                              <Button variant="ghost" size="icon" className="h-9 w-9 sm:h-8 sm:w-8" onClick={() => handleEdit(product)}>
                                <Settings className="h-4 w-4" />
                              </Button>
                            </TooltipTrigger>
                            <TooltipContent>
                              <p>Configurar produto e alertas</p>
                            </TooltipContent>
                          </Tooltip>
                        </TooltipProvider>
                        <Button variant="ghost" size="icon" className="h-9 w-9 sm:h-8 sm:w-8" onClick={() => handleEdit(product)}>
                          <Pencil className="h-4 w-4" />
                        </Button>
                        <Button variant="ghost" size="icon" className="h-9 w-9 sm:h-8 sm:w-8">
                          <Trash2 className="h-4 w-4 text-destructive" />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                );
              })}
              </TableBody>
            </Table>
          </div>

          {filteredProducts.length === 0 && (
            <div className="text-center py-12">
              <Package className="mx-auto h-12 w-12 text-muted-foreground mb-4" />
              <p className="text-muted-foreground">
                {searchTerm ? 'Nenhum produto encontrado' : 'Nenhum produto cadastrado'}
              </p>
              {!searchTerm && (
                <Button className="mt-4">
                  <Plus className="mr-2 h-4 w-4" />
                  Adicionar Primeiro Produto
                </Button>
              )}
            </div>
          )}
        </CardContent>
      </Card>
        </TabsContent>

        <TabsContent value="forecasting" className="mt-6">
          <StockForecastPanel onConfigureProduct={handleOpenInventorySettings} />
        </TabsContent>
      </Tabs>

      <ProductEditModal
        product={editingProduct}
        open={editModalOpen}
        onOpenChange={setEditModalOpen}
        onSaved={handleSaved}
      />

      <ProductInventorySettingsModal
        product={inventorySettingsProduct}
        isOpen={inventorySettingsOpen}
        onClose={() => setInventorySettingsOpen(false)}
        onSave={handleInventorySettingsSaved}
      />
    </div>
  );
}

