import { useQuery, useQueryClient } from "@tanstack/react-query";
import { fetchWithPluggyAuth } from "@/lib/pluggyClient";
import { Transaction, Bill } from "@/lib/financialUtils";

interface Item {
  id: string;
  connector_id: number;
  connector_name: string;
  status: string;
  execution_status: string;
  created_at: string;
  updated_at: string;
}

interface Account {
  id: string;
  type: string;
  name: string;
  balance: number;
  currencyCode: string;
  itemId: string;
}

interface HybridInvoice {
  mes: string;
  ano: number;
  mesKey: string;
  valor: number;
  fonte: 'bill' | 'calculado';
  transacoes?: number;
  detalhes?: string;
}

export function useItems() {
  return useQuery({
    queryKey: ['/api/items'],
    queryFn: async () => {
      try {
        console.log('🔄 useItems: Iniciando busca de items...');

        const syncRes = await fetchWithPluggyAuth('/api/sync-items', { method: 'POST' });
        if (syncRes.ok) {
          const syncData = await syncRes.json();
          console.log(`✨ Sincronização completa:`, syncData);
        } else {
          console.warn('⚠️ Sincronização falhou, mas continuando...');
        }

        console.log('📡 Buscando items do banco...');
        const res = await fetch('/api/items');
        if (!res.ok) {
          console.error('❌ Erro ao buscar items:', res.status, res.statusText);
          throw new Error('Failed to fetch items');
        }
        const data = await res.json();
        console.log(`📦 ${data.length} item(s) carregados do cache:`, data);
        return data as Item[];
      } catch (error) {
        console.error('❌ Erro completo no useItems:', error);
        throw error;
      }
    },
    staleTime: 5 * 60 * 1000,
  });
}

export function useAccounts(itemId: string | null) {
  return useQuery({
    queryKey: itemId ? [`/api/pluggy/items/${itemId}/accounts`] : null,
    queryFn: async () => {
      if (!itemId) return [];
      const res = await fetchWithPluggyAuth(`/api/pluggy/items/${itemId}/accounts`);
      if (!res.ok) throw new Error('Failed to fetch accounts');
      const data = await res.json();
      console.log(`🏦 ${data.length} conta(s) carregadas do cache`);
      return data as Account[];
    },
    enabled: !!itemId,
    staleTime: Infinity,
  });
}

export function useTransactions(accountId: string | null) {
  return useQuery({
    queryKey: accountId ? [`/api/pluggy/transactions/${accountId}`] : null,
    queryFn: async () => {
      if (!accountId) return [];

      const allTransactions: Transaction[] = [];
      let currentPage = 1;
      const maxPages = 20;

      while (currentPage <= maxPages) {
        const res = await fetchWithPluggyAuth(
          `/api/pluggy/transactions?accountId=${accountId}&page=${currentPage}`
        );

        if (!res.ok) break;

        const data = await res.json();
        const transactions = data.results || [];

        if (transactions.length === 0) break;

        allTransactions.push(...transactions);

        if (currentPage >= data.totalPages) break;
        currentPage++;
      }

      console.log(`✅ ${allTransactions.length} transações carregadas do cache`);
      return allTransactions;
    },
    enabled: !!accountId,
    staleTime: Infinity,
  });
}

export function useBills(accountId: string | null) {
  return useQuery({
    queryKey: accountId ? [`/api/pluggy/bills/${accountId}`] : null,
    queryFn: async () => {
      if (!accountId) return [];

      const res = await fetchWithPluggyAuth(`/api/pluggy/bills?accountId=${accountId}`);
      if (!res.ok) return [];

      const data = await res.json();
      const bills = data.results || [];
      console.log(`📊 ${bills.length} faturas (bills) carregadas do cache`);
      return bills as Bill[];
    },
    enabled: !!accountId,
    staleTime: Infinity,
  });
}

export function useHybridInvoices(accountId: string | null) {
  return useQuery({
    queryKey: accountId ? [`/api/pluggy/faturas-hibridas/${accountId}`] : null,
    queryFn: async () => {
      if (!accountId) return [];

      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 30000);

      const response = await fetchWithPluggyAuth(`/api/pluggy/faturas-hibridas/${accountId}`, {
        signal: controller.signal
      });
      clearTimeout(timeoutId);

      if (!response.ok) return [];

      const data = await response.json();
      console.log(`✅ ${data.faturas?.length || 0} faturas híbridas carregadas do cache`);
      return (data.faturas || []) as HybridInvoice[];
    },
    enabled: !!accountId,
    staleTime: Infinity,
  });
}

export function useRefreshData() {
  const queryClient = useQueryClient();

  return {
    refreshAll: () => {
      console.log('🔄 Invalidando todos os caches...');
      queryClient.invalidateQueries();
    },
    refreshItems: () => {
      console.log('🔄 Invalidando cache de items...');
      queryClient.invalidateQueries({ queryKey: ['/api/items'] });
    },
    refreshAccounts: (itemId: string) => {
      console.log('🔄 Invalidando cache de contas...');
      queryClient.invalidateQueries({ queryKey: [`/api/pluggy/items/${itemId}/accounts`] });
    },
    refreshTransactions: (accountId: string) => {
      console.log('🔄 Invalidando cache de transações...');
      queryClient.invalidateQueries({ queryKey: [`/api/pluggy/transactions/${accountId}`] });
    },
    refreshInvoices: (accountId: string) => {
      console.log('🔄 Invalidando cache de faturas...');
      queryClient.invalidateQueries({ queryKey: [`/api/pluggy/faturas-hibridas/${accountId}`] });
    },
  };
}

src/hooks/useBiometric.ts.content:
import { useState, useCallback } from 'react';
import {
  startRegistration,
  startAuthentication,
} from '@simplewebauthn/browser';
import type {
  RegistrationResponseJSON,
  AuthenticationResponseJSON,
} from '@simplewebauthn/browser';
import { toast } from 'sonner';

export const useBiometric = () => {
  const [isRegistering, setIsRegistering] = useState(false);
  const [isAuthenticating, setIsAuthenticating] = useState(false);
  const [isSupported, setIsSupported] = useState(false);

  const checkSupport = useCallback(async () => {
    const supported = 
      window.PublicKeyCredential !== undefined &&
      typeof window.PublicKeyCredential === 'function';

    console.log('🔐 Verificação de suporte biométrico:', {
      supported,
      PublicKeyCredential: window.PublicKeyCredential,
      isSecureContext: window.isSecureContext,
      protocol: window.location.protocol,
    });

    setIsSupported(supported);
    return supported;
  }, []);

  const registerBiometric = useCallback(async (email: string) => {
    try {
      setIsRegistering(true);

      const supported = await checkSupport();
      if (!supported) {
        toast.error('Autenticação biométrica não suportada', {
          description: 'Seu navegador ou dispositivo não suporta autenticação biométrica.',
        });
        return false;
      }

      const optionsResponse = await fetch('/api/biometric/register/options', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email }),
      });

      if (!optionsResponse.ok) {
        const error = await optionsResponse.json();
        toast.error('Erro ao configurar biometria', {
          description: error.error || 'Não foi possível iniciar o registro.',
        });
        return false;
      }

      const { options } = await optionsResponse.json();

      const attResp: RegistrationResponseJSON = await startRegistration(options);

      const verifyResponse = await fetch('/api/biometric/register/verify', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ response: attResp }),
      });

      const verification = await verifyResponse.json();

      if (verification.verified) {
        toast.success('Biometria configurada!', {
          description: 'Agora você pode fazer login com impressão digital ou Face ID.',
        });
        return true;
      } else {
        toast.error('Falha na verificação', {
          description: 'Não foi possível verificar sua biometria.',
        });
        return false;
      }
    } catch (error: any) {
      console.error('Erro ao registrar biometria:', error);

      if (error.name === 'NotAllowedError') {
        toast.error('Registro cancelado', {
          description: 'Você cancelou o registro biométrico.',
        });
      } else if (error.name === 'InvalidStateError') {
        toast.error('Biometria já registrada', {
          description: 'Este dispositivo já está registrado.',
        });
      } else {
        toast.error('Erro ao registrar biometria', {
          description: error.message || 'Tente novamente mais tarde.',
        });
      }
      return false;
    } finally {
      setIsRegistering(false);
    }
  }, [checkSupport]);

  const authenticateWithBiometric = useCallback(async (email: string) => {
    try {
      setIsAuthenticating(true);

      const supported = await checkSupport();
      if (!supported) {
        toast.error('Autenticação biométrica não suportada', {
          description: 'Seu navegador ou dispositivo não suporta autenticação biométrica.',
        });
        return null;
      }

      const optionsResponse = await fetch('/api/biometric/authenticate/options', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email }),
      });

      if (!optionsResponse.ok) {
        const error = await optionsResponse.json();

        if (optionsResponse.status === 404) {
          toast.info('Biometria não configurada', {
            description: 'Configure sua biometria primeiro para usar este recurso.',
          });
        } else {
          toast.error('Erro ao autenticar', {
            description: error.error || 'Não foi possível iniciar a autenticação.',
          });
        }
        return null;
      }

      const { options } = await optionsResponse.json();

      const asseResp: AuthenticationResponseJSON = await startAuthentication(options);

      const verifyResponse = await fetch('/api/biometric/authenticate/verify', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ response: asseResp }),
      });

      const verification = await verifyResponse.json();

      if (verification.verified) {
        toast.success('Autenticação bem-sucedida!', {
          description: 'Bem-vindo de volta!',
        });
        return verification.email;
      } else {
        toast.error('Falha na autenticação', {
          description: 'Não foi possível verificar sua biometria.',
        });
        return null;
      }
    } catch (error: any) {
      console.error('Erro ao autenticar com biometria:', error);

      if (error.name === 'NotAllowedError') {
        toast.error('Autenticação cancelada', {
          description: 'Você cancelou a autenticação biométrica.',
        });
      } else {
        toast.error('Erro ao autenticar', {
          description: error.message || 'Tente novamente mais tarde.',
        });
      }
      return null;
    } finally {
      setIsAuthenticating(false);
    }
  }, [checkSupport]);

  return {
    isRegistering,
    isAuthenticating,
    isSupported,
    checkSupport,
    registerBiometric,
    authenticateWithBiometric,
  };
};

