}

const getStatusColor = (status: string) => {
  switch (status) {
    case 'active':
      return 'default';
    case 'pending':
      return 'secondary';
    case 'inactive':
      return 'outline';
    case 'blocked':
      return 'destructive';
    default:
      return 'secondary';
  }
};

const getStatusLabel = (status: string) => {
  switch (status) {
    case 'active':
      return 'Ativo';
    case 'pending':
      return 'Pendente';
    case 'inactive':
      return 'Inativo';
    case 'blocked':
      return 'Bloqueado';
    default:
      return status;
  }
};

export function ResellerCard({ reseller, onClick }: ResellerCardProps) {
  return (
    <Card className="cursor-pointer hover:shadow-lg transition-shadow" onClick={onClick}>
