import { useState, useEffect } from 'react';
import { supabase } from '@/features/revendedora/integrations/supabase/client';
import { useCompany } from '@/features/revendedora/contexts/CompanyContext';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/features/revendedora/components/ui/card';
import { Input } from '@/features/revendedora/components/ui/input';
import { Search, Package } from 'lucide-react';
import { Badge } from '@/features/revendedora/components/ui/badge';
import { toast } from 'sonner';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/features/revendedora/components/ui/table';
import { Button } from '@/features/revendedora/components/ui/button';
import { useNavigate } from 'react-router-dom';

export default function ResellerProducts() {
  const { loading: companyLoading } = useCompany();
  const navigate = useNavigate();
  const [products, setProducts] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    loadProducts();
  }, []);

  const loadProducts = async () => {
    try {
      const { data, error } = await supabase
        .from('products')
        .select('*')
        .order('description');

      if (error) throw error;
      setProducts(data || []);
    } catch (error) {
      console.error('Error loading products:', error);
      toast.error('Erro ao carregar produtos');
    } finally {
      setLoading(false);
    }
  };

  const filteredProducts = products.filter(product =>
    (product.description || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
    (product.barcode || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
    (product.reference || '').toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading || companyLoading) {
    return <div className="flex items-center justify-center h-64">Carregando...</div>;
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Produtos</h1>
          <p className="text-muted-foreground">
            Catálogo de produtos disponíveis
          </p>
        </div>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Catálogo de Produtos</CardTitle>
          <CardDescription>
            {products.length} produto{products.length !== 1 ? 's' : ''} disponíve{products.length !== 1 ? 'is' : 'l'}
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="mb-4">
            <div className="relative">
              <Search className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
              <Input
                placeholder="Buscar produtos..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-9"
              />
            </div>
          </div>

          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Imagem</TableHead>
                <TableHead>Descrição</TableHead>
                <TableHead>Código de Barras</TableHead>
                <TableHead>Categoria</TableHead>
                <TableHead>Preço</TableHead>
                <TableHead>Estoque</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {filteredProducts.map((product) => (
                <TableRow key={product.id}>
                  <TableCell>
                    <div className="h-12 w-12 rounded-md bg-muted flex items-center justify-center overflow-hidden">
                      {product.image ? (
                        <img src={product.image} alt={product.description || 'Produto'} className="h-full w-full object-cover" />
                      ) : (
                        <Package className="h-6 w-6 text-muted-foreground" />
                      )}
                    </div>
                  </TableCell>
                  <TableCell>
                    <div>
                      <div className="font-medium">{product.description || 'Sem descrição'}</div>
                      {product.reference && (
                        <div className="text-sm text-muted-foreground">
                          Ref: {product.reference}
                        </div>
                      )}
                    </div>
                  </TableCell>
                  <TableCell className="font-mono text-sm">{product.barcode || '-'}</TableCell>
                  <TableCell>
                    {product.category && (
                      <Badge variant="secondary">{product.category}</Badge>
                    )}
                  </TableCell>
                  <TableCell className="font-semibold">
                    {product.price ? new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(product.price) : '-'}
                  </TableCell>
                  <TableCell>
                    {product.stock !== null && product.stock !== undefined ? (
                      product.stock > 0 ? (
                        <Badge variant="default">{product.stock} un.</Badge>
                      ) : (
                        <Badge variant="secondary">Esgotado</Badge>
                      )
                    ) : (
                      <Badge variant="outline">-</Badge>
                    )}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>

          {filteredProducts.length === 0 && (
            <div className="text-center py-12">
              <Package className="mx-auto h-12 w-12 text-muted-foreground mb-4" />
              <p className="text-muted-foreground">Nenhum produto encontrado</p>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

src/components/kanban/card-detail/CardCu.content:
import { Card } from '@/types/kanban';
import { Settings, Trash2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';

interface CardCustomFieldsSectionProps {
  card: Card;
  onUpdate: (card: Card) => void;
}

export const CardCustomFieldsSection = ({ card, onUpdate }: CardCustomFieldsSectionProps) => {
  const deleteCustomField = (fieldId: string) => {
    const updatedFields = card.customFields.filter((f) => f.id !== fieldId);
    onUpdate({ ...card, customFields: updatedFields });
  };

  const updateCustomField = (fieldId: string, value: string) => {
    const updatedFields = card.customFields.map((field) =>
      field.id === fieldId ? { ...field, value } : field
    );
    onUpdate({ ...card, customFields: updatedFields });
  };

  if (card.customFields.length === 0) return null;

  return (
    <div>
      <div className="flex items-center gap-3 mb-3">
        <Settings className="w-5 h-5 text-muted-foreground" />
        <h3 className="font-semibold">Campos personalizados</h3>
      </div>
      <div className="space-y-3">
        {card.customFields.map((field) => (
          <div key={field.id} className="flex items-center gap-3 group">
            <div className="flex-1">
              <div className="flex items-center gap-2 mb-1">
                <span className="text-xs font-medium text-muted-foreground">{field.name}</span>
                <Badge variant="outline" className="text-xs">
                  {field.type === 'select' ? 'Lista Suspensa' : 
                   field.type === 'checkbox' ? 'Checkbox' : 
                   field.type === 'text' ? 'Texto' :
                   field.type === 'number' ? 'Número' :
                   field.type === 'date' ? 'Data e Hora' : field.type}
                </Badge>
              </div>
              {field.type === 'select' && field.options ? (
                <Select value={field.value} onValueChange={(value) => updateCustomField(field.id, value)}>
                  <SelectTrigger>
                    <SelectValue placeholder="Selecione uma opção" />
                  </SelectTrigger>
                  <SelectContent>
                    {field.options.map((option, idx) => (
                      <SelectItem key={idx} value={option}>
                        {option}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              ) : field.type === 'checkbox' ? (
                <Input
                  type="checkbox"
                  checked={field.value === 'true'}
                  onChange={(e) => updateCustomField(field.id, e.target.checked ? 'true' : 'false')}
                  className="w-5 h-5"
                />
              ) : (
                <Input
                  value={field.value}
                  onChange={(e) => updateCustomField(field.id, e.target.value)}
                  type={field.type === 'number' ? 'number' : field.type === 'date' ? 'datetime-local' : 'text'}
                />
              )}
            </div>
            <Button
              variant="ghost"
              size="icon"
              className="opacity-0 group-hover:opacity-100 transition-opacity h-8 w-8"
              onClick={() => deleteCustomField(field.id)}
            >
              <Trash2 className="w-4 h-4 text-destructive" />
            </Button>
          </div>
        ))}
      </div>
    </div>
  );
};

