                  rows={5}
                />
                <p className="text-xs text-muted-foreground mt-1">
                  Suporta HTML básico. Será exibido abaixo da mensagem principal.
                </p>
              </div>
            </Card>
          </TabsContent>
        </Tabs>
    </div>
  );
};

