import { useState, useMemo, useRef } from "react";
import { Button } from "@/features/produto/components/ui/button";
import { Input } from "@/features/produto/components/ui/input";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/features/produto/components/ui/table";
import { Checkbox } from "@/features/produto/components/ui/checkbox";
import { Printer, Plus, Filter, Package, Upload, Download, Edit } from "lucide-react";
import { Badge } from "@/features/produto/components/ui/badge";
import { toast } from "sonner";
import type { Product, PrinterSettings } from "@/pages/Index";
import { Calendar } from "@/features/produto/components/ui/calendar";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale/pt-BR";
import { cn } from "@/features/produto/lib/utils";
import { exportToExcel, importFromExcel } from "@/features/produto/lib/exportUtils";
import { LabelConfigDialog } from "@/features/produto/components/Printer/LabelConfigDialog";
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetTrigger } from "@/features/produto/components/ui/sheet";
import { Label } from "@/features/produto/components/ui/label";
import { formatDateBRT } from "@/features/produto/lib/datetime";

interface ProductListProps {
  products: Product[];
  printerSettings: PrinterSettings;
  onAddProduct: () => void;
  onImportProducts: (products: Product[]) => void;
  onEdit: (product: Product) => void;
}

export const ProductList = ({ products, printerSettings, onAddProduct, onImportProducts, onEdit }: ProductListProps) => {
  const [selectedProducts, setSelectedProducts] = useState<string[]>([]);
  const [selectAll, setSelectAll] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [printDialogOpen, setPrintDialogOpen] = useState(false);
  const [selectedProductToPrint, setSelectedProductToPrint] = useState<Product | null>(null);
  const [filterOpen, setFilterOpen] = useState(false);

  const [filters, setFilters] = useState({
    barcode: "",
    reference: "",
    description: "",
    number: "",
    color: "",
    category: "",
    subcategory: "",
    price: "",
    stock: "",
    startDate: undefined as Date | undefined,
    endDate: undefined as Date | undefined,
  });

  const handleSelectAll = (checked: boolean) => {
    setSelectAll(checked);
    if (checked) {
      setSelectedProducts(products.map(p => p.id));
    } else {
      setSelectedProducts([]);
    }
  };

  const handleSelectProduct = (id: string, checked: boolean) => {
    if (checked) {
      setSelectedProducts(prev => [...prev, id]);
    } else {
      setSelectedProducts(prev => prev.filter(pid => pid !== id));
      setSelectAll(false);
    }
  };

  const handleExportExcel = () => {
    const selectedData = selectedProducts.length > 0
      ? products.filter(p => selectedProducts.includes(p.id))
      : filteredProducts;

    if (selectedData.length === 0) {
      toast.error("Nenhum produto para exportar");
      return;
    }

    const dataToExport = selectedData.map(p => ({
      'Código de Barras': p.barcode,
      'Referência': p.reference,
      'Descrição': p.description,
      'Número': p.number,
      'Cor': p.color,
      'Categoria': p.category,
      'Subcategoria': p.subcategory,
      'Preço': p.price,
      'Estoque': p.stock,
      'Data Adição': formatDateBRT(p.createdAt)
    }));

    exportToExcel(dataToExport, 'produtos', 'Produtos');
    toast.success(`${selectedData.length} produtos exportados com sucesso`);
  };

  const handleImportExcel = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    try {
      const data = await importFromExcel<any>(file);

      if (data.length === 0) {
        toast.error("Arquivo vazio");
        return;
      }

      const importedProducts: Product[] = data.map((row: any, index: number) => ({
        id: String(Date.now() + index),
        barcode: row['Código de Barras'] || row.barcode || '',
        reference: row['Referência'] || row.reference || '',
        description: row['Descrição'] || row.description || '',
        number: row['Número'] || row.number || '',
        color: row['Cor'] || row.color || '',
        category: row['Categoria'] || row.category || '',
        subcategory: row['Subcategoria'] || row.subcategory || '',
        price: row['Preço'] || row.price || 'R$ 0,00',
        stock: Number(row['Estoque'] || row.stock || 0),
        image: row.image || "https://images.unsplash.com/photo-1515562141207-7a88fb7ce338?w=100&h=100&fit=crop",
        createdAt: row['Data Adição'] ? new Date(row['Data Adição']) : new Date()
      }));

      onImportProducts(importedProducts);
      toast.success(`${importedProducts.length} produtos importados com sucesso`);

      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }
    } catch (error) {
      console.error('Erro ao importar:', error);
      toast.error("Erro ao importar arquivo. Verifique o formato.");
    }
  };

  const filteredProducts = useMemo(() => {
    return products.filter((product) => {
      const matchBarcode = product.barcode.toLowerCase().includes(filters.barcode.toLowerCase());
      const matchReference = product.reference.toLowerCase().includes(filters.reference.toLowerCase());
      const matchDescription = product.description.toLowerCase().includes(filters.description.toLowerCase());
      const matchNumber = product.number.toLowerCase().includes(filters.number.toLowerCase());
      const matchColor = product.color.toLowerCase().includes(filters.color.toLowerCase());
      const matchCategory = product.category.toLowerCase().includes(filters.category.toLowerCase());
      const matchSubcategory = product.subcategory.toLowerCase().includes(filters.subcategory.toLowerCase());
      const matchPrice = product.price.toLowerCase().includes(filters.price.toLowerCase());
      const matchStock = product.stock.toString().includes(filters.stock);

      // Filtro de data
      let matchDate = true;
      if (filters.startDate || filters.endDate) {
        const productDate = new Date(product.createdAt);
        productDate.setHours(0, 0, 0, 0);

        if (filters.startDate && filters.endDate) {
          const start = new Date(filters.startDate);
          start.setHours(0, 0, 0, 0);
          const end = new Date(filters.endDate);
          end.setHours(23, 59, 59, 999);
          matchDate = productDate >= start && productDate <= end;
        } else if (filters.startDate) {
          const start = new Date(filters.startDate);
          start.setHours(0, 0, 0, 0);
          matchDate = productDate >= start;
        } else if (filters.endDate) {
          const end = new Date(filters.endDate);
          end.setHours(23, 59, 59, 999);
          matchDate = productDate <= end;
        }
      }

      return matchBarcode && matchReference && matchDescription && matchNumber && 
             matchColor && matchCategory && matchSubcategory && matchPrice && 
             matchStock && matchDate;
    });
  }, [products, filters]);

  return (
    <div className="flex-1 flex flex-col bg-background">
      <div className="p-6">
        <div className="flex items-center justify-between mb-6">
          <h2 className="text-xl font-semibold text-foreground">Lista de Produtos</h2>

          <div className="flex items-center gap-2">
            <input
              ref={fileInputRef}
              type="file"
              accept=".xlsx,.xls,.csv"
              onChange={handleImportExcel}
              className="hidden"
            />
            <Button
              variant="outline"
              className="gap-2"
              onClick={() => fileInputRef.current?.click()}
            >
              <Upload className="w-4 h-4" />
              Importar
            </Button>
            <Button
              variant="outline"
              className="gap-2"
              onClick={handleExportExcel}
            >
              <Download className="w-4 h-4" />
              Exportar
            </Button>
            <Button
              className="gap-2"
              onClick={onAddProduct}
            >
              <Plus className="w-4 h-4" />
              Adicionar
            </Button>
            <Sheet open={filterOpen} onOpenChange={setFilterOpen}>
              <SheetTrigger asChild>
                <Button variant="outline" className="gap-2">
                  <Filter className="w-4 h-4" />
                  Filtro
                </Button>
              </SheetTrigger>
              <SheetContent>
                <SheetHeader>
                  <SheetTitle>Filtros</SheetTitle>
                </SheetHeader>
                <div className="space-y-4 pt-4">
                  <div>
                    <Label>Código de Barras</Label>
                    <Input
                      placeholder="Buscar por código..."
                      value={filters.barcode}
                      onChange={(e) => setFilters({...filters, barcode: e.target.value})}
                    />
                  </div>
                  <div>
                    <Label>Referência</Label>
                    <Input
                      placeholder="Buscar por referência..."
                      value={filters.reference}
                      onChange={(e) => setFilters({...filters, reference: e.target.value})}
                    />
                  </div>
                  <div>
                    <Label>Descrição</Label>
                    <Input
                      placeholder="Buscar por descrição..."
                      value={filters.description}
                      onChange={(e) => setFilters({...filters, description: e.target.value})}
                    />
                  </div>
                  <div>
                    <Label>Número</Label>
                    <Input
                      placeholder="Buscar por número..."
                      value={filters.number}
                      onChange={(e) => setFilters({...filters, number: e.target.value})}
                    />
                  </div>
                  <div>
                    <Label>Cor</Label>
                    <Input
                      placeholder="Buscar por cor..."
                      value={filters.color}
                      onChange={(e) => setFilters({...filters, color: e.target.value})}
                    />
                  </div>
                  <div>
                    <Label>Categoria</Label>
                    <Input
                      placeholder="Buscar por categoria..."
                      value={filters.category}
                      onChange={(e) => setFilters({...filters, category: e.target.value})}
                    />
                  </div>
                  <div>
                    <Label>Subcategoria</Label>
                    <Input
                      placeholder="Buscar por subcategoria..."
                      value={filters.subcategory}
                      onChange={(e) => setFilters({...filters, subcategory: e.target.value})}
                    />
                  </div>
                  <div>
                    <Label>Preço</Label>
                    <Input
                      placeholder="Buscar por preço..."
                      value={filters.price}
                      onChange={(e) => setFilters({...filters, price: e.target.value})}
                    />
                  </div>
                  <div>
                    <Label>Estoque</Label>
                    <Input
                      placeholder="Buscar por estoque..."
                      value={filters.stock}
                      onChange={(e) => setFilters({...filters, stock: e.target.value})}
                    />
                  </div>
                  <div>
                    <Label>Data Inicial</Label>
                    <Calendar
                      mode="single"
                      selected={filters.startDate}
                      onSelect={(date) => setFilters({...filters, startDate: date})}
                      locale={ptBR}
                      className="rounded-md border"
                    />
                  </div>
                  <div>
                    <Label>Data Final</Label>
                    <Calendar
                      mode="single"
                      selected={filters.endDate}
                      onSelect={(date) => setFilters({...filters, endDate: date})}
                      locale={ptBR}
                      className="rounded-md border"
                    />
                  </div>
                  <div className="flex gap-2 pt-4">
                    <Button
                      variant="outline"
                      className="flex-1"
                      onClick={() => setFilters({
                        barcode: "",
                        reference: "",
                        description: "",
                        number: "",
                        color: "",
                        category: "",
                        subcategory: "",
                        price: "",
                        stock: "",
                        startDate: undefined,
                        endDate: undefined,
                      })}
                    >
                      Limpar
                    </Button>
                    <Button
                      className="flex-1"
                      onClick={() => setFilterOpen(false)}
                    >
                      Aplicar
                    </Button>
                  </div>
                </div>
              </SheetContent>
            </Sheet>
          </div>
        </div>

        <div className="flex items-center gap-2 mb-4">
          <p className="text-sm text-muted-foreground">
            {selectedProducts.length} itens selecionados | {filteredProducts.length} produtos encontrados
          </p>
        </div>

        {/* Products Table */}
        <div className="border rounded-lg overflow-hidden bg-card">
          <Table>
            <TableHeader>
              <TableRow className="bg-muted/50">
                <TableHead className="w-12">
                  <Checkbox 
                    checked={selectAll}
                    onCheckedChange={handleSelectAll}
                  />
                </TableHead>
                <TableHead>Foto</TableHead>
                <TableHead>Cód. de Barras</TableHead>
                <TableHead>Referência</TableHead>
                <TableHead>Descrição</TableHead>
                <TableHead>Nº</TableHead>
                <TableHead>Cor</TableHead>
                <TableHead>Categoria</TableHead>
                <TableHead>Subcategoria</TableHead>
                <TableHead>Preço</TableHead>
                <TableHead>Estoque</TableHead>
                <TableHead>Data Adição</TableHead>
                <TableHead>Ações</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {filteredProducts.map((product) => (
                <TableRow key={product.id} className="hover:bg-muted/50">
                  <TableCell>
                    <Checkbox 
                      checked={selectedProducts.includes(product.id)}
                      onCheckedChange={(checked) => handleSelectProduct(product.id, checked as boolean)}
                    />
                  </TableCell>
                  <TableCell>
                    <img
                      src={product.image}
                      alt={product.description}
                      className="w-12 h-12 object-cover rounded"
                    />
                  </TableCell>
                  <TableCell>
                    <button className="text-blue-600 hover:underline font-mono text-sm">
                      {product.barcode}
                    </button>
                  </TableCell>
                  <TableCell>{product.reference || "-"}</TableCell>
                  <TableCell className="max-w-xs">{product.description}</TableCell>
                  <TableCell>{product.number || "-"}</TableCell>
                  <TableCell>{product.color || "-"}</TableCell>
                  <TableCell>{product.category}</TableCell>
                  <TableCell></TableCell>
                  <TableCell className="font-medium">{product.price}</TableCell>
                  <TableCell>
                    <Badge variant="outline" className="gap-1">
                      <Package className="w-3 h-3" />
                      {product.stock}
                    </Badge>
                  </TableCell>
                  <TableCell className="text-sm text-muted-foreground">
                    {formatDateBRT(product.createdAt)}
                  </TableCell>
                  <TableCell>
                    <div className="flex items-center gap-1">
                      <Button 
                        variant="ghost" 
                        size="icon" 
                        className="h-8 w-8"
                        onClick={() => onEdit(product)}
                        title="Editar Produto"
                      >
                        <Edit className="w-4 h-4" />
                      </Button>
                      <Button 
                        variant="ghost" 
                        size="icon" 
                        className="h-8 w-8 text-primary hover:text-primary hover:bg-primary/10"
                        onClick={() => {
                          setSelectedProductToPrint(product);
                          setPrintDialogOpen(true);
                        }}
                        title="Configurar Etiqueta"
                      >
                        <Printer className="w-4 h-4" />
                      </Button>
                    </div>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </div>
      </div>

      {selectedProductToPrint && (
        <LabelConfigDialog
          product={selectedProductToPrint}
          printerSettings={printerSettings}
          open={printDialogOpen}
          onOpenChange={(open) => {
            setPrintDialogOpen(open);
            if (!open) setSelectedProductToPrint(null);
          }}
        />
      )}
    </div>
  );
};

src/components/BillsTable.tsx.content:
import { Card } from "@/components/ui/card";
import { FileText, Calendar, DollarSign, CreditCard, AlertCircle } from "lucide-react";
import { Bill } from "@/lib/financialUtils";
import { Badge } from "@/components/ui/badge";

interface BillsTableProps {
  bills: Bill[];
}

export default function BillsTable({ bills }: BillsTableProps) {
  const formatCurrency = (amount: number, currencyCode: string = "BRL") => {
    return new Intl.NumberFormat("pt-BR", {
      style: "currency",
      currency: currencyCode,
    }).format(amount);
  };

  const formatDate = (dateString: string) => {
    try {
      return new Date(dateString).toLocaleDateString("pt-BR");
    } catch {
      return dateString;
    }
  };

  if (bills.length === 0) {
    return null;
  }

  // Ordenar por data de vencimento (mais recente primeiro)
  const sortedBills = [...bills].sort((a, b) => 
    new Date(b.dueDate).getTime() - new Date(a.dueDate).getTime()
  );

  return (
    <Card className="p-6">
      <div className="space-y-4">
        <div className="flex items-center gap-2">
          <FileText className="h-5 w-5 text-primary" />
          <h3 className="text-lg font-semibold">Faturas (Dados Brutos)</h3>
        </div>

        <div className="border rounded-lg overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-muted">
                <tr>
                  <th className="px-4 py-3 text-left text-sm font-medium">ID</th>
                  <th className="px-4 py-3 text-left text-sm font-medium">
                    <div className="flex items-center gap-2">
                      <Calendar className="h-4 w-4" />
                      Data Vencimento
                    </div>
                  </th>
                  <th className="px-4 py-3 text-right text-sm font-medium">
                    <div className="flex items-center justify-end gap-2">
                      <DollarSign className="h-4 w-4" />
                      Valor Total
                    </div>
                  </th>
                  <th className="px-4 py-3 text-right text-sm font-medium">Valor Mínimo</th>
                  <th className="px-4 py-3 text-center text-sm font-medium">
                    <div className="flex items-center justify-center gap-2">
                      <CreditCard className="h-4 w-4" />
                      Parcelamento
                    </div>
                  </th>
                  <th className="px-4 py-3 text-left text-sm font-medium">
                    <div className="flex items-center gap-2">
                      <AlertCircle className="h-4 w-4" />
                      Finance Charges
                    </div>
                  </th>
                </tr>
              </thead>
              <tbody className="divide-y">
                {sortedBills.map((bill) => (
                  <tr key={bill.id} className="hover:bg-muted/50 transition-colors">
                    <td className="px-4 py-3 text-xs font-mono text-muted-foreground">
                      {bill.id.substring(0, 8)}...
                    </td>
                    <td className="px-4 py-3 text-sm">{formatDate(bill.dueDate)}</td>
                    <td className="px-4 py-3 text-sm text-right font-medium text-primary">
                      {formatCurrency(bill.totalAmount, bill.totalAmountCurrencyCode)}
                    </td>
                    <td className="px-4 py-3 text-sm text-right text-muted-foreground">
                      {bill.minimumPaymentAmount 
                        ? formatCurrency(bill.minimumPaymentAmount, bill.totalAmountCurrencyCode)
                        : "-"
                      }
                    </td>
                    <td className="px-4 py-3 text-center">
                      {bill.allowsInstallments !== undefined ? (
                        <Badge variant={bill.allowsInstallments ? "default" : "secondary"}>
                          {bill.allowsInstallments ? "Sim" : "Não"}
                        </Badge>
                      ) : (
                        <span className="text-sm text-muted-foreground">-</span>
                      )}
                    </td>
                    <td className="px-4 py-3 text-sm">
                      {bill.financeCharges && bill.financeCharges.length > 0 ? (
                        <div className="space-y-1">
                          {bill.financeCharges.map((charge, idx) => (
                            <div key={charge.id || idx} className="text-xs">
                              <span className="font-medium">{charge.type}:</span>{" "}
                              {formatCurrency(charge.amount, charge.currencyCode)}
                              {charge.additionalInfo && (
                                <span className="text-muted-foreground ml-1">
                                  ({charge.additionalInfo})
                                </span>
                              )}
                            </div>
                          ))}
                        </div>
                      ) : (
                        <span className="text-muted-foreground">-</span>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </Card>
  );
}

src/components/notion/BlockActionsMenu.t.content:
import { useState, useEffect, useMemo } from 'react';
import { 
  Type, Heading1, Heading2, Heading3, List, ListOrdered, 
  CheckSquare, Quote, Code, Minus, Lightbulb, ChevronRight,
  Palette
} from 'lucide-react';
import { cn } from '@/lib/utils';

interface BlockActionsMenuProps {
  position: { x: number; y: number };
  onChangeType: (type: string) => void;
  onChangeTextColor: (color: string) => void;
  onChangeBackgroundColor: (color: string) => void;
  onClose: () => void;
  currentType?: string;
  currentTextColor?: string;
  currentBackgroundColor?: string;
}

interface BlockTypeOption {
  type: string;
  label: string;
  icon: React.ReactNode;
}

interface ColorOption {
  value: string;
  label: string;
  textClass: string;
  bgClass: string;
}

export const BlockActionsMenu = ({ 
  position, 
  onChangeType, 
  onChangeTextColor,
  onChangeBackgroundColor,
  onClose,
  currentType,
  currentTextColor,
  currentBackgroundColor
}: BlockActionsMenuProps) => {
  const [activeTab, setActiveTab] = useState<'type' | 'text-color' | 'bg-color'>('type');

  const blockTypes: BlockTypeOption[] = useMemo(() => [
    { type: 'text', label: 'Texto', icon: <Type className="h-4 w-4" /> },
    { type: 'h1', label: 'Título 1', icon: <Heading1 className="h-4 w-4" /> },
    { type: 'h2', label: 'Título 2', icon: <Heading2 className="h-4 w-4" /> },
    { type: 'h3', label: 'Título 3', icon: <Heading3 className="h-4 w-4" /> },
    { type: 'bullet', label: 'Lista com marcadores', icon: <List className="h-4 w-4" /> },
    { type: 'numbered', label: 'Lista numerada', icon: <ListOrdered className="h-4 w-4" /> },
    { type: 'todo', label: 'Lista de tarefas', icon: <CheckSquare className="h-4 w-4" /> },
    { type: 'toggle', label: 'Lista de alternantes', icon: <ChevronRight className="h-4 w-4" /> },
    { type: 'quote', label: 'Citação', icon: <Quote className="h-4 w-4" /> },
    { type: 'divider', label: 'Divisor', icon: <Minus className="h-4 w-4" /> },
    { type: 'callout', label: 'Frase de destaque', icon: <Lightbulb className="h-4 w-4" /> },
    { type: 'code', label: 'Código', icon: <Code className="h-4 w-4" /> },
  ], []);

  const textColors: ColorOption[] = useMemo(() => [
    { value: 'default', label: 'Padrão', textClass: 'text-foreground', bgClass: '' },
    { value: 'gray', label: 'Cinza', textClass: 'text-gray-500', bgClass: '' },
    { value: 'brown', label: 'Marrom', textClass: 'text-amber-700', bgClass: '' },
    { value: 'orange', label: 'Laranja', textClass: 'text-orange-500', bgClass: '' },
    { value: 'yellow', label: 'Amarelo', textClass: 'text-yellow-500', bgClass: '' },
    { value: 'green', label: 'Verde', textClass: 'text-green-500', bgClass: '' },
    { value: 'blue', label: 'Azul', textClass: 'text-blue-500', bgClass: '' },
    { value: 'purple', label: 'Roxo', textClass: 'text-purple-500', bgClass: '' },
    { value: 'pink', label: 'Rosa', textClass: 'text-pink-500', bgClass: '' },
    { value: 'red', label: 'Vermelho', textClass: 'text-red-500', bgClass: '' },
  ], []);

  const backgroundColors: ColorOption[] = useMemo(() => [
    { value: 'default', label: 'Padrão', textClass: '', bgClass: 'bg-transparent' },
    { value: 'gray', label: 'Cinza', textClass: '', bgClass: 'bg-gray-100 dark:bg-gray-800' },
    { value: 'brown', label: 'Marrom', textClass: '', bgClass: 'bg-amber-100 dark:bg-amber-900' },
    { value: 'orange', label: 'Laranja', textClass: '', bgClass: 'bg-orange-100 dark:bg-orange-900' },
    { value: 'yellow', label: 'Amarelo', textClass: '', bgClass: 'bg-yellow-100 dark:bg-yellow-900' },
    { value: 'green', label: 'Verde', textClass: '', bgClass: 'bg-green-100 dark:bg-green-900' },
    { value: 'blue', label: 'Azul', textClass: '', bgClass: 'bg-blue-100 dark:bg-blue-900' },
    { value: 'purple', label: 'Roxo', textClass: '', bgClass: 'bg-purple-100 dark:bg-purple-900' },
    { value: 'pink', label: 'Rosa', textClass: '', bgClass: 'bg-pink-100 dark:bg-pink-900' },
    { value: 'red', label: 'Vermelho', textClass: '', bgClass: 'bg-red-100 dark:bg-red-900' },
  ], []);

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (!(e.target as HTMLElement).closest('.block-actions-menu')) {
        onClose();
      }
    };

    const handleEscape = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        onClose();
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    document.addEventListener('keydown', handleEscape);

    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
      document.removeEventListener('keydown', handleEscape);
    };
  }, [onClose]);

  return (
    <div
      className="block-actions-menu fixed bg-popover border border-border rounded-lg shadow-lg overflow-hidden z-50"
      style={{
        left: `${position.x}px`,
        top: `${position.y}px`,
        width: '280px'
      }}
    >
      {/* Tabs */}
      <div className="flex border-b border-border bg-muted/30">
        <button
          onClick={() => setActiveTab('type')}
          className={cn(
            'flex-1 px-3 py-2 text-xs font-medium transition-colors',
            activeTab === 'type' 
              ? 'bg-background text-foreground border-b-2 border-primary' 
              : 'text-muted-foreground hover:text-foreground'
          )}
        >
          Tipo
        </button>
        <button
          onClick={() => setActiveTab('text-color')}
          className={cn(
            'flex-1 px-3 py-2 text-xs font-medium transition-colors flex items-center justify-center gap-1',
            activeTab === 'text-color' 
              ? 'bg-background text-foreground border-b-2 border-primary' 
              : 'text-muted-foreground hover:text-foreground'
          )}
        >
          <Palette className="h-3 w-3" />
          Texto
        </button>
        <button
          onClick={() => setActiveTab('bg-color')}
          className={cn(
            'flex-1 px-3 py-2 text-xs font-medium transition-colors flex items-center justify-center gap-1',
            activeTab === 'bg-color' 
              ? 'bg-background text-foreground border-b-2 border-primary' 
              : 'text-muted-foreground hover:text-foreground'
          )}
        >
          <Palette className="h-3 w-3" />
          Fundo
        </button>
      </div>

      {/* Content */}
      <div className="max-h-[400px] overflow-y-auto">
        {activeTab === 'type' && (
          <div className="py-2">
            {blockTypes.map((option) => (
              <button
                key={option.type}
                onClick={() => {
                  onChangeType(option.type);
                  onClose();
                }}
                className={cn(
                  'w-full text-left px-3 py-2 hover:bg-accent hover:text-accent-foreground transition-colors flex items-center gap-3',
                  currentType === option.type && 'bg-accent text-accent-foreground'
                )}
              >
                <span className="text-muted-foreground">
                  {option.icon}
                </span>
                <span className="text-sm">{option.label}</span>
                {currentType === option.type && (
                  <span className="ml-auto text-primary text-xs">✓</span>
                )}
              </button>
            ))}
          </div>
        )}

        {activeTab === 'text-color' && (
          <div className="py-2">
            {textColors.map((color) => (
              <button
                key={color.value}
                onClick={() => {
                  onChangeTextColor(color.value);
                  onClose();
                }}
                className={cn(
                  'w-full text-left px-3 py-2.5 hover:bg-accent hover:text-accent-foreground transition-colors flex items-center gap-3',
                  currentTextColor === color.value && 'bg-accent text-accent-foreground'
                )}
              >
                <div className={cn('w-4 h-4 rounded-full border border-border', color.textClass, 'bg-current')} />
                <span className={cn('text-sm', color.textClass)}>{color.label}</span>
                {currentTextColor === color.value && (
                  <span className="ml-auto text-primary text-xs">✓</span>
                )}
              </button>
            ))}
          </div>
        )}

        {activeTab === 'bg-color' && (
          <div className="py-2">
            {backgroundColors.map((color) => (
              <button
                key={color.value}
                onClick={() => {
                  onChangeBackgroundColor(color.value);
                  onClose();
                }}
                className={cn(
                  'w-full text-left px-3 py-2.5 hover:bg-accent hover:text-accent-foreground transition-colors flex items-center gap-3',
                  currentBackgroundColor === color.value && 'bg-accent text-accent-foreground'
                )}
              >
                <div className={cn('w-4 h-4 rounded border border-border', color.bgClass)} />
                <span className="text-sm">{color.label}</span>
                {currentBackgroundColor === color.value && (
                  <span className="ml-auto text-primary text-xs">✓</span>
                )}
              </button>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

src/components/billing/SupabaseFilesTabl.content:
import { Card } from "@/components/ui/card";
import { FileText, Download, Calendar, DollarSign, Building2, Image, FileEdit } from "lucide-react";
import { format, parseISO } from "date-fns";
import { ptBR } from "date-fns/locale/pt-BR";
import { SupabaseFile } from "@/hooks/useSupabaseFiles";
import { Button } from "@/components/ui/button";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";

interface SupabaseFilesTableProps {
  files: SupabaseFile[];
}

export default function SupabaseFilesTable({ files }: SupabaseFilesTableProps) {
  const formatDate = (dateString: string | undefined) => {
    if (!dateString) return "-";
    try {
      return format(parseISO(dateString), "dd/MM/yyyy", { locale: ptBR });
    } catch {
      return dateString;
    }
  };

  const formatCurrency = (value: string | undefined) => {
    if (!value) return "-";
    const numValue = parseFloat(value);
    if (isNaN(numValue)) return "-";
    return new Intl.NumberFormat("pt-BR", {
      style: "currency",
      currency: "BRL",
    }).format(numValue);
  };

  const getCategoryColor = (category: string | undefined) => {
    const colors: Record<string, string> = {
      'food': 'bg-orange-500/10 text-orange-500',
      'transport': 'bg-blue-500/10 text-blue-500',
      'health': 'bg-red-500/10 text-red-500',
      'entertainment': 'bg-purple-500/10 text-purple-500',
      'shopping': 'bg-pink-500/10 text-pink-500',
      'bills': 'bg-yellow-500/10 text-yellow-500',
      'morada': 'bg-indigo-500/10 text-indigo-500',
      'saúde': 'bg-red-500/10 text-red-500',
      'other': 'bg-gray-500/10 text-gray-500',
    };
    return colors[category?.toLowerCase() || 'other'] || colors.other;
  };

  const getFileTypeDisplay = (file: SupabaseFile) => {
    // Se foi criado manualmente pela plataforma
    if (file.type === 'manual') {
      return {
        icon: <FileEdit className="h-4 w-4 text-green-500" />,
        label: 'Manual',
        color: 'text-green-600 dark:text-green-400'
      };
    }

    // Arquivos locais ou do Supabase são Imagem
    return {
      icon: <Image className="h-4 w-4 text-blue-500" />,
      label: 'Imagem',
      color: 'text-blue-600 dark:text-blue-400'
    };
  };

  if (files.length === 0) {
    return (
      <Card className="p-8">
        <div className="text-center text-muted-foreground">
          <FileText className="h-12 w-12 mx-auto mb-4 opacity-50" />
          <p>Nenhum anexo encontrado no Supabase</p>
          <p className="text-sm mt-2">
            Configure o Supabase em Configurações para visualizar anexos
          </p>
        </div>
      </Card>
    );
  }

  return (
    <Card className="p-6">
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-lg font-semibold flex items-center gap-2">
          <FileText className="h-5 w-5" />
          Documentos Financeiros ({files.length})
        </h3>
      </div>

      <div className="rounded-md border">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Tipo do Arquivo</TableHead>
              <TableHead>Categoria</TableHead>
              <TableHead>Valor</TableHead>
              <TableHead>Data</TableHead>
              <TableHead>Vencimento</TableHead>
              <TableHead>Descrição</TableHead>
              <TableHead className="text-right">Ações</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {files.map((file) => {
              const fileType = getFileTypeDisplay(file);

              return (
                <TableRow key={file.id}>
                  <TableCell className="font-medium">
                    <div className="flex items-center gap-2">
                      {fileType.icon}
                      <span className={`${fileType.color} font-medium`}>
                        {fileType.label}
                      </span>
                    </div>
                  </TableCell>
                  <TableCell>
                    {file.category && (
                      <span className={`px-2 py-1 rounded-full text-xs font-medium ${getCategoryColor(file.category)}`}>
                        {file.category}
                      </span>
                    )}
                  </TableCell>
                  <TableCell>
                    {file.amount && (
                      <span className="flex items-center gap-1 font-medium">
                        <DollarSign className="h-3 w-3" />
                        {formatCurrency(file.amount)}
                      </span>
                    )}
                  </TableCell>
                  <TableCell>
                    <span className="flex items-center gap-1 text-sm text-muted-foreground">
                      <Calendar className="h-3 w-3" />
                      {formatDate(file.created_at)}
                    </span>
                  </TableCell>
                  <TableCell>
                    {file.due_date && (
                      <span className="flex items-center gap-1 text-sm font-medium text-orange-600 dark:text-orange-400">
                        <Calendar className="h-3 w-3" />
                        {formatDate(file.due_date)}
                      </span>
                    )}
                  </TableCell>
                  <TableCell className="max-w-[300px]">
                    {file.establishment ? (
                      <div className="flex items-center gap-1">
                        <Building2 className="h-3 w-3 text-muted-foreground flex-shrink-0" />
                        <span className="truncate block text-sm">
                          {file.establishment}
                        </span>
                      </div>
                    ) : (
                      <span className="truncate block text-sm text-muted-foreground">
                        {file.description || "-"}
                      </span>
                    )}
                  </TableCell>
                  <TableCell className="text-right">
                    <Button
                      variant="ghost"
                      size="sm"
                      asChild
                    >
                      <a
                        href={file.file_url}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="flex items-center gap-1"
                      >
                        <Download className="h-4 w-4" />
                        Abrir
                      </a>
                    </Button>
                  </TableCell>
                </TableRow>
              );
            })}
          </TableBody>
        </Table>
      </div>
    </Card>
  );
}

