import { useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import { 
  Users, 
  MessageSquare, 
  FileText, 
  MoreHorizontal,
  FileEdit,
  Layout,
  Briefcase,
  Calendar,
  LayoutDashboard,
  Package,
  Search,
  History,
  BarChart3,
  Settings,
  Download,
  Bell,
  Store,
  ChevronRight
} from "lucide-react";
import { cn } from "@/lib/utils";
import {
  Drawer,
  DrawerClose,
  DrawerContent,
  DrawerHeader,
  DrawerTitle,
  DrawerDescription,
} from "@/components/ui/drawer";
import { ScrollArea } from "@/components/ui/scroll-area";

interface NavItem {
  path: string;
  icon: React.ElementType;
  label: string;
}

interface DrawerMenuItem {
  path: string;
  icon: React.ElementType;
  label: string;
}

interface DrawerSection {
  title: string;
  items: DrawerMenuItem[];
}

const mainNavItems: NavItem[] = [
  { path: "/clientes", icon: Users, label: "Clientes" },
  { path: "/whatsapp-platform", icon: MessageSquare, label: "WhatsApp" },
  { path: "/faturamento", icon: FileText, label: "Finanças" },
];

const drawerSections: DrawerSection[] = [
  {
    title: "Formulários & Documentos",
    items: [
      { path: "/formulario", icon: FileEdit, label: "Formulário" },
      { path: "/documentos", icon: FileText, label: "Documentos" },
      { path: "/notion", icon: Layout, label: "Notion" },
    ],
  },
  {
    title: "Ferramentas",
    items: [
      { path: "/workspace", icon: Briefcase, label: "Workspace" },
      { path: "/calendario", icon: Calendar, label: "Calendário" },
      { path: "/kanban", icon: LayoutDashboard, label: "Kanban" },
      { path: "/produto", icon: Package, label: "Produtos" },
    ],
  },
  {
    title: "Compliance & CPF",
    items: [
      { path: "/consultar-cpf", icon: Search, label: "Consultar CPF" },
      { path: "/historico-consultas", icon: History, label: "Histórico Consultas" },
    ],
  },
  {
    title: "Administração",
    items: [
      { path: "/produto/admin/dashboard", icon: BarChart3, label: "Admin Dashboard" },
      { path: "/configuracoes", icon: Settings, label: "Configurações" },
      { path: "/export", icon: Download, label: "Exportar Dados" },
      { path: "/notifications", icon: Bell, label: "Notificações" },
    ],
  },
  {
    title: "Plataforma Revendedora",
    items: [
      { path: "/revendedora", icon: Store, label: "Revendedora" },
    ],
  },
];

const triggerHaptic = () => {
  if ('vibrate' in navigator) {
    navigator.vibrate(10);
  }
};

export function BottomNav() {
  const location = useLocation();
  const navigate = useNavigate();
  const [isDrawerOpen, setIsDrawerOpen] = useState(false);

  const isActive = (path: string) => {
    return location.pathname === path || location.pathname.startsWith(path + "/");
  };

  const isAnyDrawerItemActive = () => {
    return drawerSections.some(section => 
      section.items.some(item => isActive(item.path))
    );
  };

  const handleNavClick = (path: string) => {
    triggerHaptic();
    navigate(path);
  };

  const handleDrawerItemClick = (path: string) => {
    triggerHaptic();
    setIsDrawerOpen(false);
    navigate(path);
  };

  const handleMoreClick = () => {
    triggerHaptic();
    setIsDrawerOpen(true);
  };

  return (
    <>
      <nav className="md:hidden fixed bottom-0 left-0 right-0 z-50 pb-safe"
        style={{
          background: 'rgba(10, 10, 10, 0.85)',
          backdropFilter: 'blur(20px) saturate(180%)',
          WebkitBackdropFilter: 'blur(20px) saturate(180%)',
          borderTop: '1px solid rgba(212, 175, 55, 0.2)',
        }}
      >
        <div className="flex items-center justify-around h-16 px-1">
          {mainNavItems.map((item) => {
            const Icon = item.icon;
            const active = isActive(item.path);

            return (
              <button
                key={item.path}
                onClick={() => handleNavClick(item.path)}
                className={cn(
                  "flex flex-col items-center justify-center min-w-[48px] min-h-[56px] rounded-xl transition-all duration-200 flex-1",
                  "active:scale-95 touch-manipulation",
                  active
                    ? "text-primary"
                    : "text-muted-foreground hover:text-primary/70"
                )}
                aria-label={item.label}
                title={item.label}
              >
                <div
                  className={cn(
                    "p-2 rounded-lg transition-all duration-200",
                    active && "bg-primary/10"
                  )}
                >
                  <Icon
                    className={cn(
                      "transition-all duration-200",
                      active ? "h-6 w-6" : "h-5 w-5"
                    )}
                  />
                </div>
              </button>
            );
          })}

          <button
            onClick={handleMoreClick}
            className={cn(
              "flex flex-col items-center justify-center min-w-[48px] min-h-[56px] rounded-xl transition-all duration-200 flex-1",
              "active:scale-95 touch-manipulation",
              isAnyDrawerItemActive() || isDrawerOpen
                ? "text-primary"
                : "text-muted-foreground hover:text-primary/70"
            )}
            aria-label="Mais"
            title="Mais opções"
          >
            <div
              className={cn(
                "p-2 rounded-lg transition-all duration-200",
                (isAnyDrawerItemActive() || isDrawerOpen) && "bg-primary/10"
              )}
            >
              <MoreHorizontal
                className={cn(
                  "transition-all duration-200",
                  isAnyDrawerItemActive() || isDrawerOpen ? "h-6 w-6" : "h-5 w-5"
                )}
              />
            </div>
          </button>
        </div>
      </nav>

      <Drawer open={isDrawerOpen} onOpenChange={setIsDrawerOpen}>
        <DrawerContent 
          className="bg-[#0a0a0a] border-primary/20 max-h-[85vh]"
          style={{
            background: 'rgba(10, 10, 10, 0.98)',
            backdropFilter: 'blur(20px)',
            WebkitBackdropFilter: 'blur(20px)',
          }}
        >
          <DrawerHeader className="border-b border-primary/10 pb-4">
            <DrawerTitle className="text-lg font-semibold text-foreground">
              Mais Opções
            </DrawerTitle>
            <DrawerDescription className="text-sm text-muted-foreground">
              Acesse todas as funcionalidades da plataforma
            </DrawerDescription>
          </DrawerHeader>

          <ScrollArea className="flex-1 px-4 py-2" style={{ maxHeight: 'calc(85vh - 120px)' }}>
            <div className="space-y-6 pb-8">
              {drawerSections.map((section) => (
                <div key={section.title}>
                  <h3 className="text-xs font-semibold text-primary/80 uppercase tracking-wider mb-3 px-1">
                    {section.title}
                  </h3>
                  <div className="space-y-1">
                    {section.items.map((item) => {
                      const Icon = item.icon;
                      const active = isActive(item.path);

                      return (
                        <DrawerClose asChild key={item.path}>
                          <button
                            onClick={() => handleDrawerItemClick(item.path)}
                            className={cn(
                              "w-full flex items-center gap-4 min-h-[48px] px-3 py-3 rounded-xl transition-all duration-200",
                              "active:scale-[0.98] touch-manipulation",
                              active
                                ? "bg-primary/10 text-primary border border-primary/20"
                                : "text-foreground hover:bg-white/5 border border-transparent"
                            )}
                          >
                            <div
                              className={cn(
                                "w-10 h-10 rounded-lg flex items-center justify-center flex-shrink-0 transition-all",
                                active 
                                  ? "bg-primary/20" 
                                  : "bg-white/5"
                              )}
                            >
                              <Icon 
                                className={cn(
                                  "w-5 h-5 transition-colors",
                                  active ? "text-primary" : "text-muted-foreground"
                                )} 
                              />
                            </div>
                            <span className={cn(
                              "flex-1 text-left font-medium",
                              active ? "text-primary" : "text-foreground"
                            )}>
                              {item.label}
                            </span>
                            <ChevronRight 
                              className={cn(
                                "w-5 h-5 flex-shrink-0",
                                active ? "text-primary/60" : "text-muted-foreground/40"
                              )} 
                            />
                          </button>
                        </DrawerClose>
                      );
                    })}
                  </div>
                </div>
              ))}
            </div>
          </ScrollArea>
        </DrawerContent>
      </Drawer>
    </>
  );
}

server/lib/requestBatcher.ts.content:
/**
 * Request Batcher - Agrupa múltiplas requisições em uma só
 * 
 * Útil para otimizar chamadas ao banco de dados e APIs externas,
 * reduzindo o número de requests HTTP/queries.
 */

interface QueuedRequest<T, R> {
  request: T;
  resolve: (value: R) => void;
  reject: (error: Error) => void;
}

export class RequestBatcher<T, R> {
  private queue: QueuedRequest<T, R>[] = [];
  private timeout: NodeJS.Timeout | null = null;
  private batchFn: (requests: T[]) => Promise<R[]>;
  private delay: number;

  constructor(
    batchFn: (requests: T[]) => Promise<R[]>,
    delay: number = 50
  ) {
    this.batchFn = batchFn;
    this.delay = delay;
  }

  /**
   * Adiciona uma request à fila de processamento
   * @param request - Request a ser processado
   * @returns Promise que resolve quando o request for processado
   */
  add(request: T): Promise<R> {
    return new Promise<R>((resolve, reject) => {
      // Adiciona request à queue
      this.queue.push({ request, resolve, reject });

      // Clear timeout anterior se existir
      if (this.timeout) {
        clearTimeout(this.timeout);
      }

      // Setar novo timeout para chamar flush() após delay
      this.timeout = setTimeout(() => {
        this.flush();
      }, this.delay);
    });
  }

  /**
   * Processa todos os requests pendentes em batch
   */
  private async flush(): Promise<void> {
    // Se queue vazia, return
    if (this.queue.length === 0) {
      return;
    }

    // Splice queue (pegar todos e limpar)
    const batch = this.queue.splice(0, this.queue.length);
    const requests = batch.map(item => item.request);

    // Log detalhado
    console.log(`[BATCH] Processing ${batch.length} requests in 1 call`);

    try {
      // Chamar batchFn com array de requests
      const results = await this.batchFn(requests);

      // Resolver cada promise na ordem correta
      batch.forEach((item, index) => {
        if (results[index] !== undefined) {
          item.resolve(results[index]);
        } else {
          item.reject(new Error(`Result not found for request at index ${index}`));
        }
      });

      console.log(`[BATCH] Successfully processed ${batch.length} requests`);
    } catch (error) {
      // Se batchFn falhar, rejeitar todas as promises
      console.error(`[BATCH] Error processing batch of ${batch.length} requests:`, error);

      const errorMessage = error instanceof Error ? error.message : 'Unknown error during batch processing';
      batch.forEach(item => {
        item.reject(new Error(errorMessage));
      });
    }
  }

  /**
   * Força o processamento imediato de todos os requests pendentes
   */
  public forceFlush(): Promise<void> {
    if (this.timeout) {
      clearTimeout(this.timeout);
      this.timeout = null;
    }
    return this.flush();
  }

  /**
   * Retorna o número de requests pendentes na fila
   */
  public get queueSize(): number {
    return this.queue.length;
  }
}

/**
 * Factory function para criar instâncias de RequestBatcher
 * 
 * @param batchFn - Função que processa um array de requests
 * @param delay - Tempo de espera para acumular requests (default 50ms)
 * @returns Nova instância de RequestBatcher
 * 
 * @example
 * ```typescript
 * // Criar batcher para buscar projetos
 * const projectBatcher = createBatcher(async (projectIds) => {
 *   const { data } = await supabase
 *     .from('projects')
 *     .select('*')
 *     .in('id', projectIds);
 *   return data;
 * });
 * 
 * // Uso (agrupa automaticamente)
 * const projects = await Promise.all(
 *   ids.map(id => projectBatcher.add(id))
 * );
 * ```
 */
export function createBatcher<T, R>(
  batchFn: (requests: T[]) => Promise<R[]>,
  delay?: number
): RequestBatcher<T, R> {
  return new RequestBatcher<T, R>(batchFn, delay);
}

/**
 * Exemplo de uso com Supabase
 */
export const exampleUsage = {
  // Criar batcher para buscar projetos
  projectBatcher: createBatcher(async (projectIds: string[]) => {
    // Simulação - substitua com sua lógica real
    console.log(`[EXAMPLE] Fetching projects: ${projectIds.join(', ')}`);
    return projectIds.map(id => ({ id, name: `Project ${id}` }));
  }),

  // Função helper para usar o batcher
  async fetchProjects(ids: string[]) {
    const projects = await Promise.all(
      ids.map(id => this.projectBatcher.add(id))
    );
    return projects;
  }
};

src/features/whatsapp-platform/lib/evolu.content:
interface EvolutionMessage {
  key: {
    id: string;
    remoteJid: string;
    fromMe: boolean;
  };
  message?: {
    conversation?: string;
    extendedTextMessage?: {
      text: string;
    };
    audioMessage?: {
      url: string;
      seconds: number;
      ptt: boolean;
      mimetype: string;
    };
    imageMessage?: {
      url: string;
      caption?: string;
      mimetype: string;
      width?: number;
      height?: number;
    };
    videoMessage?: {
      url: string;
      caption?: string;
      mimetype: string;
      seconds?: number;
    };
    documentMessage?: {
      url: string;
      fileName: string;
      mimetype: string;
      fileLength?: string;
      caption?: string;
    };
  };
  messageTimestamp: number;
  pushName?: string;
}

interface ProcessedMessage {
  id: string;
  content: string;
  timestamp: Date;
  sender: "user" | "contact";
  mediaType: "text" | "audio" | "image" | "video" | "document";
  mediaUrl?: string;
  caption?: string;
  duration?: number;
  fileName?: string;
  fileSize?: number;
}

/**
 * Processa uma mensagem recebida da Evolution API
 */
export function processEvolutionMessage(msg: EvolutionMessage): ProcessedMessage {
  const baseMessage: ProcessedMessage = {
    id: msg.key.id,
    timestamp: new Date(msg.messageTimestamp * 1000),
    sender: (msg.key.fromMe ? "user" : "contact") as "user" | "contact",
    content: "",
    mediaType: "text" as const,
  };

  // Processar mensagem de texto
  if (msg.message?.conversation) {
    return {
      ...baseMessage,
      content: msg.message.conversation,
      mediaType: "text" as const,
    };
  }

  // Processar mensagem de texto estendida
  if (msg.message?.extendedTextMessage?.text) {
    return {
      ...baseMessage,
      content: msg.message.extendedTextMessage.text,
      mediaType: "text" as const,
    };
  }

  // Processar áudio
  if (msg.message?.audioMessage) {
    const audio = msg.message.audioMessage;
    return {
      ...baseMessage,
      content: audio.ptt ? "🎤 Mensagem de voz" : "🎵 Áudio",
      mediaType: "audio" as const,
      mediaUrl: audio.url,
      duration: audio.seconds,
    };
  }

  // Processar imagem
  if (msg.message?.imageMessage) {
    const image = msg.message.imageMessage;
    return {
      ...baseMessage,
      content: image.caption || "📷 Imagem",
      mediaType: "image" as const,
      mediaUrl: image.url,
      caption: image.caption,
    };
  }

  // Processar vídeo
  if (msg.message?.videoMessage) {
    const video = msg.message.videoMessage;
    return {
      ...baseMessage,
      content: video.caption || "🎥 Vídeo",
      mediaType: "video" as const,
      mediaUrl: video.url,
      caption: video.caption,
      duration: video.seconds,
    };
  }

  // Processar documento
  if (msg.message?.documentMessage) {
    const doc = msg.message.documentMessage;
    return {
      ...baseMessage,
      content: doc.caption || `📄 ${doc.fileName}`,
      mediaType: "document" as const,
      mediaUrl: doc.url,
      caption: doc.caption,
      fileName: doc.fileName,
      fileSize: doc.fileLength ? parseInt(doc.fileLength) : undefined,
    };
  }

  // Mensagem não suportada
  return {
    ...baseMessage,
    content: "Mensagem não suportada",
    mediaType: "text" as const,
  };
}

/**
 * Processa múltiplas mensagens da Evolution API
 */
export function processEvolutionMessages(messages: EvolutionMessage[]): ProcessedMessage[] {
  return messages.map(processEvolutionMessage);
}

/**
 * Detecta o tipo de mídia de uma mensagem
 */
export function detectMediaType(msg: EvolutionMessage): "text" | "audio" | "image" | "video" | "document" {
  if (msg.message?.audioMessage) return "audio";
  if (msg.message?.imageMessage) return "image";
  if (msg.message?.videoMessage) return "video";
  if (msg.message?.documentMessage) return "document";
  return "text";
}

