src/hooks/useCachedData.ts.content:
import { useState, useEffect } from 'react';

interface CacheEntry<T> {
  data: T;
  timestamp: number;
}

/**
 * Hook para gerenciar dados em cache com localStorage
 * Os dados são salvos no localStorage e só recarregados quando explicitamente solicitado
 */
export function useCachedData<T>(
  key: string,
  fetchFn: () => Promise<T>,
  dependencies: any[] = []
) {
  const [data, setData] = useState<T | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [shouldRefresh, setShouldRefresh] = useState(false);

  // Carregar dados do cache ou buscar se não existir
  useEffect(() => {
    const loadData = async () => {
      // Primeiro tenta carregar do localStorage
      const cached = localStorage.getItem(key);

      if (cached && !shouldRefresh) {
        try {
          const entry: CacheEntry<T> = JSON.parse(cached);
          console.log(`📦 ${key} carregados do cache (${new Date(entry.timestamp).toLocaleString()})`);
          setData(entry.data);
          return;
        } catch (e) {
          console.error(`❌ Erro ao carregar cache de ${key}:`, e);
        }
      }

      // Se não tiver cache ou for refresh, busca novos dados
      if (!cached || shouldRefresh) {
        setIsLoading(true);
        try {
          console.log(`🔄 Buscando ${key}...`);
          const newData = await fetchFn();

          const entry: CacheEntry<T> = {
            data: newData,
            timestamp: Date.now(),
          };

          localStorage.setItem(key, JSON.stringify(entry));
          setData(newData);
          console.log(`✅ ${key} salvos no cache`);
        } catch (error) {
          console.error(`❌ Erro ao buscar ${key}:`, error);
        } finally {
          setIsLoading(false);
          setShouldRefresh(false);
        }
      }
    };

    loadData();
  }, [key, shouldRefresh, ...dependencies]);

  const refresh = () => {
    setShouldRefresh(true);
  };

  const clearCache = () => {
    localStorage.removeItem(key);
    setData(null);
  };

  return { data, isLoading, refresh, clearCache };
}

src/components/notion/blocks/PdfBlock.ts.content:
import { useState } from 'react';
import { useNotionStore } from '@/stores/notionStore';
import type { BaseBlock } from '@/types/notion';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { FileText, Trash2 } from 'lucide-react';

interface PdfBlockProps {
  block: BaseBlock;
}

export const PdfBlock = ({ block }: PdfBlockProps) => {
  const { updateBlock, deleteBlock } = useNotionStore();
  const { isLocked } = useNotionStore(state => ({ isLocked: state.getCurrentPage()?.locked }));
  const [url, setUrl] = useState(block.url || '');
  const [showActions, setShowActions] = useState(false);

  const handleUrlChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (isLocked) return;
    const newUrl = e.target.value;
    setUrl(newUrl);
    updateBlock(block.id, { url: newUrl });
  };

  return (
    <div
      className="relative group notion-hover rounded px-1"
      onMouseEnter={() => setShowActions(true)}
      onMouseLeave={() => setShowActions(false)}
    >
      <div className="border border-border rounded-lg overflow-hidden">
        <div className="bg-muted px-3 py-2 flex items-center gap-2">
          <FileText className="h-4 w-4 text-red-500" />
          <Input
            type="url"
            placeholder="Cole a URL do PDF"
            value={url}
            onChange={handleUrlChange}
            className="flex-1 h-8 text-sm border-0 bg-transparent focus-visible:ring-0"
            data-testid={`pdf-url-${block.id}`}
            disabled={isLocked}
          />
          {showActions && (
            <Button
              variant="ghost"
              size="sm"
              className="h-6 w-6 p-0 opacity-0 group-hover:opacity-100"
              onClick={() => deleteBlock(block.id)}
              disabled={isLocked}
            >
              <Trash2 className="h-3 w-3" />
            </Button>
          )}
        </div>
        {url ? (
          <div className="aspect-[8.5/11] bg-muted/50">
            <iframe
              src={url}
              className="w-full h-full"
              title="PDF Viewer"
              sandbox="allow-scripts allow-same-origin"
              referrerPolicy="no-referrer"
            />
          </div>
        ) : (
          <div className="aspect-[8.5/11] bg-muted/50 flex items-center justify-center text-muted-foreground">
            <p className="text-sm">Adicione uma URL do PDF para visualizar</p>
          </div>
        )}
      </div>
    </div>
  );
};

src/components/kanban/card-detail/CardAt.content:
import { Card } from '@/types/kanban';
import { Paperclip, ExternalLink, Trash2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { format } from 'date-fns';
import { ptBR } from 'date-fns/locale/pt-BR';

interface CardAttachmentsSectionProps {
  card: Card;
  onUpdate: (card: Card) => void;
}

export const CardAttachmentsSection = ({ card, onUpdate }: CardAttachmentsSectionProps) => {
  const deleteAttachment = (attachmentId: string) => {
    const updatedAttachments = card.attachments.filter((a) => a.id !== attachmentId);
    onUpdate({ ...card, attachments: updatedAttachments });
  };

  if (card.attachments.length === 0) return null;

  return (
    <div>
      <div className="flex items-center gap-3 mb-3">
        <Paperclip className="w-5 h-5 text-muted-foreground" />
        <h3 className="font-semibold">Anexos</h3>
      </div>
      <div className="space-y-2">
        {card.attachments.map((attachment) => (
          <div
            key={attachment.id}
            className="flex items-center gap-3 p-3 bg-secondary/30 rounded hover:bg-secondary/50 transition-colors group"
          >
            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-2">
                <a
                  href={attachment.url}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="font-medium text-sm hover:underline flex items-center gap-1"
                >
                  {attachment.name}
                  <ExternalLink className="w-3 h-3" />
                </a>
              </div>
              <p className="text-xs text-muted-foreground mt-1">
                Adicionado {format(attachment.addedAt, "d 'de' MMMM 'às' HH:mm", { locale: ptBR })}
              </p>
            </div>
            <Button
              variant="ghost"
              size="icon"
              className="opacity-0 group-hover:opacity-100 transition-opacity h-8 w-8"
              onClick={() => deleteAttachment(attachment.id)}
            >
              <Trash2 className="w-4 h-4 text-destructive" />
            </Button>
          </div>
        ))}
      </div>
    </div>
  );
};

