    }

    return {
      success: true,
      data: uniqueEvents,
      source: 'integrated',
      sources: {
        google_calendar: formattedEvents.length,
        ical: icalEvents.length,
        workspace: workspaceEvents.length,
        total_unique: uniqueEvents.length
      },
      total: uniqueEvents.length
    };
      },
