## 6. LÓGICA DE DETERMINAÇÃO DO PIPELINE STATUS

### 6.1 Função Principal

```typescript
// Localização: server/lib/leadJourneyAggregator.ts (linha 223-269)

function determinePipelineStatus(journey: Partial<LeadJourney> & { formularioEnvio?: any }): string {
  const { meeting, cpfData, form, formularioEnvio } = journey;

  // PRIORIDADE 1: Resultado final (consultor)
  if (meeting?.resultadoReuniao) {
    return 'consultor';
  }

  // PRIORIDADE 2: Status da reunião
  if (meeting?.status === 'realizada') {
    return 'reuniao-completo';
  }

  if (meeting?.status === 'nao_compareceu' || meeting?.status === 'naocompareceu') {
    return 'reuniao-nao-compareceu';
  }

  if (meeting?.status === 'agendada' || meeting?.status === 'agendado') {
    return 'reuniao-agendada';
  }

  if (meeting?.status === 'pendente' && meeting?.data) {
    return 'reuniao-pendente';
  }

  // PRIORIDADE 3: Status do CPF
  if (cpfData) {
    if (cpfData.status === 'rejected' || cpfData.aprovado === false) {
      return 'cpf-reprovado';
    }
    if (cpfData.status === 'approved' || cpfData.aprovado === true) {
      return 'cpf-aprovado';
    }
  }

  // PRIORIDADE 4: Status do formulário
  if (form) {
    if (form.passed === false) {
      return 'formulario-reprovado';
    }
    if (form.passed === true) {
      return 'formulario-aprovado';
    }
  }

  // PRIORIDADE 5: Formulário enviado mas não preenchido
  if (formularioEnvio && !form) {
    return 'formulario-nao-preenchido';
  }

  // DEFAULT: Contato inicial
  return 'contato-inicial';
}
```

### 6.2 Mapeamento formStatus → pipelineStatus (leadSync.ts)

```typescript
// Localização: server/formularios/services/leadSync.ts (linha 38-62)

function getPipelineStatus(formStatus: string, qualificationStatus: string): string {
  // Qualificação tem prioridade sobre status do formulário
  if (qualificationStatus === 'approved') {
    return 'formulario-aprovado';
  }
  if (qualificationStatus === 'rejected') {
    return 'formulario-reprovado';
  }

  // Mapeamento baseado no status do formulário
  switch (formStatus) {
    case 'not_sent':
      return 'contato-inicial';
    case 'sent':
      return 'formulario-enviado';
    case 'opened':
      return 'formulario-aberto';
    case 'started':
      return 'formulario-incompleto';
    case 'completed':
      return 'formulario-completo';
    default:
      return 'contato-inicial';
  }
}
```

