## 8. AGREGADOR DE JORNADAS

### 8.1 Função Principal: aggregateLeadJourneys()

```typescript
// Localização: server/lib/leadJourneyAggregator.ts

export async function aggregateLeadJourneys(tenantId: string): Promise<LeadJourney[]> {
  // 1. Fetch data from all sources in parallel
  const [
    clienteMap,        // dados_cliente (phone → record)
    submissionsMap,    // form_submissions (tel:/cpf:/name: → record)
    cpfMap,            // cpf_compliance_resultados (cpf:/tel: → record)
    reunioesMap,       // reunioes (phone → record)
    dashboardMap,      // dashboard_completo_v5_base (phone → record)
    formEnviosMap      // formulario_envios (phone → record)
  ] = await Promise.all([
    fetchDadosCliente(tenantId),
    fetchFormSubmissions(tenantId),
    fetchCpfComplianceResults(tenantId),
    fetchReunioes(tenantId),
    fetchDashboardData(tenantId),
    fetchFormularioEnvios(tenantId)
  ]);

  // 2. Collect all unique phone numbers
  const allPhones = new Set<string>();
  // ... add phones from all maps

  // 3. For each phone, build the complete journey
  for (const phone of allPhones) {
    const journey = buildJourneyForPhone(phone, tenantId, ...maps);
    journeys.push(journey);
  }

  // 4. Sort by most recent activity
  return journeys.sort((a, b) => 
    new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime()
  );
}
```

