export { InputOTP, InputOTPGroup, InputOTPSlot, InputOTPSeparator };

src/components/notion/ThemeSelector.tsx.content:
import { useState, useEffect } from 'react';
import { Label } from '@/components/ui/label';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Plus, Tag, Sparkles } from 'lucide-react';
import { nanoid } from 'nanoid';

interface Theme {
  id: string;
  name: string;
  icon: string;
  color: string;
}

interface ThemeSelectorProps {
  selectedThemeId?: string;
  onThemeSelect: (themeId: string) => void;
  userId?: string;
}

export const ThemeSelector = ({ selectedThemeId, onThemeSelect, userId }: ThemeSelectorProps) => {
  const [themes, setThemes] = useState<Theme[]>([]);
  const [isCreatingNew, setIsCreatingNew] = useState(false);
  const [newThemeName, setNewThemeName] = useState('');
  const [newThemeIcon, setNewThemeIcon] = useState('🏷️');
  const [newThemeColor, setNewThemeColor] = useState('#6366f1');

  const themeIcons = ['🏷️', '📁', '🎯', '💼', '🚀', '⭐', '🎨', '📊', '💡', '🔖', '📌', '✨'];

  const themeColors = [
    { name: 'Azul', value: '#6366f1' },
    { name: 'Verde', value: '#10b981' },
    { name: 'Vermelho', value: '#ef4444' },
    { name: 'Amarelo', value: '#eab308' },
    { name: 'Roxo', value: '#a855f7' },
    { name: 'Rosa', value: '#ec4899' },
    { name: 'Laranja', value: '#f97316' },
    { name: 'Cinza', value: '#6b7280' },
  ];

  useEffect(() => {
    fetchThemes();
  }, []);

  const fetchThemes = async () => {
    try {
      const response = await fetch('/api/workspace/themes');
      if (response.ok) {
        const data = await response.json();
        setThemes(data);
      }
    } catch (error) {
      console.error('Erro ao carregar temas:', error);
    }
  };

  const handleCreateTheme = async () => {
    if (!newThemeName.trim()) return;

    const newTheme: Theme = {
      id: nanoid(),
      name: newThemeName,
      icon: newThemeIcon,
      color: newThemeColor,
    };

    try {
      const response = await fetch('/api/workspace/themes', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newTheme),
      });

      if (response.ok) {
        const createdTheme = await response.json();
        setThemes([...themes, createdTheme]);
        onThemeSelect(createdTheme.id);
        setIsCreatingNew(false);
        setNewThemeName('');
        setNewThemeIcon('🏷️');
        setNewThemeColor('#6366f1');
      }
    } catch (error) {
      console.error('Erro ao criar tema:', error);
    }
  };

  if (isCreatingNew) {
    return (
      <div className="space-y-4 p-4 border rounded-lg bg-muted/50">
        <div className="flex items-center justify-between">
          <Label className="text-sm font-medium flex items-center gap-2">
            <Sparkles className="h-4 w-4" />
            Criar Novo Tema
          </Label>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setIsCreatingNew(false)}
          >
            Cancelar
          </Button>
        </div>

        <div className="space-y-3">
          <div>
            <Label className="text-xs">Nome do Tema</Label>
            <Input
              value={newThemeName}
              onChange={(e) => setNewThemeName(e.target.value)}
              placeholder="Ex: Projetos, Finanças, Marketing..."
              className="mt-1"
            />
          </div>

          <div>
            <Label className="text-xs">Ícone</Label>
            <div className="flex gap-2 flex-wrap mt-1">
              {themeIcons.map((icon) => (
                <button
                  key={icon}
                  onClick={() => setNewThemeIcon(icon)}
                  className={`text-xl p-2 rounded hover:bg-background ${
                    newThemeIcon === icon ? 'bg-background ring-2 ring-primary' : ''
                  }`}
                >
                  {icon}
                </button>
              ))}
            </div>
          </div>

          <div>
            <Label className="text-xs">Cor</Label>
            <div className="grid grid-cols-4 gap-2 mt-1">
              {themeColors.map((color) => (
                <button
                  key={color.value}
                  onClick={() => setNewThemeColor(color.value)}
                  className={`flex items-center gap-2 p-2 rounded hover:bg-background ${
                    newThemeColor === color.value ? 'bg-background ring-2 ring-primary' : ''
                  }`}
                >
                  <div
                    className="w-4 h-4 rounded-full"
                    style={{ backgroundColor: color.value }}
                  />
                  <span className="text-xs">{color.name}</span>
                </button>
              ))}
            </div>
          </div>

          <Button
            onClick={handleCreateTheme}
            disabled={!newThemeName.trim()}
            className="w-full"
          >
            <Plus className="h-4 w-4 mr-2" />
            Criar Tema
          </Button>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-3">
      <Label className="flex items-center gap-2">
        <Tag className="h-4 w-4" />
        Tema / Categoria
      </Label>
      <Select value={selectedThemeId} onValueChange={onThemeSelect}>
        <SelectTrigger>
          <SelectValue placeholder="Selecione um tema..." />
        </SelectTrigger>
        <SelectContent>
          <SelectItem value="none">
            <span className="text-muted-foreground">Sem tema</span>
          </SelectItem>
          {themes.map((theme) => (
            <SelectItem key={theme.id} value={theme.id}>
              <div className="flex items-center gap-2">
                <span>{theme.icon}</span>
                <span>{theme.name}</span>
                <div
                  className="w-3 h-3 rounded-full ml-auto"
                  style={{ backgroundColor: theme.color }}
                />
              </div>
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
      <Button
        variant="outline"
        size="sm"
        onClick={() => setIsCreatingNew(true)}
        className="w-full"
      >
        <Plus className="h-4 w-4 mr-2" />
        Criar Novo Tema
      </Button>
    </div>
  );
};

src/features/formularios-platform/pages/.content:
import { useState, useEffect } from "react";
import { Card } from "../components/ui/card";
import { Button } from "../components/ui/button";
import { Input } from "../components/ui/input";
import { Label } from "../components/ui/label";
import { testSupabaseConnection } from "../lib/supabase-helpers";
import { Settings, Save, Trash2, ArrowLeft, CheckCircle2, Database, Loader2 } from "lucide-react";
import { useLocation } from "wouter";
import { toast } from "sonner";
import { api } from "../lib/api";
import { useQueryClient } from "@tanstack/react-query";

const Configuracoes = () => {
  const [, navigate] = useLocation();
  const queryClient = useQueryClient();
  const [url, setUrl] = useState("");
  const [anonKey, setAnonKey] = useState("");
  const [companyName, setCompanyName] = useState("");
  const [testing, setTesting] = useState(false);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    // Buscar configurações do servidor E localStorage
    const loadSettings = async () => {
      try {
        // Primeiro tentar do localStorage (mais rápido)
        const localUrl = localStorage.getItem('supabase_url');
        const localKey = localStorage.getItem('supabase_anon_key');
        const localCompanyName = localStorage.getItem('company_name');

        if (localUrl && localKey) {
          console.log('✅ Carregando credenciais do localStorage');
          setUrl(localUrl);
          setAnonKey(localKey);
          setCompanyName(localCompanyName || '');
          setLoading(false);
          return;
        }

        // Se não tem no localStorage, buscar do servidor
        console.log('📡 Carregando credenciais do servidor...');
        const settings = await api.getSettings();
        if (settings.supabaseUrl && settings.supabaseAnonKey) {
          setUrl(settings.supabaseUrl);
          setAnonKey(settings.supabaseAnonKey);
          setCompanyName(settings.companyName || '');

          // Salvar no localStorage para próxima vez
          localStorage.setItem('supabase_url', settings.supabaseUrl);
          localStorage.setItem('supabase_anon_key', settings.supabaseAnonKey);
          if (settings.companyName) {
            localStorage.setItem('company_name', settings.companyName);
          }
          console.log('✅ Credenciais sincronizadas do servidor para localStorage');
        }
      } catch (error) {
        console.error("Erro ao carregar configurações:", error);
      } finally {
        setLoading(false);
      }
    };

    loadSettings();
  }, []);

  const handleTest = async () => {
    if (!url || !anonKey) {
      toast.error("Por favor, preencha todos os campos");
      return;
    }

    if (!url.startsWith("http")) {
      toast.error("URL deve começar com http:// ou https://");
      return;
    }

    setTesting(true);
    try {
      const result = await testSupabaseConnection(url, anonKey);

      if (result.success) {
        toast.success(result.message);
      } else {
        toast.error(`Erro: ${result.message}`);
      }
    } catch (error: any) {
      toast.error(`Erro ao testar: ${error.message}`);
    } finally {
      setTesting(false);
    }
  };

  const handleSave = async () => {
    if (!url || !anonKey) {
      toast.error("Por favor, preencha os campos de Supabase");
      return;
    }

    if (!url.startsWith("http")) {
      toast.error("URL deve começar com http:// ou https://");
      return;
    }

    setSaving(true);
    try {
      await api.saveSettings({
        supabaseUrl: url,
        supabaseAnonKey: anonKey,
        companyName: companyName || null
      });

      // ✅ CORREÇÃO CRÍTICA: Salvar no localStorage para que o frontend envie nos headers
      localStorage.setItem('supabase_url', url);
      localStorage.setItem('supabase_anon_key', anonKey);
      if (companyName) {
        localStorage.setItem('company_name', companyName);
      } else {
        localStorage.removeItem('company_name');
      }
      console.log('✅ Credenciais salvas no localStorage');

      // ✅ CORREÇÃO CRÍTICA: Invalidar queries de formulários para recarregar dados do Supabase
      console.log('🔄 Invalidando queries de formulários para recarregar do Supabase...');
      queryClient.invalidateQueries({ queryKey: ["/api/forms"] });
      queryClient.invalidateQueries({ queryKey: ["/api/formularios/ativo"] });
      console.log('✅ Queries invalidadas - formulários serão recarregados');

      toast.success("Configurações salvas! O sistema agora usará seu Supabase.");
    } catch (error: any) {
      toast.error(`Erro ao salvar: ${error.message}`);
    } finally {
      setSaving(false);
    }
  };

  const handleClear = async () => {
    setSaving(true);
    try {
      await api.saveSettings({
        supabaseUrl: "",
        supabaseAnonKey: "",
        companyName: ""
      });

      // ✅ CORREÇÃO CRÍTICA: Limpar do localStorage também
      localStorage.removeItem('supabase_url');
      localStorage.removeItem('supabase_anon_key');
      localStorage.removeItem('company_name');
      console.log('✅ Credenciais removidas do localStorage');

      // ✅ CORREÇÃO CRÍTICA: Invalidar queries de formulários para recarregar do PostgreSQL local
      console.log('🔄 Invalidando queries de formulários para recarregar do PostgreSQL local...');
      queryClient.invalidateQueries({ queryKey: ["/api/forms"] });
      queryClient.invalidateQueries({ queryKey: ["/api/formularios/ativo"] });
      console.log('✅ Queries invalidadas - formulários serão recarregados do PostgreSQL local');

      setUrl("");
      setAnonKey("");
      setCompanyName("");
      toast.success("Configurações removidas. Usando PostgreSQL local.");
    } catch (error: any) {
      toast.error(`Erro ao limpar: ${error.message}`);
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="container mx-auto px-4 py-12">
      <div className="max-w-2xl mx-auto">
        <Button
          onClick={() => navigate("/")}
          variant="outline"
          className="mb-6 gap-2"
        >
          <ArrowLeft className="h-4 w-4" />
          Voltar
        </Button>

        <header className="text-center mb-8">
          <div className="inline-flex items-center gap-2 mb-4 px-4 py-2 bg-primary/10 border border-primary/20 rounded-full">
            <Settings className="h-4 w-4 text-primary" />
            <span className="text-sm font-medium text-primary">Configurações</span>
          </div>
          <h1 className="text-4xl font-bold mb-3 bg-gradient-to-r from-primary via-primary-glow to-accent bg-clip-text text-transparent">
            Conexão Supabase
          </h1>
          <p className="text-lg text-muted-foreground">
            Configure suas credenciais do Supabase para salvar os dados
          </p>
        </header>

