import { X, Download } from "lucide-react";
import { Dialog, DialogContent } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { useState, useEffect } from "react";

interface MediaModalProps {
  isOpen: boolean;
  onClose: () => void;
  mediaUrl: string;
  mediaType: "image" | "video";
  caption?: string;
  fileName?: string;
}

export function MediaModal({ isOpen, onClose, mediaUrl, mediaType, caption, fileName }: MediaModalProps) {
  const [isFullscreen, setIsFullscreen] = useState(false);

  useEffect(() => {
    const handleEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        onClose();
      }
    };

    if (isOpen) {
      document.addEventListener('keydown', handleEsc);
      document.body.style.overflow = 'hidden';
    }

    return () => {
      document.removeEventListener('keydown', handleEsc);
      document.body.style.overflow = 'unset';
    };
  }, [isOpen, onClose]);

  const handleDownload = () => {
    const a = document.createElement('a');
    a.href = mediaUrl;
    a.download = fileName || (mediaType === 'image' ? 'imagem.jpg' : 'video.mp4');
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] bg-black/95 flex items-center justify-center animate-in fade-in duration-200">
      {/* Header */}
      <div className="absolute top-0 left-0 right-0 z-10 flex items-center justify-between p-4 bg-gradient-to-b from-black/80 to-transparent">
        <div className="flex-1">
          {caption && (
            <p className="text-white text-sm line-clamp-2">{caption}</p>
          )}
        </div>
        <div className="flex items-center gap-2">
          <Button
            variant="ghost"
            size="icon"
            onClick={handleDownload}
            className="text-white hover:bg-white/20"
          >
            <Download className="h-5 w-5" />
          </Button>
          <Button
            variant="ghost"
            size="icon"
            onClick={onClose}
            className="text-white hover:bg-white/20"
          >
            <X className="h-6 w-6" />
          </Button>
        </div>
      </div>

      {/* Media Content */}
      <div className="relative w-full h-full flex items-center justify-center p-4 pt-16 pb-16">
        {mediaType === "image" ? (
          <img
            src={mediaUrl}
            alt={caption || "Imagem"}
            className="max-w-full max-h-full object-contain cursor-zoom-in"
            onClick={(e) => {
              e.stopPropagation();
              setIsFullscreen(!isFullscreen);
            }}
            style={isFullscreen ? {
              width: '100vw',
              height: '100vh',
              objectFit: 'contain',
              maxWidth: 'none',
              maxHeight: 'none'
            } : undefined}
          />
        ) : (
          <video
            src={mediaUrl}
            controls
            autoPlay
            className="max-w-full max-h-full"
            style={{ maxHeight: '90vh', maxWidth: '90vw' }}
          >
            <source src={mediaUrl} type="video/mp4" />
            Seu navegador não suporta vídeo.
          </video>
        )}
      </div>

      {/* Footer */}
      {caption && (
        <div className="absolute bottom-0 left-0 right-0 z-10 p-4 bg-gradient-to-t from-black/80 to-transparent">
          <p className="text-white text-sm text-center">{caption}</p>
        </div>
      )}

      {/* Click outside to close */}
      <div 
        className="absolute inset-0 -z-10"
        onClick={onClose}
      />
    </div>
  );
}

src/components/billing/ImageUploader.tsx.content:
import { useState, useRef, ChangeEvent, DragEvent } from 'react';
import { Upload, Camera, X, Check } from 'lucide-react';
import { useUploadAttachment } from '@/hooks/useAttachments';

interface ImageUploaderProps {
  onSuccess?: () => void;
  onCancel?: () => void;
}

export function ImageUploader({ onSuccess, onCancel }: ImageUploaderProps) {
  const [file, setFile] = useState<File | null>(null);
  const [preview, setPreview] = useState<string | null>(null);
  const [isDragging, setIsDragging] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const cameraInputRef = useRef<HTMLInputElement>(null);
  const uploadMutation = useUploadAttachment();

  const handleFile = (selectedFile: File) => {
    // Validar que é uma imagem
    if (!selectedFile.type.startsWith('image/')) {
      alert('Por favor, selecione apenas imagens (JPEG, PNG, WebP)');
      return;
    }

    setFile(selectedFile);

    const reader = new FileReader();
    reader.onloadend = () => {
      setPreview(reader.result as string);
    };
    reader.readAsDataURL(selectedFile);
  };

  const handleDragOver = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = () => {
    setIsDragging(false);
  };

  const handleDrop = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    setIsDragging(false);

    const droppedFile = e.dataTransfer.files[0];
    if (droppedFile) {
      // Validar que é uma imagem antes de processar
      if (!droppedFile.type.startsWith('image/')) {
        alert('Por favor, arraste apenas arquivos de imagem');
        return;
      }
      handleFile(droppedFile);
    }
  };

  const handleFileChange = (e: ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (selectedFile) {
      handleFile(selectedFile);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!file) {
      alert('Selecione uma imagem');
      return;
    }

    try {
      await uploadMutation.mutateAsync({
        file,
        category: '',
        amount: '',
        date: new Date().toISOString().split('T')[0],
        description: file.name,
        type: 'receipt',
      });

      setFile(null);
      setPreview(null);

      if (onSuccess) onSuccess();
    } catch (error) {
      console.error('Erro ao fazer upload:', error);
      alert('Erro ao fazer upload. Tente novamente.');
    }
  };

  const handleReset = () => {
    setFile(null);
    setPreview(null);
  };

  return (
    <div className="space-y-4">
      {!file ? (
        <div
          className={`border-2 border-dashed rounded-lg p-8 text-center transition-colors ${
            isDragging
              ? 'border-blue-500 bg-blue-50 dark:bg-blue-950'
              : 'border-gray-300 dark:border-gray-700'
          }`}
          onDragOver={handleDragOver}
          onDragLeave={handleDragLeave}
          onDrop={handleDrop}
        >
          <div className="space-y-4">
            <div className="flex justify-center gap-4">
              <button
                type="button"
                onClick={() => fileInputRef.current?.click()}
                className="flex flex-col items-center gap-2 px-6 py-4 bg-blue-500 text-white rounded-lg hover:bg-blue-600 transition-colors"
              >
                <Upload className="w-6 h-6" />
                <span>Selecionar Imagem</span>
              </button>

              <button
                type="button"
                onClick={() => cameraInputRef.current?.click()}
                className="flex flex-col items-center gap-2 px-6 py-4 bg-green-500 text-white rounded-lg hover:bg-green-600 transition-colors"
              >
                <Camera className="w-6 h-6" />
                <span>Tirar Foto</span>
              </button>
            </div>

            <p className="text-sm text-gray-500 dark:text-gray-400">
              Ou arraste e solte uma imagem aqui
            </p>

            <p className="text-xs text-gray-400 dark:text-gray-500">
              Formatos aceitos: JPEG, PNG, WebP (máx. 10MB)
            </p>
          </div>

          {/* Input para selecionar imagem da galeria - apenas imagens */}
          <input
            ref={fileInputRef}
            type="file"
            accept="image/*"
            onChange={handleFileChange}
            className="hidden"
          />

          {/* Input para tirar foto com a câmera - força uso da câmera traseira */}
          <input
            ref={cameraInputRef}
            type="file"
            accept="image/*"
            capture="environment"
            onChange={handleFileChange}
            className="hidden"
          />
        </div>
      ) : (
        <form onSubmit={handleSubmit} className="space-y-4">
          {preview && (
            <div className="relative">
              <img
                src={preview}
                alt="Preview"
                className="w-full max-h-96 object-contain rounded-lg border border-gray-200 dark:border-gray-700"
              />
              <button
                type="button"
                onClick={handleReset}
                className="absolute top-2 right-2 p-2 bg-red-500 text-white rounded-full hover:bg-red-600 transition-colors"
              >
                <X className="w-4 h-4" />
              </button>
            </div>
          )}

          <div className="bg-blue-50 dark:bg-blue-950 border border-blue-200 dark:border-blue-800 rounded-lg p-4">
            <p className="text-sm text-blue-800 dark:text-blue-200">
              📸 A imagem será enviada e processada automaticamente
            </p>
          </div>

          <div className="flex gap-3">
            <button
              type="submit"
              disabled={uploadMutation.isPending}
              className="flex-1 flex items-center justify-center gap-2 px-4 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            >
              {uploadMutation.isPending ? (
                <>
                  <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                  Enviando...
                </>
              ) : (
                <>
                  <Check className="w-4 h-4" />
                  Enviar Imagem
                </>
              )}
            </button>

            {onCancel && (
              <button
                type="button"
                onClick={onCancel}
                className="px-4 py-2 border border-gray-300 dark:border-gray-700 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
              >
                Cancelar
              </button>
            )}
          </div>
        </form>
      )}
    </div>
  );
}

src/components/notion/views/BoardDatabas.content:
import { useState } from 'react';
import { Plus, GripVertical } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { cn } from '@/lib/utils';
import type { StoreDatabase } from '@/stores/notionStore';

interface BoardDatabaseViewProps {
  database: StoreDatabase;
  onUpdateDatabase: (updates: Partial<StoreDatabase>) => void;
  locked?: boolean;
}

export const BoardDatabaseView = ({
  database,
  onUpdateDatabase,
  locked = false,
}: BoardDatabaseViewProps) => {
  const [draggedRowId, setDraggedRowId] = useState<string | null>(null);

  const statusField = database.fields.find(f => f.type === 'select' || f.name.toLowerCase().includes('status'));

  if (!statusField || !statusField.options) {
    return (
      <div className="p-8 text-center text-gray-500">
        <p>Para usar a visualização de quadro, adicione um campo de seleção para o status.</p>
      </div>
    );
  }

  const columns = statusField.options.map(option => ({
    id: option,
    name: option,
    rows: (database.rows || []).filter(row => row.values[statusField.id] === option),
  }));

  const addRow = (statusValue: string) => {
    if (locked) return;

    const newRow: any = {
      id: Date.now().toString(),
      values: {
        [statusField.id]: statusValue,
      },
    };

    database.fields.forEach(field => {
      if (field.id !== statusField.id) {
        newRow.values[field.id] = field.type === 'checkbox' ? false : '';
      }
    });

    onUpdateDatabase({
      rows: [...(database.rows || []), newRow],
    });
  };

  const moveRow = (rowId: string, newStatus: string) => {
    if (locked) return;

    onUpdateDatabase({
      rows: (database.rows || []).map(row =>
        row.id === rowId
          ? { ...row, values: { ...row.values, [statusField.id]: newStatus } }
          : row
      ),
    });
  };

  const handleDragStart = (rowId: string) => {
    setDraggedRowId(rowId);
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDrop = (statusValue: string) => {
    if (draggedRowId) {
      moveRow(draggedRowId, statusValue);
      setDraggedRowId(null);
    }
  };

  const getFieldValue = (row: any, fieldId: string) => {
    const value = row.values[fieldId];
    const field = database.fields.find(f => f.id === fieldId);

    if (!field) return null;

    if (field.type === 'select' || field.type === 'multi-select') {
      if (Array.isArray(value)) {
        return value.map((v, i) => (
          <Badge key={i} variant="secondary" className="mr-1 text-xs">
            {v}
          </Badge>
        ));
      }
      return value ? <Badge variant="secondary" className="text-xs">{value}</Badge> : null;
    }

    if (field.type === 'checkbox') {
      return value ? '✓' : '';
    }

    return value || '';
  };

  const titleField = database.fields[0];

  return (
    <div className="flex gap-4 p-4 overflow-x-auto h-full bg-[#f7f6f5]">
      {columns.map(column => (
        <div
          key={column.id}
          className="flex-shrink-0 w-[280px] bg-white rounded-lg border border-[#e9e9e7] flex flex-col"
          onDragOver={handleDragOver}
          onDrop={() => handleDrop(column.id)}
        >
          <div className="p-3 border-b border-[#e9e9e7] bg-[#fafafa]">
            <div className="flex items-center justify-between">
              <h3 className="text-sm font-medium text-gray-900">
                {column.name}
              </h3>
              <span className="text-xs text-gray-500 bg-gray-100 px-2 py-0.5 rounded">
                {column.rows.length}
              </span>
            </div>
          </div>

          <div className="flex-1 p-2 space-y-2 overflow-y-auto">
            {column.rows.map(row => (
              <div
                key={row.id}
                draggable={!locked}
                onDragStart={() => handleDragStart(row.id)}
                className={cn(
                  "p-3 bg-white rounded border border-gray-200 cursor-pointer",
                  "hover:shadow-sm transition-all",
                  draggedRowId === row.id && "opacity-50",
                  !locked && "hover:border-gray-300"
                )}
                style={{
                  backgroundColor: row.backgroundColor,
                  color: row.textColor,
                }}
              >
                <div className="flex items-start gap-2">
                  {!locked && (
                    <GripVertical className="w-4 h-4 text-gray-400 mt-0.5 flex-shrink-0" />
                  )}
                  <div className="flex-1 min-w-0">
                    <div 
                      className={cn(
                        "text-sm mb-2",
                        row.fontWeight === 'bold' && "font-bold",
                        row.fontWeight === 'light' && "font-light",
                        row.fontSize === 'small' && "text-xs",
                        row.fontSize === 'large' && "text-base",
                        row.fontStyle === 'italic' && "italic"
                      )}
                    >
                      {row.values[titleField.id] || 'Sem título'}
                    </div>

                    <div className="flex flex-wrap gap-1">
                      {database.fields.slice(1).map(field => {
                        if (field.id === statusField.id) return null;
                        const value = getFieldValue(row, field.id);
                        if (!value) return null;

                        return (
                          <div key={field.id} className="text-xs text-gray-600">
                            {value}
                          </div>
                        );
                      })}
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>

          {!locked && (
            <div className="p-2 border-t border-[#e9e9e7]">
              <Button
                variant="ghost"
                size="sm"
                onClick={() => addRow(column.id)}
                className="w-full justify-start text-gray-600 hover:bg-[#f7f6f5] h-8 text-sm"
              >
                <Plus className="w-4 h-4 mr-1" />
                Nova página
              </Button>
            </div>
          )}
        </div>
      ))}

      {!locked && statusField.options && (
        <div className="flex-shrink-0 w-[280px]">
          <Button
            variant="outline"
            size="sm"
            className="w-full h-10 border-dashed border-gray-300 hover:border-gray-400 hover:bg-[#f7f6f5] text-gray-600"
            onClick={() => {
              const newOption = `Nova coluna ${statusField.options!.length + 1}`;
              onUpdateDatabase({
                fields: database.fields.map(f =>
                  f.id === statusField.id
                    ? { ...f, options: [...(f.options || []), newOption] }
                    : f
                ),
              });
            }}
          >
            <Plus className="w-4 h-4 mr-1" />
            Nova coluna
          </Button>
        </div>
      )}
    </div>
  );
};

