      let checks: any[] = [];

      if (ids && ids.length > 0) {
        // Download specific IDs - VERIFICAR CADA UM PERTENCE AO TENANT
        for (const id of ids) {
          let checkRecord: any = null;

          // Primeiro buscar do Supabase Master
