import { Badge } from "@/components/ui/badge";
import { X } from "lucide-react";
import { configManager, WhatsAppTag } from "../lib/config";

interface TagBadgeProps {
  tagId: string;
  size?: 'sm' | 'md';
  onRemove?: () => void;
  showRemove?: boolean;
}

export function TagBadge({ tagId, size = 'sm', onRemove, showRemove = false }: TagBadgeProps) {
  const tags = configManager.getTags();
  const tag = tags.find(t => t.id === tagId);

  if (!tag) {
    return null;
  }

  const textSize = size === 'sm' ? 'text-xs' : 'text-sm';
  const paddingSize = size === 'sm' ? 'px-2 py-0.5' : 'px-3 py-1';

  return (
    <Badge 
      className={`${textSize} ${paddingSize} border-0 flex items-center gap-1 font-medium shadow-sm`}
      style={{ 
        backgroundColor: tag.color,
        color: '#ffffff',
        borderColor: tag.color
      }}
    >
      <span>{tag.name}</span>
      {showRemove && onRemove && (
        <button
          onClick={(e) => {
            e.stopPropagation();
            onRemove();
          }}
          className="hover:bg-black/20 rounded-full p-0.5 transition-colors"
        >
          <X className="h-3 w-3" />
        </button>
      )}
    </Badge>
  );
}

src/features/revendedora/components/inve.content:
import { useState, useEffect } from 'react';
import { supabase } from '@/integrations/supabase/client';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Switch } from '@/components/ui/switch';
import { Separator } from '@/components/ui/separator';
import { Badge } from '@/components/ui/badge';
import { toast } from 'sonner';
import { Bell, Package, AlertTriangle, Save, Loader2 } from 'lucide-react';

interface Product {
  id: string;
  description: string | null;
  reference: string | null;
  image: string | null;
  barcode: string | null;
  category: string | null;
  price: number | null;
  stock: number | null;
  low_stock_threshold?: number | null;
  notify_low_stock?: boolean;
}

interface ProductEditModalProps {
  product: Product | null;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSaved?: () => void;
}

export function ProductEditModal({ product, open, onOpenChange, onSaved }: ProductEditModalProps) {
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState({
    description: '',
    reference: '',
    barcode: '',
    category: '',
    price: 0,
    stock: 0,
    low_stock_threshold: 5,
    notify_low_stock: true
  });

  useEffect(() => {
    if (product) {
      setFormData({
        description: product.description || '',
        reference: product.reference || '',
        barcode: product.barcode || '',
        category: product.category || '',
        price: product.price || 0,
        stock: product.stock || 0,
        low_stock_threshold: product.low_stock_threshold ?? 5,
        notify_low_stock: product.notify_low_stock ?? true
      });
    }
  }, [product]);

  const handleSave = async () => {
    if (!product || !supabase) return;

    setLoading(true);
    try {
      const { error } = await supabase
        .from('products')
        .update({
          description: formData.description,
          reference: formData.reference,
          barcode: formData.barcode,
          category: formData.category,
          price: formData.price,
          stock: formData.stock,
          low_stock_threshold: formData.low_stock_threshold,
          notify_low_stock: formData.notify_low_stock
        } as any)
        .eq('id', product.id);

      if (error) {
        if (error.code === '42703' || error.message?.includes('column') || error.message?.includes('low_stock_threshold')) {
          console.warn('[ProductEditModal] Stock alert columns not available, saving without them');
          const { error: fallbackError } = await supabase
            .from('products')
            .update({
              description: formData.description,
              reference: formData.reference,
              barcode: formData.barcode,
              category: formData.category,
              price: formData.price,
              stock: formData.stock
            })
            .eq('id', product.id);

          if (fallbackError) throw fallbackError;

          toast.success('Produto atualizado! (Alertas de estoque requerem migração do banco de dados)');
          onOpenChange(false);
          onSaved?.();
          return;
        }
        throw error;
      }

      toast.success('Produto atualizado com sucesso!');
      onOpenChange(false);
      onSaved?.();
    } catch (error: any) {
      console.error('[ProductEditModal] Error saving:', error);
      toast.error('Erro ao salvar produto: ' + error.message);
    } finally {
      setLoading(false);
    }
  };

  const isLowStock = formData.stock <= formData.low_stock_threshold;
  const isOutOfStock = formData.stock === 0;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[500px]">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Package className="h-5 w-5" />
            Editar Produto
          </DialogTitle>
          <DialogDescription>
            Configure as informações do produto e alertas de estoque
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-6 py-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="description">Descrição</Label>
              <Input
                id="description"
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                placeholder="Nome do produto"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="reference">Referência</Label>
              <Input
                id="reference"
                value={formData.reference}
                onChange={(e) => setFormData({ ...formData, reference: e.target.value })}
                placeholder="REF-001"
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="barcode">Código de Barras</Label>
              <Input
                id="barcode"
                value={formData.barcode}
                onChange={(e) => setFormData({ ...formData, barcode: e.target.value })}
                placeholder="7891234567890"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="category">Categoria</Label>
              <Input
                id="category"
                value={formData.category}
                onChange={(e) => setFormData({ ...formData, category: e.target.value })}
                placeholder="Acessórios"
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="price">Preço (R$)</Label>
              <Input
                id="price"
                type="number"
                step="0.01"
                min="0"
                value={formData.price}
                onChange={(e) => setFormData({ ...formData, price: parseFloat(e.target.value) || 0 })}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="stock">Estoque Atual</Label>
              <div className="flex items-center gap-2">
                <Input
                  id="stock"
                  type="number"
                  min="0"
                  value={formData.stock}
                  onChange={(e) => setFormData({ ...formData, stock: parseInt(e.target.value) || 0 })}
                />
                {isOutOfStock && (
                  <Badge variant="destructive">Esgotado</Badge>
                )}
                {isLowStock && !isOutOfStock && (
                  <Badge variant="secondary" className="bg-orange-200 text-orange-800">
                    Baixo
                  </Badge>
                )}
              </div>
            </div>
          </div>

          <Separator />

          <div className="space-y-4">
            <div className="flex items-center gap-2">
              <Bell className="h-5 w-5 text-primary" />
              <h4 className="font-semibold">Configuração de Alertas</h4>
            </div>

            <div className="flex items-center justify-between p-4 rounded-lg border bg-muted/50">
              <div className="space-y-1">
                <Label htmlFor="notify_low_stock" className="text-base font-medium">
                  Notificar quando estoque estiver baixo
                </Label>
                <p className="text-sm text-muted-foreground">
                  Receba alertas quando o produto atingir o limite mínimo
                </p>
              </div>
              <Switch
                id="notify_low_stock"
                checked={formData.notify_low_stock}
                onCheckedChange={(checked) => setFormData({ ...formData, notify_low_stock: checked })}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="low_stock_threshold" className="flex items-center gap-2">
                <AlertTriangle className="h-4 w-4 text-orange-500" />
                Limite mínimo de estoque
              </Label>
              <div className="flex items-center gap-3">
                <Input
                  id="low_stock_threshold"
                  type="number"
                  min="1"
                  max="999"
                  className="w-24"
                  value={formData.low_stock_threshold}
                  onChange={(e) => setFormData({ 
                    ...formData, 
                    low_stock_threshold: Math.max(1, parseInt(e.target.value) || 5)
                  })}
                />
                <span className="text-sm text-muted-foreground">
                  peças (notificação será enviada quando atingir este número)
                </span>
              </div>
              {formData.notify_low_stock && formData.stock <= formData.low_stock_threshold && (
                <p className="text-sm text-orange-600 flex items-center gap-1 mt-2">
                  <AlertTriangle className="h-4 w-4" />
                  O estoque atual ({formData.stock}) está abaixo do limite configurado ({formData.low_stock_threshold})
                </p>
              )}
            </div>
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)} disabled={loading}>
            Cancelar
          </Button>
          <Button onClick={handleSave} disabled={loading}>
            {loading ? (
              <>
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                Salvando...
              </>
            ) : (
              <>
                <Save className="mr-2 h-4 w-4" />
                Salvar Alterações
              </>
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

src/hooks/use-rich-text.ts.content:
import { useCallback } from 'react';

export const useRichText = () => {
  const applyFormat = useCallback((command: string, value?: string) => {
    document.execCommand(command, false, value);
  }, []);

  const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
    const isMac = navigator.platform.toUpperCase().indexOf('MAC') >= 0;
    const modKey = isMac ? e.metaKey : e.ctrlKey;

    if (modKey) {
      switch (e.key.toLowerCase()) {
        case 'b':
          e.preventDefault();
          applyFormat('bold');
          break;
        case 'i':
          e.preventDefault();
          applyFormat('italic');
          break;
        case 'u':
          e.preventDefault();
          applyFormat('underline');
          break;
        case 'e':
          e.preventDefault();
          applyFormat('strikeThrough');
          break;
        case 'k':
          e.preventDefault();
          const url = prompt('Enter URL:');
          if (url) {
            applyFormat('createLink', url);
          }
          break;
      }
    }

    if (modKey && e.shiftKey && e.key.toLowerCase() === 's') {
      e.preventDefault();
      applyFormat('strikeThrough');
    }
  }, [applyFormat]);

  const toggleFormat = useCallback((format: string) => {
    applyFormat(format);
  }, [applyFormat]);

  return {
    handleKeyDown,
    toggleFormat,
  };
};

src/components/CPFInput.tsx.content:
import { useState } from "react";
import { User, CheckCircle2 } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";

interface CPFInputProps {
  onSubmit: (cpf: string) => void;
  onBack: () => void;
}

export function CPFInput({ onSubmit, onBack }: CPFInputProps) {
  const [cpf, setCpf] = useState("");
  const [isValid, setIsValid] = useState(false);

  const formatCPF = (value: string) => {
    const numbers = value.replace(/\D/g, "");

    if (numbers.length <= 11) {
      const formatted = numbers
        .replace(/(\d{3})(\d)/, "$1.$2")
        .replace(/(\d{3})(\d)/, "$1.$2")
        .replace(/(\d{3})(\d{1,2})/, "$1-$2");

      setCpf(formatted);

      // Validação simples de CPF (11 dígitos)
      setIsValid(numbers.length === 11);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (isValid) {
      onSubmit(cpf.replace(/\D/g, ""));
    }
  };

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-2xl font-semibold mb-2" data-testid="text-title">
          Digite seu CPF
        </h2>
        <p className="text-sm text-muted-foreground">
          Informe o CPF do titular da conta bancária
        </p>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="space-y-2">
          <Label htmlFor="cpf" className="text-sm font-medium">
            CPF
          </Label>
          <div className="relative">
            <User className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
            <Input
              id="cpf"
              type="text"
              placeholder="000.000.000-00"
              value={cpf}
              onChange={(e) => formatCPF(e.target.value)}
              className="pl-10 h-12 text-base"
              autoFocus
              data-testid="input-cpf"
            />
            {isValid && (
              <CheckCircle2 className="absolute right-3 top-1/2 -translate-y-1/2 h-5 w-5 text-chart-2" />
            )}
          </div>
          <p className="text-xs text-muted-foreground">
            Digite apenas números, a formatação é automática
          </p>
        </div>

        <div className="flex gap-3">
          <Button
            type="button"
            variant="outline"
            onClick={onBack}
            className="flex-1 h-12"
            data-testid="button-back"
          >
            Voltar
          </Button>
          <Button
            type="submit"
            disabled={!isValid}
            className="flex-1 h-12"
            data-testid="button-continue"
          >
            Continuar
          </Button>
        </div>
      </form>
    </div>
  );
}

src/features/formularios-platform/utils/.content:
export interface DesignColors {
  background: string;
  secondary: string;
  primary: string;
  text: string;
  button: string;
  buttonText: string;
  progressBar?: string;
}

export interface DesignTypography {
  fontFamily: string;
  titleSize?: string;
  textSize?: string;
  fontSize?: string;
}

export interface DesignConfig {
  colors?: Partial<DesignColors>;
  typography?: Partial<DesignTypography>;
  spacing?: string;
  logo?: string | null;
  logoSize?: number;
  logoAlign?: string;
}

const defaultDesign = {
  colors: {
    primary: "hsl(221, 83%, 53%)",
    secondary: "hsl(210, 40%, 96%)",
    background: "hsl(0, 0%, 100%)",
    text: "hsl(222, 47%, 11%)",
    button: "hsl(221, 83%, 53%)",
    buttonText: "hsl(0, 0%, 100%)",
    progressBar: undefined as string | undefined
  },
  typography: {
    fontFamily: "Inter",
    titleSize: "2xl",
    textSize: "base"
  },
  spacing: "comfortable"
};

export function deriveDesignColors(designConfig: any): {
  colors: DesignColors;
  typography: { fontFamily: string; titleSize: string; textSize: string };
  spacing: string;
  logo?: string | null;
  logoSize?: number;
  logoAlign?: string;
} {
  const baseDesign = (designConfig as DesignConfig) ?? {};
  return {
    colors: { ...defaultDesign.colors, ...(baseDesign.colors || {}) },
    typography: { 
      ...defaultDesign.typography, 
      ...(baseDesign.typography || {}) 
    } as { fontFamily: string; titleSize: string; textSize: string },
    spacing: baseDesign.spacing || defaultDesign.spacing,
    logo: baseDesign.logo,
    logoSize: baseDesign.logoSize,
    logoAlign: baseDesign.logoAlign
  };
}

src/components/notion/BlockWrapper.tsx.content:
import { ReactNode, useRef, useState } from 'react';
import { useNotionStore, type StoreBlock } from '@/stores/notionStore';
import { Button } from '@/components/ui/button';
import { GripVertical, Plus } from 'lucide-react';
import { BlockActionsMenu } from './BlockActionsMenu';
import { 
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { cn } from '@/lib/utils';

interface BlockWrapperProps {
  blockId: string;
  index: number;
  children: ReactNode;
  className?: string;
}

export const BlockWrapper = ({ blockId, index, children, className }: BlockWrapperProps) => {
  const { updateBlock, reorderBlocks, getCurrentPage, pages } = useNotionStore();
  const blockRef = useRef<HTMLDivElement>(null);
  const [showActions, setShowActions] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [isDragOver, setIsDragOver] = useState(false);
  const [showMenu, setShowMenu] = useState(false);
  const [menuPosition, setMenuPosition] = useState({ x: 0, y: 0 });
  const currentPage = getCurrentPage();
  const isLocked = currentPage?.locked || false;

  // Get current block data
  const currentBlock = currentPage?.blocks?.find(b => b.id === blockId) as StoreBlock | undefined;

  const handleDragStart = (e: React.DragEvent) => {
    if (isLocked) return;
    e.dataTransfer.effectAllowed = 'move';
    e.dataTransfer.setData('text/plain', index.toString());
    setIsDragging(true);
  };

  const handleDragEnd = () => {
    if (isLocked) return;
    setIsDragging(false);
  };

  const handleDragOver = (e: React.DragEvent) => {
    if (isLocked) return;
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    setIsDragOver(true);
  };

  const handleDragLeave = () => {
    if (isLocked) return;
    setIsDragOver(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    if (isLocked) return;
    e.preventDefault();
    setIsDragOver(false);

    const draggedIndex = parseInt(e.dataTransfer.getData('text/plain'));
    if (draggedIndex !== index) {
      reorderBlocks(draggedIndex, index);
    }
  };

  const handleAddBlockClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    const button = e.currentTarget;
    const rect = button.getBoundingClientRect();
    setMenuPosition({ 
      x: rect.right + 8, 
      y: rect.top 
    });
    setShowMenu(true);
  };

  const handleChangeType = (type: string) => {
    updateBlock(blockId, { type: type as any, content: currentBlock?.content || '' });
  };

  const handleChangeTextColor = (color: string) => {
    updateBlock(blockId, { textColor: color });
  };

  const handleChangeBackgroundColor = (color: string) => {
    updateBlock(blockId, { backgroundColor: color });
  };

  return (
    <div
      ref={blockRef}
      draggable={!isLocked}
      onDragStart={handleDragStart}
      onDragEnd={handleDragEnd}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
      className={cn(
        "relative group transition-all",
        isDragging && "opacity-50",
        isDragOver && "border-t-2 border-blue-500",
        className
      )}
      onMouseEnter={() => setShowActions(true)}
      onMouseLeave={() => setShowActions(false)}
    >
      {!isLocked && (
        <div className={cn(
          'absolute left-0 top-1 -translate-x-full flex items-center gap-1 pr-1 opacity-0 group-hover:opacity-100 transition-opacity',
          showActions && 'opacity-100'
        )}>
          <Tooltip>
            <TooltipTrigger asChild>
              <Button
                variant="ghost"
                size="sm"
                className="h-5 w-5 p-0 cursor-grab active:cursor-grabbing"
                data-testid={`drag-handle-${blockId}`}
              >
                <GripVertical className="h-3.5 w-3.5 text-muted-foreground" />
              </Button>
            </TooltipTrigger>
            <TooltipContent side="left">
              <p className="text-xs">Arraste para mover</p>
            </TooltipContent>
          </Tooltip>
          <Tooltip>
            <TooltipTrigger asChild>
              <Button
                variant="ghost"
                size="sm"
                className="h-5 w-5 p-0"
                onClick={handleAddBlockClick}
                data-testid={`add-block-after-${blockId}`}
              >
                <Plus className="h-3.5 w-3.5 text-muted-foreground" />
              </Button>
            </TooltipTrigger>
            <TooltipContent side="left">
              <p className="text-xs">Adicionar bloco</p>
            </TooltipContent>
          </Tooltip>
        </div>
      )}

      {children}

      {showMenu && !isLocked && (
        <BlockActionsMenu
          position={menuPosition}
          onChangeType={handleChangeType}
          onChangeTextColor={handleChangeTextColor}
          onChangeBackgroundColor={handleChangeBackgroundColor}
          onClose={() => setShowMenu(false)}
          currentType={currentBlock?.type}
          currentTextColor={currentBlock?.textColor}
          currentBackgroundColor={currentBlock?.backgroundColor}
        />
      )}
    </div>
  );
};

