            {lead.ultimaMensagem && (
              <div className="py-1.5 border-t border-zinc-700">
                <div className="text-xs text-zinc-500 italic truncate">
                  "{truncateText(lead.ultimaMensagem, 60)}"
                </div>
              </div>
            )}
          </div>
        </Card>
      </DialogTrigger>
      <LeadDetailDialog lead={lead} />
    </Dialog>
  );
}

