}

export interface BigdatacorpProcessesResponse {
  Result: Array<{
    MatchKeys: string;
    Processes: {
      Lawsuits: BigdatacorpLawsuit[];
      TotalLawsuits: number;
      TotalLawsuitsAsAuthor: number;
      TotalLawsuitsAsDefendant: number;
