                <Alert>
                  <AlertDescription>
                    <p className="font-semibold mb-2">🔑 Código de Pareamento:</p>
                    <p className="text-2xl font-mono font-bold text-center py-4 bg-muted rounded-lg">
                      {pairingCode}
