export { Checkbox };

import { useState } from "react";
import { Question, QuestionOption } from "../types/form";
import { Button } from "./ui/button";
import { Input } from "./ui/input";
import { Card } from "./ui/card";
import { Trash2, Plus, GripVertical } from "lucide-react";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "./ui/select";

interface QuestionEditorProps {
  question: Question;
  onUpdate: (question: Question) => void;
  onDelete: () => void;
  index: number;
  dragHandleProps?: any;
}

export const QuestionEditor = ({ question, onUpdate, onDelete, index, dragHandleProps }: QuestionEditorProps) => {
  const [text, setText] = useState(question.text);

  const handleTextChange = (value: string) => {
    setText(value);
    onUpdate({ ...question, text: value });
  };

  const handleTypeChange = (type: 'multiple-choice' | 'text') => {
    const updatedQuestion: Question = {
      ...question,
      type,
      options: type === 'multiple-choice' ? (question.options || [
        { id: '1', text: '', points: 0 },
        { id: '2', text: '', points: 0 }
      ]) : undefined,
      points: type === 'text' ? (question.points || 0) : undefined
    };
    onUpdate(updatedQuestion);
  };

  const addOption = () => {
    if (question.type === 'multiple-choice') {
      const newOptions = [
        ...(question.options || []),
        { id: Date.now().toString(), text: '', points: 0 }
      ];
      onUpdate({ ...question, options: newOptions });
    }
  };

  const updateOption = (optionId: string, field: keyof QuestionOption, value: string | number) => {
    if (question.options) {
      const newOptions = question.options.map(opt =>
        opt.id === optionId ? { ...opt, [field]: value } : opt
      );
      onUpdate({ ...question, options: newOptions });
    }
  };

  const deleteOption = (optionId: string) => {
    if (question.options) {
      const newOptions = question.options.filter(opt => opt.id !== optionId);
      onUpdate({ ...question, options: newOptions });
    }
  };

  return (
    <Card className="p-6 bg-card border-border shadow-[var(--shadow-luxury)] transition-all duration-300 hover:shadow-[var(--shadow-glow)]">
      <div className="flex items-start gap-4">
        <div className="mt-2 cursor-move" {...dragHandleProps}>
          <GripVertical className="h-5 w-5 text-muted-foreground" />
        </div>

        <div className="flex-1 space-y-4">
          <div className="flex items-center gap-3">
            <span className="font-semibold text-primary bg-primary/10 px-3 py-1 rounded-full text-sm">
              #{index + 1}
            </span>
            <Input
              value={text}
              onChange={(e) => handleTextChange(e.target.value)}
              placeholder="Digite sua pergunta..."
              className="flex-1 font-medium bg-background border-border"
            />
          </div>

          <div className="flex gap-3">
            <Select value={question.type} onValueChange={handleTypeChange}>
              <SelectTrigger className="w-[200px] bg-background border-border">
                <SelectValue />
              </SelectTrigger>
              <SelectContent className="bg-popover border-border z-50">
                <SelectItem value="multiple-choice">Múltipla Escolha</SelectItem>
                <SelectItem value="text">Resposta Livre</SelectItem>
              </SelectContent>
            </Select>

            {question.type === 'text' && (
              <div className="flex items-center gap-2">
                <span className="text-sm text-muted-foreground">Pontos:</span>
                <Input
                  type="number"
                  value={question.points || 0}
                  onChange={(e) => onUpdate({ ...question, points: parseInt(e.target.value) || 0 })}
                  className="w-20 bg-background border-border"
                />
              </div>
            )}
          </div>

          {question.type === 'multiple-choice' && (
            <div className="space-y-3 pl-4 border-l-2 border-primary/20">
              {question.options?.map((option) => (
                <div key={option.id} className="flex items-center gap-2">
                  <Input
                    value={option.text}
                    onChange={(e) => updateOption(option.id, 'text', e.target.value)}
                    placeholder="Texto da opção"
                    className="flex-1 bg-background border-border"
                  />
                  <Input
                    type="number"
                    value={option.points}
                    onChange={(e) => updateOption(option.id, 'points', parseInt(e.target.value) || 0)}
                    placeholder="Pts"
                    className="w-20 bg-background border-border"
                  />
                  <Button
                    variant="ghost"
                    size="icon"
                    onClick={() => deleteOption(option.id)}
                    className="text-destructive hover:text-destructive hover:bg-destructive/10"
                  >
                    <Trash2 className="h-4 w-4" />
                  </Button>
                </div>
              ))}
              <Button
                variant="outline"
                size="sm"
                onClick={addOption}
                className="gap-1 border-border"
              >
                <Plus className="h-4 w-4" />
                Adicionar Opção
              </Button>
            </div>
          )}
        </div>

        <Button
          variant="ghost"
          size="icon"
          onClick={onDelete}
          className="text-destructive hover:text-destructive hover:bg-destructive/10"
        >
          <Trash2 className="h-4 w-4" />
        </Button>
      </div>
    </Card>
  );
};

import { Badge } from "./ui/badge";
import { CheckCircle2, XCircle, Clock, Eye, Send, FileText } from "lucide-react";
import { cn } from "../lib/utils";

interface LeadStatusBadgeProps {
  lead: {
    formularioEnviado?: boolean;
    formularioAberto?: boolean;
    formularioIniciado?: boolean;
    formularioConcluido?: boolean;
    statusQualificacao?: string;
    pontuacao?: number;
  };
  progressoPercentual?: number;
  className?: string;
}

export function LeadStatusBadge({ lead, progressoPercentual = 0, className }: LeadStatusBadgeProps) {
  const getStatusInfo = () => {
    if (lead.formularioConcluido && lead.statusQualificacao === 'aprovado') {
      return {
        variant: 'approved' as const,
        icon: CheckCircle2,
        text: `APROVADO (${lead.pontuacao || 0} pts)`,
        className: 'bg-green-100 text-green-800 border-green-200 hover:bg-green-100'
      };
    }

    if (lead.formularioConcluido && lead.statusQualificacao === 'reprovado') {
      return {
        variant: 'rejected' as const,
        icon: XCircle,
        text: `Reprovado (${lead.pontuacao || 0} pts)`,
        className: 'bg-red-100 text-red-800 border-red-200 hover:bg-red-100'
      };
    }

    if (lead.formularioIniciado) {
      return {
        variant: 'in_progress' as const,
        icon: Clock,
        text: `Em andamento (${progressoPercentual}%)`,
        className: 'bg-yellow-100 text-yellow-800 border-yellow-200 hover:bg-yellow-100'
      };
    }

    if (lead.formularioAberto) {
      return {
        variant: 'viewed' as const,
        icon: Eye,
        text: 'Visualizou',
        className: 'bg-blue-100 text-blue-800 border-blue-200 hover:bg-blue-100'
      };
    }

    if (lead.formularioEnviado) {
      return {
        variant: 'sent' as const,
        icon: Send,
        text: 'Enviado (não visualizado)',
        className: 'bg-gray-100 text-gray-800 border-gray-200 hover:bg-gray-100'
      };
    }

    return {
      variant: 'no_form' as const,
      icon: FileText,
      text: 'Sem formulário',
      className: 'bg-gray-50 text-gray-600 border-gray-100 hover:bg-gray-50'
    };
  };

  const status = getStatusInfo();
  const Icon = status.icon;

  return (
    <Badge 
      variant="outline" 
      className={cn(
        'inline-flex items-center gap-1.5 px-2.5 py-0.5 text-xs font-semibold',
        status.className,
        className
      )}
    >
      <Icon className="h-3.5 w-3.5" />
      {status.text}
    </Badge>
  );
}

