import { useState, useEffect } from 'react';

interface BeforeInstallPromptEvent extends Event {
  prompt: () => Promise<void>;
  userChoice: Promise<{ outcome: 'accepted' | 'dismissed' }>;
}

export interface DeviceInfo {
  isIOS: boolean;
  isAndroid: boolean;
  isMobile: boolean;
  isTablet: boolean;
  isDesktop: boolean;
  isSafari: boolean;
  isChrome: boolean;
  isStandalone: boolean;
  platform: 'ios' | 'android' | 'desktop';
  browser: 'safari' | 'chrome' | 'firefox' | 'edge' | 'other';
}

export function detectDevice(): DeviceInfo {
  const ua = navigator.userAgent.toLowerCase();
  const isIOS = /iphone|ipad|ipod/.test(ua);
  const isAndroid = /android/.test(ua);
  const isSafari = /safari/.test(ua) && !/chrome/.test(ua);
  const isChrome = /chrome/.test(ua) || /chromium/.test(ua);

  // Detectar standalone mode - iOS usa navigator.standalone, outros usam matchMedia
  let isStandalone = false;
  try {
    // iOS Safari
    if ('standalone' in navigator) {
      isStandalone = (navigator as any).standalone === true;
    }
    // Outros browsers
    if (!isStandalone && window.matchMedia) {
      isStandalone = window.matchMedia('(display-mode: standalone)').matches;
    }
  } catch (e) {
    console.warn('[PWA] Erro ao detectar standalone mode:', e);
  }

  // Detectar se é mobile ou tablet
  const isMobileUA = /mobile/.test(ua);
  const isTabletUA = /tablet|ipad/.test(ua);
  const isMobile = (isIOS || isAndroid) && !isTabletUA;
  const isTablet = isTabletUA || (isAndroid && !isMobileUA);
  const isDesktop = !isMobile && !isTablet;

  // Detectar browser
  let browser: 'safari' | 'chrome' | 'firefox' | 'edge' | 'other' = 'other';
  if (isSafari) browser = 'safari';
  else if (/edg/.test(ua)) browser = 'edge';
  else if (isChrome) browser = 'chrome';
  else if (/firefox/.test(ua)) browser = 'firefox';

  // Determinar plataforma principal
  let platform: 'ios' | 'android' | 'desktop' = 'desktop';
  if (isIOS) platform = 'ios';
  else if (isAndroid) platform = 'android';

  return {
    isIOS,
    isAndroid,
    isMobile,
    isTablet,
    isDesktop,
    isSafari,
    isChrome,
    isStandalone,
    platform,
    browser,
  };
}

export function usePWAInstall() {
  const [deferredPrompt, setDeferredPrompt] = useState<BeforeInstallPromptEvent | null>(null);
  const [deviceInfo] = useState<DeviceInfo>(detectDevice());
  const [isInstalled, setIsInstalled] = useState(() => deviceInfo.isStandalone);
  const [canInstall, setCanInstall] = useState(false);

  useEffect(() => {
    // Verificar standalone mode novamente (importante para iOS)
    let currentlyStandalone = false;
    try {
      // iOS Safari usa navigator.standalone
      if ('standalone' in navigator) {
        currentlyStandalone = (navigator as any).standalone === true;
      }
      // Outros browsers usam matchMedia
      if (!currentlyStandalone && window.matchMedia) {
        currentlyStandalone = window.matchMedia('(display-mode: standalone)').matches;
      }
    } catch (e) {
      console.warn('[PWA] Erro ao verificar standalone mode no effect:', e);
    }

    // Se está em standalone mode, marcar como instalado
    if (currentlyStandalone) {
      console.log('✅ [PWA] App detectado em modo standalone - marcando como instalado');
      setIsInstalled(true);
      setCanInstall(false);
      return;
    }

    // Se já foi marcado como instalado anteriormente, não fazer nada
    if (isInstalled) {
      console.log('✅ [PWA] App já instalado - modo standalone detectado');
      return;
    }

    console.log('📱 [PWA] Device Info:', {
      platform: deviceInfo.platform,
      browser: deviceInfo.browser,
      isMobile: deviceInfo.isMobile,
      isTablet: deviceInfo.isTablet,
      isStandalone: deviceInfo.isStandalone,
    });

    // Registrar Service Worker
    if ('serviceWorker' in navigator) {
      navigator.serviceWorker
        .register('/service-worker.js', { scope: '/' })
        .then((registration) => {
          console.log('✅ [PWA] Service Worker registrado:', registration.scope);
          // Verificar se há update
          registration.update();
        })
        .catch((error) => {
          console.error('❌ [PWA] Erro ao registrar Service Worker:', error);
        });
    }

    // Listener para beforeinstallprompt (Chrome/Edge/Android)
    const handleBeforeInstallPrompt = (e: Event) => {
      console.log('🎯 [PWA] beforeinstallprompt recebido - instalação automática disponível!');
      e.preventDefault();
      const promptEvent = e as BeforeInstallPromptEvent;
      setDeferredPrompt(promptEvent);
      // Salvar também no window global para acesso posterior (importante para iframes)
      (window as any).deferredPrompt = promptEvent;
      setCanInstall(true);
    };

    // Listener para quando o app é instalado
    const handleAppInstalled = () => {
      console.log('🎉 [PWA] App instalado com sucesso!');
      setIsInstalled(true);
      setDeferredPrompt(null);
      setCanInstall(false);
    };

    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    window.addEventListener('appinstalled', handleAppInstalled);

    // Para iOS Safari, o botão sempre pode ser mostrado (instalação manual)
    if (deviceInfo.isIOS && deviceInfo.isSafari && !deviceInfo.isStandalone) {
      console.log('📱 [PWA] iOS Safari detectado - instalação manual disponível');
      setCanInstall(true);
    }

    // Para Android não-Chrome, também permitir mostrar instruções
    if (deviceInfo.isAndroid && !deviceInfo.isChrome && !deviceInfo.isStandalone) {
      console.log('📱 [PWA] Android detectado - instalação manual disponível');
      setCanInstall(true);
    }

    // MODO TESTE: Sempre mostrar botão em desenvolvimento para testar UI
    // Detectar se está em ambiente Replit/iframe ou localhost
    const isDevelopment = window.location.hostname.includes('replit') || 
                         window.location.hostname.includes('localhost') ||
                         window.location.hostname.includes('127.0.0.1') ||
                         window.self !== window.top;

    if (isDevelopment && !deviceInfo.isStandalone) {
      console.log('🧪 [PWA] Modo desenvolvimento detectado - botão sempre visível para testes');
      setCanInstall(true);
    }

    return () => {
      window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
      window.removeEventListener('appinstalled', handleAppInstalled);
    };
  }, [isInstalled, deviceInfo]);

  const install = async (): Promise<'success' | 'dismissed' | 'manual' | 'error'> => {
    // Se tem prompt automático (Chrome/Edge/Android Chrome)
    if (deferredPrompt) {
      try {
        console.log('🚀 [PWA] Iniciando instalação automática com deferredPrompt...');
        await deferredPrompt.prompt();
        const choiceResult = await deferredPrompt.userChoice;

        if (choiceResult.outcome === 'accepted') {
          console.log('✅ [PWA] Usuário aceitou instalar');
          setDeferredPrompt(null);
          return 'success';
        } else {
          console.log('ℹ️ [PWA] Usuário recusou a instalação');
          return 'dismissed';
        }
      } catch (error) {
        console.error('❌ [PWA] Erro ao instalar:', error);
        return 'error';
      }
    }

    // Para Android Chrome em iframes (Replit), tentar forçar a instalação
    if (deviceInfo.isAndroid && deviceInfo.isChrome) {
      console.log('🔧 [PWA] Android Chrome detectado - tentando instalação alternativa...');

      // Tentar usar o evento global se existir
      const globalPrompt = (window as any).deferredPrompt;
      if (globalPrompt) {
        try {
          console.log('🚀 [PWA] Usando prompt global...');
          await globalPrompt.prompt();
          const choiceResult = await globalPrompt.userChoice;

          if (choiceResult.outcome === 'accepted') {
            console.log('✅ [PWA] Usuário aceitou instalar (via prompt global)');
            return 'success';
          } else {
            console.log('ℹ️ [PWA] Usuário recusou a instalação');
            return 'dismissed';
          }
        } catch (error) {
          console.error('❌ [PWA] Erro ao instalar via prompt global:', error);
        }
      }

      // Se não conseguiu instalar automaticamente, mostrar instruções específicas do Chrome
      console.log('ℹ️ [PWA] Instalação automática não disponível - mostrar instruções do Chrome');
      return 'manual';
    }

    // Para iOS e outros casos, retornar 'manual' para mostrar instruções
    console.log('ℹ️ [PWA] Instalação automática não disponível - mostrar instruções');
    return 'manual';
  };

  return {
    install,
    canInstall: canInstall && !isInstalled,
    isInstalled,
    deferredPrompt,
    deviceInfo,
  };
}

src/features/formularios-platform/types/.content:
// ============================================================================
// BASE TYPES - Shared across all element types
// ============================================================================

export interface ElementStyleConfig {
  alignment?: 'left' | 'center' | 'right';
  fontSize?: 'xs' | 'sm' | 'base' | 'lg' | 'xl' | '2xl' | '3xl' | '4xl';
  fontWeight?: 'normal' | 'medium' | 'semibold' | 'bold';
  italic?: boolean;
  underline?: boolean;
  strikethrough?: boolean;
  textColor?: string;
  backgroundColor?: string;
  padding?: 'none' | 'sm' | 'md' | 'lg';
  margin?: 'none' | 'sm' | 'md' | 'lg';
}

// ============================================================================
// FORM ELEMENTS - Union type for Canva-style builder
// ============================================================================

export interface QuestionOption {
  id: string;
  text: string;
  points: number;
}

// Question Element (scoring)
export interface QuestionElement {
  type: 'question';
  id: string;
  text: string;
  questionType: 'multiple-choice' | 'text';
  options?: QuestionOption[];
  points?: number;
  required?: boolean;
  style?: ElementStyleConfig;
  elementTypeVersion?: number;
}

// Heading Element (título)
export interface HeadingElement {
  type: 'heading';
  id: string;
  text: string;
  level: 1 | 2 | 3; // h1, h2, h3
  style?: ElementStyleConfig;
  elementTypeVersion?: number;
}

// Text Block Element (parágrafo/texto rico)
export interface TextElement {
  type: 'text';
  id: string;
  content: string;
  style?: ElementStyleConfig;
  elementTypeVersion?: number;
}

// Page Break Element (divisor de página)
export interface PageBreakElement {
  type: 'pageBreak';
  id: string;
  label?: string;
  showLine?: boolean;
  style?: ElementStyleConfig;
  elementTypeVersion?: number;
}

// Union type for all form elements
export type FormElement = QuestionElement | HeadingElement | TextElement | PageBreakElement;

// Type guards for element discrimination
export function isQuestionElement(element: FormElement): element is QuestionElement {
  return element.type === 'question';
}

export function isHeadingElement(element: FormElement): element is HeadingElement {
  return element.type === 'heading';
}

export function isTextElement(element: FormElement): element is TextElement {
  return element.type === 'text';
}

export function isPageBreakElement(element: FormElement): element is PageBreakElement {
  return element.type === 'pageBreak';
}

// ============================================================================
// LEGACY SUPPORT - Backward compatibility with old Question type
// ============================================================================

export interface Question {
  id: string;
  text: string;
  type: 'multiple-choice' | 'text';
  options?: QuestionOption[];
  points?: number;
}

// Convert legacy Question to QuestionElement
export function questionToElement(question: Question): QuestionElement {
  return {
    type: 'question',
    id: question.id,
    text: question.text,
    questionType: question.type,
    options: question.options,
    points: question.points,
    elementTypeVersion: 1
  };
}

// Convert QuestionElement back to legacy Question (for API compatibility)
export function elementToQuestion(element: QuestionElement): Question {
  return {
    id: element.id,
    text: element.text,
    type: element.questionType,
    options: element.options,
    points: element.points
  };
}

// ============================================================================
// FORM CONFIG
// ============================================================================

export interface DesignConfig {
  colors: {
    primary: string;
    secondary: string;
    background: string;
    text: string;
    button: string;
    buttonText: string;
    progressBar?: string;
  };
  typography: {
    fontFamily: string;
    titleSize: string;
    textSize: string;
  };
  logo?: string | null;
  logoAlign?: 'left' | 'center' | 'right';
  logoSize?: number; // Logo size in pixels (default: 64)
  extractedColors?: string[]; // Colors extracted from logo
  spacing: 'compact' | 'comfortable' | 'spacious';
}

export interface WelcomePageConfig {
  title: string;
  description: string;
  buttonText?: string;
  logo?: string | null;
  titleSize?: 'xs' | 'sm' | 'base' | 'lg' | 'xl' | '2xl' | '3xl' | '4xl';
  extendedDescription?: string;
  logoAlign?: 'left' | 'center' | 'right';
}

export interface CompletionPageConfig {
  title: string;
  subtitle?: string;
  successMessage: string;
  failureMessage: string;
  showScore: boolean;
  showTierBadge: boolean;
  ctaText?: string;
  ctaUrl?: string;
  customContent?: string;
  additionalThankYouText?: string;
  design?: {
    colors: {
      primary: string;
      secondary: string;
      background: string;
      text: string;
      successIcon: string;
      failureIcon: string;
    };
    typography: {
      fontFamily: string;
      titleSize: string;
      textSize: string;
    };
    logo?: string | null;
    logoAlign?: 'left' | 'center' | 'right';
    spacing: 'compact' | 'comfortable' | 'spacious';
  };
}

export interface ScoreTier {
  id: string;
  label: string;
  minScore: number;
  maxScore: number;
  description: string;
  qualifies: boolean;
}

export interface FormConfig {
  title: string;
  description: string;
  elements: FormElement[]; // NEW: Unified elements array
  questions?: Question[]; // LEGACY: Keep for backward compatibility
  passingScore: number;
  scoreTiers?: ScoreTier[];
  designConfig?: DesignConfig;
  welcomePageConfig?: WelcomePageConfig;
  completionPageConfig?: CompletionPageConfig;
}

export interface FormAnswer {
  questionId: string;
  answer: string;
  points: number;
}

export interface FormSubmission {
  answers: FormAnswer[];
  totalScore: number;
  passed: boolean;
}

export interface FormTemplate {
  id: string;
  name: string;
  description?: string;
  thumbnailUrl?: string;
  designConfig: DesignConfig;
  elements: FormElement[]; // NEW: Use elements
  questions?: Question[]; // LEGACY: Keep for backward compatibility
  isDefault?: boolean;
}

// ============================================================================
// HELPER FUNCTIONS - Migration and conversion utilities
// ============================================================================

// Convert legacy questions array to elements array
export function migrateQuestionsToElements(questions: Question[]): FormElement[] {
  return questions.map(questionToElement);
}

// Extract only question elements from mixed elements
export function extractQuestions(elements: FormElement[]): Question[] {
  return elements
    .filter(isQuestionElement)
    .map(elementToQuestion);
}

// Calculate total possible score from elements
export function calculateMaxScore(elements: FormElement[]): number {
  return elements
    .filter(isQuestionElement)
    .reduce((total, element) => {
      if (element.questionType === 'multiple-choice' && element.options) {
        const maxOptionPoints = Math.max(...element.options.map(opt => opt.points), 0);
        return total + maxOptionPoints;
      }
      return total + (element.points || 0);
    }, 0);
}

// ============================================================================
// PAGE GROUPING - Accordion/collapsible pages functionality
// ============================================================================

export interface Page {
  id: string;
  label: string;
  elements: FormElement[];
  elementCount: number;
}

// Group elements into pages based on pageBreak elements
export function groupElementsIntoPages(elements: FormElement[] | undefined | null): Page[] {
  const pages: Page[] = [];
  let currentPageElements: FormElement[] = [];
  let pageIndex = 0;

  // Defensive check: if elements is undefined, null, or not an array, return single empty page
  if (!elements || !Array.isArray(elements)) {
    return [{
      id: 'page-0',
      label: 'Página 1',
      elements: [],
      elementCount: 0
    }];
  }

  elements.forEach((element) => {
    if (isPageBreakElement(element)) {
      // Save current page if it has elements
      if (currentPageElements.length > 0) {
        const pageId = `page-${pageIndex}`;
        const label = `Página ${pageIndex + 1}`;
        pages.push({
          id: pageId,
          label,
          elements: currentPageElements,
          elementCount: currentPageElements.length
        });
        pageIndex++;
        currentPageElements = [];
      }
      // Skip consecutive page breaks
    } else {
      currentPageElements.push(element);
    }
  });

  // Add remaining elements as last page
  if (currentPageElements.length > 0) {
    const pageId = `page-${pageIndex}`;
    const label = `Página ${pageIndex + 1}`;
    pages.push({
      id: pageId,
      label,
      elements: currentPageElements,
      elementCount: currentPageElements.length
    });
  }

  // If no pages were created (no elements), return single empty page
  if (pages.length === 0) {
    pages.push({
      id: 'page-0',
      label: 'Página 1',
      elements: [],
      elementCount: 0
    });
  }

  return pages;
}

// Flatten pages back into a single elements array with pageBreaks between them
export function flattenPagesToElements(pages: Page[]): FormElement[] {
  const elements: FormElement[] = [];

  pages.forEach((page, index) => {
    // Add page elements
    elements.push(...page.elements);

    // Add page break after each page except the last one
    if (index < pages.length - 1) {
      elements.push({
        type: 'pageBreak',
        id: `pagebreak-${Date.now()}-${index}`,
        label: `Página ${index + 2}`,
        showLine: true,
        elementTypeVersion: 1
      });
    }
  });

  return elements;
}

// Get the page that contains a specific element
export function getPageForElement(elementId: string, pages: Page[]): Page | null {
  for (const page of pages) {
    if (page.elements.some(el => el.id === elementId)) {
      return page;
    }
  }
  return null;
}

