import { useState } from "react";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Button } from "@/components/ui/button";
import { Filter, X } from "lucide-react";
import { translateCategory } from "@/lib/translations";

export interface TransactionFilterParams {
  searchText: string;
  dateFrom: string;
  dateTo: string;
  type: string; // "all" | "DEBIT" | "CREDIT"
  category: string;
}

interface TransactionFiltersProps {
  onFilterChange: (filters: TransactionFilterParams) => void;
  availableCategories: string[];
}

export default function TransactionFilters({ onFilterChange, availableCategories }: TransactionFiltersProps) {
  const [filters, setFilters] = useState<TransactionFilterParams>({
    searchText: "",
    dateFrom: "",
    dateTo: "",
    type: "all",
    category: "all",
  });

  const handleFilterChange = (key: keyof TransactionFilterParams, value: string) => {
    const newFilters = { ...filters, [key]: value };
    setFilters(newFilters);
    onFilterChange(newFilters);
  };

  const clearFilters = () => {
    const clearedFilters: TransactionFilterParams = {
      searchText: "",
      dateFrom: "",
      dateTo: "",
      type: "all",
      category: "all",
    };
    setFilters(clearedFilters);
    onFilterChange(clearedFilters);
  };

  const hasActiveFilters = 
    filters.searchText !== "" || 
    filters.dateFrom !== "" || 
    filters.dateTo !== "" || 
    filters.type !== "all" || 
    filters.category !== "all";

  return (
    <Card className="p-6 mb-6">
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Filter className="h-5 w-5 text-primary" />
            <h3 className="text-lg font-semibold">Filtros de Transações</h3>
          </div>
          {hasActiveFilters && (
            <Button 
              variant="outline" 
              size="sm" 
              onClick={clearFilters}
              className="gap-2"
            >
              <X className="h-4 w-4" />
              Limpar Filtros
            </Button>
          )}
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {/* Busca por Nome/Descrição */}
          <div className="space-y-2">
            <Label htmlFor="search">Buscar por Nome/Descrição</Label>
            <Input
              id="search"
              placeholder="Ex: Mercadolivre, Pagamento..."
              value={filters.searchText}
              onChange={(e) => handleFilterChange("searchText", e.target.value)}
            />
          </div>

          {/* Data Inicial */}
          <div className="space-y-2">
            <Label htmlFor="dateFrom">Data Inicial</Label>
            <Input
              id="dateFrom"
              type="date"
              value={filters.dateFrom}
              onChange={(e) => handleFilterChange("dateFrom", e.target.value)}
            />
          </div>

          {/* Data Final */}
          <div className="space-y-2">
            <Label htmlFor="dateTo">Data Final</Label>
            <Input
              id="dateTo"
              type="date"
              value={filters.dateTo}
              onChange={(e) => handleFilterChange("dateTo", e.target.value)}
            />
          </div>

          {/* Tipo (Débito/Crédito) */}
          <div className="space-y-2">
            <Label htmlFor="type">Tipo</Label>
            <Select
              value={filters.type}
              onValueChange={(value) => handleFilterChange("type", value)}
            >
              <SelectTrigger id="type">
                <SelectValue placeholder="Todos" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Todos</SelectItem>
                <SelectItem value="DEBIT">Débito</SelectItem>
                <SelectItem value="CREDIT">Crédito</SelectItem>
              </SelectContent>
            </Select>
          </div>

          {/* Categoria */}
          <div className="space-y-2">
            <Label htmlFor="category">Categoria</Label>
            <Select
              value={filters.category}
              onValueChange={(value) => handleFilterChange("category", value)}
            >
              <SelectTrigger id="category">
                <SelectValue placeholder="Todas" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Todas</SelectItem>
                {availableCategories.map((category) => (
                  <SelectItem key={category} value={category}>
                    {translateCategory(category)}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        </div>
      </div>
    </Card>
  );
}

src/components/notion/views/ChartView.ts.content:
import { useState } from 'react';
import type { ChartType } from '@/types/notion';
import type { StoreDatabase } from '@/stores/notionStore';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { BarChart3, LineChart, PieChart, AreaChart } from 'lucide-react';
import { BarChart, Bar, LineChart as RechartsLineChart, Line, PieChart as RechartsPieChart, Pie, AreaChart as RechartsAreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, Cell } from 'recharts';

interface ChartViewProps {
  database: StoreDatabase;
  onUpdate: (updates: Partial<StoreDatabase>) => void;
  isLocked: boolean;
}

const COLORS = ['#8884d8', '#82ca9d', '#ffc658', '#ff8042', '#0088fe', '#00c49f', '#ffbb28', '#ff6b6b'];

export const ChartView = ({ database, onUpdate, isLocked }: ChartViewProps) => {
  const [chartType, setChartType] = useState<ChartType>(database.chartType || 'bar');
  const [xAxisField, setXAxisField] = useState(database.chartXAxis || database.fields[0]?.id || '');
  const [yAxisField, setYAxisField] = useState(database.chartYAxis || database.fields.find(f => f.type === 'number')?.id || database.fields[1]?.id || '');

  const chartTypes: { type: ChartType; icon: any; label: string }[] = [
    { type: 'bar', icon: BarChart3, label: 'Barras' },
    { type: 'line', icon: LineChart, label: 'Linha' },
    { type: 'pie', icon: PieChart, label: 'Pizza' },
    { type: 'area', icon: AreaChart, label: 'Área' },
    { type: 'donut', icon: PieChart, label: 'Rosca' },
  ];

  const handleChartTypeChange = (type: ChartType) => {
    setChartType(type);
    onUpdate({ chartType: type });
  };

  const handleXAxisChange = (fieldId: string) => {
    setXAxisField(fieldId);
    onUpdate({ chartXAxis: fieldId });
  };

  const handleYAxisChange = (fieldId: string) => {
    setYAxisField(fieldId);
    onUpdate({ chartYAxis: fieldId });
  };

  const getChartData = () => {
    const xField = database.fields.find(f => f.id === xAxisField);
    const yField = database.fields.find(f => f.id === yAxisField);

    if (!xField || !yField) return [];

    return (database.rows || []).map(row => ({
      name: String(row.values[xAxisField] || 'Sem nome'),
      value: Number(row.values[yAxisField]) || 0,
      fullData: row.values,
    }));
  };

  const chartData = getChartData();
  const hasData = chartData.length > 0 && chartData.some(d => d.value !== 0);

  if (database.fields.length === 0) {
    return (
      <div className="p-8 text-center text-muted-foreground">
        Adicione campos ao database para criar gráficos
      </div>
    );
  }

  const renderChart = () => {
    if (!hasData) {
      return (
        <div className="flex items-center justify-center h-96 text-muted-foreground">
          <div className="text-center">
            <BarChart3 className="h-16 w-16 mx-auto mb-4 opacity-50" />
            <p>Nenhum dado disponível para visualizar</p>
            <p className="text-sm mt-2">Adicione linhas com valores numéricos ao database</p>
          </div>
        </div>
      );
    }

    switch (chartType) {
      case 'bar':
        return (
          <ResponsiveContainer width="100%" height={400}>
            <BarChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="name" />
              <YAxis />
              <Tooltip />
              <Legend />
              <Bar dataKey="value" fill="#8884d8" name={database.fields.find(f => f.id === yAxisField)?.name || 'Valor'} />
            </BarChart>
          </ResponsiveContainer>
        );

      case 'line':
        return (
          <ResponsiveContainer width="100%" height={400}>
            <RechartsLineChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="name" />
              <YAxis />
              <Tooltip />
              <Legend />
              <Line type="monotone" dataKey="value" stroke="#8884d8" name={database.fields.find(f => f.id === yAxisField)?.name || 'Valor'} />
            </RechartsLineChart>
          </ResponsiveContainer>
        );

      case 'area':
        return (
          <ResponsiveContainer width="100%" height={400}>
            <RechartsAreaChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="name" />
              <YAxis />
              <Tooltip />
              <Legend />
              <Area type="monotone" dataKey="value" stroke="#8884d8" fill="#8884d8" name={database.fields.find(f => f.id === yAxisField)?.name || 'Valor'} />
            </RechartsAreaChart>
          </ResponsiveContainer>
        );

      case 'pie':
      case 'donut':
        return (
          <ResponsiveContainer width="100%" height={400}>
            <RechartsPieChart>
              <Pie
                data={chartData}
                cx="50%"
                cy="50%"
                labelLine={false}
                label={({ name, percent }) => `${name}: ${(percent * 100).toFixed(0)}%`}
                outerRadius={chartType === 'donut' ? 120 : 150}
                innerRadius={chartType === 'donut' ? 60 : 0}
                fill="#8884d8"
                dataKey="value"
              >
                {chartData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                ))}
              </Pie>
              <Tooltip />
            </RechartsPieChart>
          </ResponsiveContainer>
        );

      default:
        return null;
    }
  };

  return (
    <div className="p-4 space-y-4">
      <div className="flex flex-wrap gap-4 items-center justify-between bg-muted/30 p-4 rounded-lg">
        <div className="flex gap-2">
          {chartTypes.map(({ type, icon: Icon, label }) => (
            <Button
              key={type}
              variant={chartType === type ? 'default' : 'outline'}
              size="sm"
              onClick={() => handleChartTypeChange(type)}
              disabled={isLocked}
              title={label}
            >
              <Icon className="h-4 w-4 mr-2" />
              {label}
            </Button>
          ))}
        </div>

        <div className="flex gap-4 items-center">
          <div className="flex items-center gap-2">
            <span className="text-sm font-medium">Eixo X:</span>
            <Select value={xAxisField} onValueChange={handleXAxisChange} disabled={isLocked}>
              <SelectTrigger className="w-40">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {database.fields.map(field => (
                  <SelectItem key={field.id} value={field.id}>
                    {field.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {(chartType === 'bar' || chartType === 'line' || chartType === 'area') && (
            <div className="flex items-center gap-2">
              <span className="text-sm font-medium">Eixo Y:</span>
              <Select value={yAxisField} onValueChange={handleYAxisChange} disabled={isLocked}>
                <SelectTrigger className="w-40">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {database.fields.map(field => (
                    <SelectItem key={field.id} value={field.id}>
                      {field.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          )}
        </div>
      </div>

      <div className="bg-background border border-border rounded-lg p-6">
        {renderChart()}
      </div>

      {hasData && (
        <div className="text-sm text-muted-foreground text-center">
          Mostrando {chartData.length} {chartData.length === 1 ? 'registro' : 'registros'}
        </div>
      )}
    </div>
  );
};

src/hooks/useBankingData.ts.content:
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { fetchWithPluggyAuth } from "@/lib/pluggyClient";
import { Transaction, Bill } from "@/lib/financialUtils";

interface Item {
  id: string;
  connector_id: number;
  connector_name: string;
  status: string;
  execution_status: string;
  created_at: string;
  updated_at: string;
}

interface Account {
  id: string;
  type: string;
  name: string;
  balance: number;
  currencyCode: string;
  itemId: string;
}

interface HybridInvoice {
  mes: string;
  ano: number;
  mesKey: string;
  valor: number;
  fonte: 'bill' | 'calculado';
  transacoes?: number;
  detalhes?: string;
}

export function useItems() {
  return useQuery({
    queryKey: ['/api/items'],
    queryFn: async () => {
      try {
        console.log('🔄 useItems: Iniciando busca de items...');

        const syncRes = await fetchWithPluggyAuth('/api/sync-items', { method: 'POST' });
        if (syncRes.ok) {
          const syncData = await syncRes.json();
          console.log(`✨ Sincronização completa:`, syncData);
        } else {
          console.warn('⚠️ Sincronização falhou, mas continuando...');
        }

        console.log('📡 Buscando items do banco...');
        const res = await fetch('/api/items');
        if (!res.ok) {
          console.error('❌ Erro ao buscar items:', res.status, res.statusText);
          throw new Error('Failed to fetch items');
        }
        const data = await res.json();
        console.log(`📦 ${data.length} item(s) carregados do cache:`, data);
        return data as Item[];
      } catch (error) {
        console.error('❌ Erro completo no useItems:', error);
        throw error;
      }
    },
    staleTime: 5 * 60 * 1000,
  });
}

export function useAccounts(itemId: string | null) {
  return useQuery({
    queryKey: itemId ? [`/api/pluggy/items/${itemId}/accounts`] : null,
    queryFn: async () => {
      if (!itemId) return [];
      const res = await fetchWithPluggyAuth(`/api/pluggy/items/${itemId}/accounts`);
      if (!res.ok) throw new Error('Failed to fetch accounts');
      const data = await res.json();
      console.log(`🏦 ${data.length} conta(s) carregadas do cache`);
      return data as Account[];
    },
    enabled: !!itemId,
    staleTime: Infinity,
  });
}

export function useTransactions(accountId: string | null) {
  return useQuery({
    queryKey: accountId ? [`/api/pluggy/transactions/${accountId}`] : null,
    queryFn: async () => {
      if (!accountId) return [];

      const allTransactions: Transaction[] = [];
      let currentPage = 1;
      const maxPages = 20;

      while (currentPage <= maxPages) {
        const res = await fetchWithPluggyAuth(
          `/api/pluggy/transactions?accountId=${accountId}&page=${currentPage}`
        );

        if (!res.ok) break;

        const data = await res.json();
        const transactions = data.results || [];

        if (transactions.length === 0) break;

        allTransactions.push(...transactions);

        if (currentPage >= data.totalPages) break;
        currentPage++;
      }

      console.log(`✅ ${allTransactions.length} transações carregadas do cache`);
      return allTransactions;
    },
    enabled: !!accountId,
    staleTime: Infinity,
  });
}

export function useBills(accountId: string | null) {
  return useQuery({
    queryKey: accountId ? [`/api/pluggy/bills/${accountId}`] : null,
    queryFn: async () => {
      if (!accountId) return [];

      const res = await fetchWithPluggyAuth(`/api/pluggy/bills?accountId=${accountId}`);
      if (!res.ok) return [];

      const data = await res.json();
      const bills = data.results || [];
      console.log(`📊 ${bills.length} faturas (bills) carregadas do cache`);
      return bills as Bill[];
    },
    enabled: !!accountId,
    staleTime: Infinity,
  });
}

export function useHybridInvoices(accountId: string | null) {
  return useQuery({
    queryKey: accountId ? [`/api/pluggy/faturas-hibridas/${accountId}`] : null,
    queryFn: async () => {
      if (!accountId) return [];

      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 30000);

      const response = await fetchWithPluggyAuth(`/api/pluggy/faturas-hibridas/${accountId}`, {
        signal: controller.signal
      });
      clearTimeout(timeoutId);

      if (!response.ok) return [];

      const data = await response.json();
      console.log(`✅ ${data.faturas?.length || 0} faturas híbridas carregadas do cache`);
      return (data.faturas || []) as HybridInvoice[];
    },
    enabled: !!accountId,
    staleTime: Infinity,
  });
}

export function useRefreshData() {
  const queryClient = useQueryClient();

  return {
    refreshAll: () => {
      console.log('🔄 Invalidando todos os caches...');
      queryClient.invalidateQueries();
    },
    refreshItems: () => {
      console.log('🔄 Invalidando cache de items...');
      queryClient.invalidateQueries({ queryKey: ['/api/items'] });
    },
    refreshAccounts: (itemId: string) => {
      console.log('🔄 Invalidando cache de contas...');
      queryClient.invalidateQueries({ queryKey: [`/api/pluggy/items/${itemId}/accounts`] });
    },
    refreshTransactions: (accountId: string) => {
      console.log('🔄 Invalidando cache de transações...');
      queryClient.invalidateQueries({ queryKey: [`/api/pluggy/transactions/${accountId}`] });
    },
    refreshInvoices: (accountId: string) => {
      console.log('🔄 Invalidando cache de faturas...');
      queryClient.invalidateQueries({ queryKey: [`/api/pluggy/faturas-hibridas/${accountId}`] });
    },
  };
}

src/components/notion/PageOptionsMenu.ts.content:
import { useNotionStore } from '@/stores/notionStore';
import { Button } from '@/components/ui/button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
  DropdownMenuCheckboxItem,
} from '@/components/ui/dropdown-menu';
import {
  MoreHorizontal,
  Link2,
  Copy,
  Trash2,
  Type,
  Maximize,
  Lock,
  Undo,
  Download,
  Upload,
  FileText,
  Image as ImageIcon,
  X,
  LayoutGrid,
} from 'lucide-react';
import { toast } from 'sonner';
import { useState } from 'react';
import { CoverGalleryDialog } from './CoverGalleryDialog';
import { ExportOptionsDialog } from './ExportOptionsDialog';
import { MoveToBoardDialog } from './MoveToBoardDialog';

export const PageOptionsMenu = () => {
  const {
    getCurrentPage,
    updatePage,
    duplicatePage,
    deletePage,
    exportData,
    importData,
  } = useNotionStore();

  const currentPage = getCurrentPage();
  const [showCoverDialog, setShowCoverDialog] = useState(false);
  const [showExportDialog, setShowExportDialog] = useState(false);
  const [showMoveToBoardDialog, setShowMoveToBoardDialog] = useState(false);

  if (!currentPage) return null;

  const handleCopyLink = () => {
    const url = window.location.href;
    navigator.clipboard.writeText(url);
    toast.success('Link copiado para área de transferência');
  };

  const handleDuplicate = () => {
    duplicatePage(currentPage.id);
    toast.success('Página duplicada');
  };

  const handleMoveToTrash = () => {
    if (confirm(`Tem certeza que deseja mover "${currentPage.title}" para a lixeira?`)) {
      deletePage(currentPage.id);
      toast.success('Página movida para lixeira');
    }
  };

  const handleFontChange = (font: 'sans' | 'serif' | 'mono') => {
    updatePage(currentPage.id, { fontStyle: font });
    toast.success(`Fonte alterada para ${font === 'sans' ? 'Padrão' : font === 'serif' ? 'Serifada' : 'Mono'}`);
  };

  const handleToggleSmallText = () => {
    updatePage(currentPage.id, { smallText: !currentPage.smallText });
  };

  const handleToggleFullWidth = () => {
    updatePage(currentPage.id, { fullWidth: !currentPage.fullWidth });
  };

  const handleToggleLock = () => {
    updatePage(currentPage.id, { locked: !currentPage.locked });
    toast.success(currentPage.locked ? 'Página desbloqueada' : 'Página bloqueada');
  };

  const handleExport = () => {
    setShowExportDialog(true);
  };

  const handleMoveToBoard = () => {
    setShowMoveToBoardDialog(true);
  };

  const handleImport = () => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'application/json';
    input.onchange = (e) => {
      const file = (e.target as HTMLInputElement).files?.[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = (event) => {
        const data = event.target?.result as string;
        importData(data);
        toast.success('Dados importados com sucesso');
      };
      reader.readAsText(file);
    };
    input.click();
  };

  const handleAddCover = () => {
    setShowCoverDialog(true);
  };

  const handleSelectCover = (coverUrl: string) => {
    updatePage(currentPage.id, { cover: coverUrl });
    toast.success('Capa adicionada');
  };

  const handleSelectGradient = (gradient: string) => {
    updatePage(currentPage.id, { cover: gradient });
    toast.success('Capa adicionada');
  };

  const handleUploadFile = () => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'image/*';
    input.onchange = (e) => {
      const file = (e.target as HTMLInputElement).files?.[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = (event) => {
        const dataUrl = event.target?.result as string;
        updatePage(currentPage.id, { cover: dataUrl });
        toast.success('Capa adicionada do arquivo');
      };
      reader.readAsDataURL(file);
    };
    input.click();
  };

  const handleRemoveCover = () => {
    updatePage(currentPage.id, { cover: undefined });
    toast.success('Capa removida');
  };

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button variant="ghost" size="sm">
          <MoreHorizontal className="h-4 w-4" />
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-56">
        {!currentPage.cover ? (
          <DropdownMenuItem onClick={handleAddCover}>
            <ImageIcon className="mr-2 h-4 w-4" />
            Adicionar capa
          </DropdownMenuItem>
        ) : (
          <DropdownMenuItem onClick={handleRemoveCover}>
            <X className="mr-2 h-4 w-4" />
            Remover capa
          </DropdownMenuItem>
        )}

        <DropdownMenuSeparator />

        <DropdownMenuSub>
          <DropdownMenuSubTrigger>
            <Type className="mr-2 h-4 w-4" />
            Estilo de fonte
          </DropdownMenuSubTrigger>
          <DropdownMenuSubContent>
            <DropdownMenuItem onClick={() => handleFontChange('sans')}>
              <span className="font-sans font-medium">Padrão</span>
            </DropdownMenuItem>
            <DropdownMenuItem onClick={() => handleFontChange('serif')}>
              <span className="font-serif font-medium">Serifada</span>
            </DropdownMenuItem>
            <DropdownMenuItem onClick={() => handleFontChange('mono')}>
              <span className="font-mono font-medium">Mono</span>
            </DropdownMenuItem>
          </DropdownMenuSubContent>
        </DropdownMenuSub>

        <DropdownMenuSeparator />

        <DropdownMenuItem onClick={handleCopyLink}>
          <Link2 className="mr-2 h-4 w-4" />
          Copiar link
          <span className="ml-auto text-xs text-muted-foreground">Ctrl+Alt+L</span>
        </DropdownMenuItem>

        <DropdownMenuItem onClick={handleDuplicate}>
          <Copy className="mr-2 h-4 w-4" />
          Duplicar
          <span className="ml-auto text-xs text-muted-foreground">Ctrl+D</span>
        </DropdownMenuItem>

        <DropdownMenuItem onClick={handleMoveToTrash}>
          <Trash2 className="mr-2 h-4 w-4" />
          Mover para a lixeira
        </DropdownMenuItem>

        <DropdownMenuSeparator />

        <DropdownMenuCheckboxItem
          checked={currentPage.smallText || false}
          onCheckedChange={handleToggleSmallText}
        >
          Texto pequeno
        </DropdownMenuCheckboxItem>

        <DropdownMenuCheckboxItem
          checked={currentPage.fullWidth || false}
          onCheckedChange={handleToggleFullWidth}
        >
          <Maximize className="mr-2 h-4 w-4" />
          Largura completa
        </DropdownMenuCheckboxItem>

        <DropdownMenuCheckboxItem
          checked={currentPage.locked || false}
          onCheckedChange={handleToggleLock}
        >
          <Lock className="mr-2 h-4 w-4" />
          Bloquear página
        </DropdownMenuCheckboxItem>

        <DropdownMenuSeparator />

        <DropdownMenuItem onClick={handleImport}>
          <Upload className="mr-2 h-4 w-4" />
          Importar
        </DropdownMenuItem>

        <DropdownMenuItem onClick={handleMoveToBoard}>
          <LayoutGrid className="mr-2 h-4 w-4" />
          Mover para Quadro
        </DropdownMenuItem>

        <DropdownMenuItem onClick={handleExport}>
          <Download className="mr-2 h-4 w-4" />
          Exportar
        </DropdownMenuItem>
      </DropdownMenuContent>

      <CoverGalleryDialog
        open={showCoverDialog}
        onOpenChange={setShowCoverDialog}
        onSelectCover={handleSelectCover}
        onSelectGradient={handleSelectGradient}
        onUploadFile={handleUploadFile}
      />

      <MoveToBoardDialog
        open={showMoveToBoardDialog}
        onOpenChange={setShowMoveToBoardDialog}
        pageTitle={currentPage.title}
        pageData={exportData()}
      />

      <ExportOptionsDialog
        open={showExportDialog}
        onOpenChange={setShowExportDialog}
        pageTitle={currentPage.title}
        pageData={exportData()}
      />
    </DropdownMenu>
  );
};

