  // ===== MONITORING CONFIGURATION =====

  app.get("/api/config/monitoring", authenticateConfig, async (req, res) => {
    try {
      const configFromDb = await db.select().from(monitoringConfig).limit(1);

      if (configFromDb[0]) {
