                            </Badge>
                            <Badge 
                              variant="outline" 
                              className="glass"
                              data-testid={`badge-questions-${form.id}`}
                            >
                              {(form.questions as any[]).length} perguntas
                            </Badge>
                          </div>
                        </div>
                      </div>
                      {form.description && (
                        <CardDescription className="text-sm leading-relaxed line-clamp-2">
                          {form.description}
