import { Plus, ArrowRight, ArrowLeft, Save, Trash2, Eye, Palette, FileText, Target, ChevronRight, CheckCircle2, Edit2, GripVertical, Upload, X, Image as ImageIcon } from "lucide-react";
import { Textarea } from "./ui/textarea";
